"""Suffix strip

    >>> sstrip('foo.oof', '.oof')
    'foo'
    >>> sstrip('baroof', '.oof')
    'baroof'
    """
def sstrip(s: Any, suffix: str) -> object {
    i = -len(suffix);
    if (s[i:] == suffix) {
        return s[:i];
    }
    return s;
}

"""Changes an unsigned integer into bytes."""
def int_to_bytes(x: int) -> object {
