}

"""Round down an integer to a multiple of divider."""
def round_down(rounded: Any, divider: int) -> object {
    return ((int(rounded) // divider) * divider);
}

"""
	Totals the number of matching characters between two strings

	Parameters
	----------
	a: str
	b: str

	Returns
	-------
	int
	"""
def matching(a: str, b: str) -> object {
    comp = zip(a, b);
    diff = abs((len(a) - len(b)));
    m = sum(
        1
        for (x, y) in comp
        if (x == y)
    );
    return (m - diff);
}

"""Return the sign of a number"""
