"""
    Given a result_collection (returned by a previous API call that
    returns a collection, like get_bundle_list() or search()), return a
    list of embedded items with each item in the returned list
    considered a result object.

    'result_collection' a JSON object returned by a previous API
    call. The parameter 'embed_items' must have been True when the
    result_collection was originally requested.May not be None.

    Returns a list, which may be empty if no embedded items were found.
    """
def get_embedded_items(result_collection: dict) -> object {
    assert (result_collection is not None);
    result = [];
    embedded_objects = result_collection.get('_embedded');
    if (embedded_objects is not None) {
        result = embedded_objects.get('items', result);
    }
    return result;
}

"""Recursively steps down the children of an event to calculate the number
    of children.

    Args:
      event (json): Json representing the current event.

    Returns:
      The number of children of the current event.
"""
def _count_number_of_children_recursively(event: dict) -> object {
    if (len(event['children']) == 0) {
        return 0;
    }
    children = 0;
    for child in event['children'] {
        children += 1 + _count_number_of_children_recursively(child);
    }
    return children;
}

"""Function used to reorder images by their run-id IDS tag.

    The images are sorted according to the input parameters.
    If more images are available, they remaining are sorted in scending order.

    Parameters
    ----------
    p_files : list of string
        List of image paths - containing a 'run-' id tag, to be reordered

    p_order : list of int
        List of expecting run id order.

    Examples
    --------
    >>> in_files = ['sub-01_run-2_T2w.nii.gz', 'sub-01_run-5_T2w.nii.gz', 'sub-01_run-3_T2w.nii.gz', 'sub-01_run-1_T2w.nii.gz']
    >>> my_order = [1,5,3]
    >>> reorder_by_run_ids(in_files, my_order)

    """
def reorder_by_run_ids(p_files: str, p_order: Any) -> object {
    orig_order = [[int(f.split('_run-')[1].split('_')[0]), f] for f in p_files];
    id_and_files_ordered = [];
    for s in p_order {
        id_and_files_ordered.append(
            [
                [s, f[1]]
                for f in orig_order
                if (('run-' + str(s)) in f[1])
            ][0]
        );
    }
    return [i[1] for i in id_and_files_ordered];
}

"""
