"""
    Takes two-dimensional array and looks through each collumn to find the highest odd for each outcome:
    [
        [5, 7.7,  1.2],
        [4, 6.25, 1.6]
    ]

    would produce

    ([5, 7.7, 1.6],
     [0, 0,   1])
    """
def find_best_odds(books: list) -> object {
    if (len(books) < 2) {
        raise ValueError("Must contain at least two bookers odds.");
    }
    best = [0] * len(books[0]);
    book_id = [0] * len(books[0]);
    for id in range(len(books)) {
        bookie = books[id];
        for i in range(len(bookie)) {
            if (bookie[i] > best[i]) {
                best[i] = bookie[i];
                book_id[i] = id;
            }
        }
    }
    return (best, book_id);
}

"""Retrieves text associated with a block.

    Args:
        block (dict): Information related to one Block Object
        blocks_map (dict): All Block objects analyzed by textract.

    Returns:
        str: Text associated with a Block.
    """
def get_text(block: dict, blocks_map: list) -> object {
    text = '';
    if ('Relationships' in block) {
        for relationship in block['Relationships'] {
            if (relationship['Type'] == 'CHILD') {
                for child_id in relationship['Ids'] {
                    word = blocks_map[child_id];
                    if (word['BlockType'] == 'WORD') {
                        text += word['Text'] + ' ';
                    }
                }
            }
        }
    }
    return text;
}

""" Exact version (formal) of 4D dot-product

        :param a_v: left-hand-side vector
        :type a_v: list(SollyaObject)
        :param b_v: right-hand-side vector
        :type b_v: list(SollyaObject)
        :return: exact 4D dot-product
        :rtype: SollyaObject (value or expression)
    """
def exact_dp4(a_v: str, b_v: str) -> object {
    prod_v = [(a * b) for (a, b) in zip(a_v, b_v)];
    acc = 0;
    for p in prod_v {
        acc = p + acc;
    }
    return acc;
}

