"""Return substring from a text based on start and end substrings delimited by ::."""
def get_fragment(text: list, startend: str) -> object {
    startend = (startend.split("::") as str);
    if ((startend[0] not in text) or (startend[1] not in text)) {
        return;
    }
    start_idx = text.index(startend[0]);
    end_idx = text.index(startend[1]);
    if (end_idx < start_idx) {
        return;
    }
    return text[start_idx:(end_idx + len(startend[1]))];
}

"""
    Intermediate top reward.
    """
def calcTopReward(top_action: list, gold_labels: str) -> object {
    lenth = len(top_action);
    r = [0.0 for i in range(lenth)];
    rem = [0 for i in range(len(gold_labels))];
    for i in range(lenth)[::-1] {
        if (top_action[i] > 0) {
            ok = -1;
            for (j, label) in enumerate(gold_labels) {
                if (label['type'] == top_action[i]) {
                    if (rem[j] == 0) {
                        ok = 1;
                        rem[j] = 1;
                        break;
                    } else {
                        ok = (-0.2 as int);
                    }
                }
            }
            r[i] = ok;
        }
    }
    return r;
}

"""Converts n bits to a human readable format."""
def bits2human(n: int, format: str = "%(value).1f%(symbol)s") -> str {
    symbols = ('B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB', 'ZiB', 'YiB');
    prefix: dict[str, int] = {};
    prefix['B'] = 8;
    for (i, s) in enumerate(symbols[1:]) {
        prefix[s] = ((1024 ** (i + 1)) * 8 as int);
    }
    for symbol in reversed(symbols) {
        if n >= prefix[symbol] {
            value = float(n) / prefix[symbol];
            return format % locals();
        }
    }
    return format % dict(symbol=symbols[0], value=n);
}

