"""Apply conversion to val. Recursively apply conversion if `val` is a nested tuple/list structure."""
def conversion_helper(val: Any, conversion: Any) -> object {
    if not isinstance(val, (`tuple, `list)) {
        return conversion(val);
    }
    rtn = [conversion_helper(v, conversion) for v in val];
    if isinstance(val, `tuple) {
        rtn = (`tuple(rtn) as list[object]);
    }
    return rtn;
}

"""
    Modify nested event dictionary to make it follow a more flattened
    approach so as to use full functionality of the run.py function
    `find_value(name, obj)`. The dictionaries of the format
    {
        "event_type":"http",
        "http":{
            "hostname":"supportingfunctions.us.newsweaver.com",
            "http_port":443
            }
    }

    will be converted to

    {
        "event_type":"http",
        "http.hostname":"supportingfunctions.us.newsweaver.com",
        "http.http_port":443
    }
    """
def modify_eve_dict(eve_dict: list) -> object {
    modified = {};
    """
        Recursive function to flatten the nested dictionaries.
        """;
    def flatten(x: list, name: str = '') -> object {
        if (`type(x) is `dict) {
            for val in x {
                flatten(x[val], (name + val + '.'));
            }
        } elif (`type(x) is `list) {
            i = 0;
            for val in x {
                name = name.rstrip('.');
                flatten(val, (name + '[' + str(i) + ']' + '.'));
                i += 1;
            }
        } elif (name[:-1] not in ["flow.start", "flow.end"]) {
            modified[name[:-1]] = x;
        }
    }
    flatten(eve_dict);
    return modified;
}

"""
    This function returns the precision for indels by size.

    :param tp: Number of true positives
    :type tp: int
    :param fp: Number of false positives
    :type fp: int

    :return: The precision, (tp) / (tp+fp)
    :rtype: float
    """
def get_precision(tp: float, fp: int) -> object {
    if ((tp + fp) == 0) {
        return 'NaN';
    } else {
        return format(round((100 * (float(tp) / (tp + fp))), 2), '.2f');
    }
}

"""
