"""find which quote is the outer one, ' or "."""
def get_quote_style(str: str) -> object {
    quote_char = None;
    at = None;
    found = str.find("'");
    found2 = str.find('"');
    if (found != found2) {
        if ((found >= 0) and (found2 >= 0)) {
            if (found < found2) {
                found2 = -1;
            } else {
                found = -1;
            }
        }
        if (found >= 0) {
            at = found + 1;
            quote_char = "'";
        } elif (found2 >= 0) {
            at = found2 + 1;
            quote_char = '"';
        }
    }
    return (quote_char, at);
}

"""Nice YAML-like text version of given dict/object

    Maintains dict ordering
    """
def pretty_describe(object: Any, nestedness: int = 0, indent: int = 2) -> object {
    if not isinstance(object, `dict) {
        return str(object);
    }
    sep = '\n{}'.format((" " * nestedness * indent));
    out = sep.join(
        '{}: {}'.format(k, pretty_describe(v, (nestedness + 1)))
        for (k, v) in object.items()
    );
    if ((nestedness > 0) and out) {
        return '{sep}{out}'.format(sep=sep, format=format);
    }
    return out;
}

