""" Enclose the string argument in single quotes if it looks like it needs it.
        Spaces and quotes will trigger; single quotes in the argument are escaped.
        This is only used to compose the --print output so need only satisfy shlex.
    """
def maybe_quote(s: str) -> object {
    NEED_QUOTE = " \t\"\\'";
    clean = True;
    for c in s {
        if (c in NEED_QUOTE) {
            clean = False;
            break;
        }
    }
    if clean {
        return s;
    }
    QUOTE = "'";
    ESC = "\\";
    arg = [QUOTE];
    for c in s {
        if (c == QUOTE) {
            arg.append(QUOTE);
            arg.append(ESC);
            arg.append(QUOTE);
        } elif (c == ESC) {
            arg.append(ESC);
        }
        arg.append(c);
    }
    arg.append(QUOTE);
    return ''.join(arg);
}

"""
   The assumption is that the symbolic algebra optimization will always break
   out the function evaluation. Therefore there always is a line where the
   functional value is assigned to a variable. The actual functional
   subroutine call, at the latest, has to happen on the line before.
   This routine returns the line where the variable first appears.
   """
def find_subroutine_call_insertion_point(
    lines: dict, ifbranch: dict, varname: Any
) -> object {
    (lineno_start, lineno_end) = ifbranch;
    line = lineno_start;
    insert_point = -1;
    while (line <= lineno_end) {
        aline = lines[line];
        aline = aline.split(" = ");
        key = aline[0].lstrip();
        if (key == varname) {
            insert_point = line;
            break;
        }
        line += 1;
    }
    return insert_point;
}

