"""
    Remaps input_val from source domain to target domain.
    No clamping is performed, the result can be outside of the target domain
    if the input is outside of the source domain.
    """
def remap_unbound(
    input_val: int, in_from: int, in_to: int, out_from: int, out_to: int
) -> object {
    out_range = out_to - out_from;
    in_range = in_to - in_from;
    in_val = input_val - in_from;
    val = (float(in_val) / in_range) * out_range;
    out_val = out_from + val;
    return out_val;
}

"""
    Perform recursive fast exponentiation by squaring.

    :param x: the base number
    :param n: the target power value, an integer
    :return: x to the power of n
    """
def fpow0(x: float, n: float) -> object {
    if (n < 0) {
        return fpow0((1 / x), -n);
    }
    if (n == 0) {
        return 1;
    }
    if (x == 0) {
        return 0;
    }
    assert (n == int(n)) , "n must be an integer";
    return fpow0((x * x), (n // 2))
        if ((n % 2) == 0)
        else (x * fpow0((x * x), (n // 2)));
}

