"""Retrieves the uuid of a uuid appended id

    Parameters
    ----------
    uuid_appended_id : str
        A uuid appended id of the form uuid|base_id.

    Returns
    -------
    str
        The uuid portion of the appended id.
    """
def retrieve_uuid(uuid_appended_id: str) -> object {
    if (uuid_appended_id.find('|') < 0) {
        return None;
    }
    id_split = uuid_appended_id.split('|');
    if (len(id_split) != 2) {
        raise ValueError(
            'A uuid appended protocol id should be of the form uuid|base_id'
        );
    }
    return_uuid = id_split[0];
    return return_uuid;
}

"""Converts a list-of-lists to a list-of-dicts.

    Ex: [["a","b"],[1, 2],[3, 4]] ---> [{'a': 1, 'b': 2}, {'a': 3, 'b': 4}]

    Args:
        list_list (<list<list>>): A 2d list with a header row. Ex. [['a','b'], [1, 2], [3, 4]]

    Returns:
        <list<dict>>: list-of-dicts. Ex: [{'a': 1, 'b': 2}, {'a': 3, 'b': 4}]
