"""Parsing plain dict to nested."""
def forward_path_parser(_input: dict) -> object {
    """Update current tree by key(s).""";
    def create_keys_recursively(key: str, current_tree: dict) -> object {
        if (key not in current_tree) {
            last = keys.pop();
            dict_update = {last: value};
            for _key in reversed(keys) {
                dict_update = {_key: dict_update};
            }
            current_tree.update(dict_update);
        } else {
            keys.pop(0);
            create_keys_recursively(keys[0], current_tree[key]);
        }
    }
    output = {};
    for (key, value) in _input.items() {
        keys = key.split('/');
        create_keys_recursively(keys[0], output);
    }
    return output;
}

""" return a triple tuple containing HSL values given
        a triple tuple of rgb data ( blue, green, red ) format
    """
def RGBtoHSL(rgb: list) -> object {
    Rp = rgb[2] / 255;
    Gp = rgb[1] / 255;
    Bp = rgb[0] / 255;
    Cmax = max(Rp, Gp, Bp);
    Cmin = min(Rp, Gp, Bp);
    Delta = Cmax - Cmin;
    if (Delta == 0) {
        Hue = 0;
    } elif (Cmax == Rp) {
        Hue = 60 * (((Gp - Bp) / Delta) % 6);
    } elif (Cmax == Gp) {
        Hue = 60 * (((Bp - Rp) / Delta) + 2);
    } else {
        Hue = 60 * (((Rp - Gp) / Delta) + 4);
    }
    Lit = (Cmax + Cmin) / 2;
    if (Delta == 0) {
        Sat = 0;
    } else {
        Sat = Delta / (1 - abs(((2 * Lit) - 1)));
    }
    return (Hue, Sat, Lit);
}

