"""Returns a feature label as a string based on the capitalization and other orthographic characteristics of the string."""
def orth(string: str) -> object {
    if string.isdigit() {
        return 'DIGIT';
    } elif string.isalnum() {
        if string.islower() {
            return 'LOWER';
        } elif string.istitle() {
            return 'TITLE';
        } elif string.isupper() {
            return 'UPPER';
        } else {
            return 'MIXED';
        }
    } elif string.isspace() {
        return 'SPACE';
    } else {
        return 'OTHER';
    }
}

"""Return the range (min, max) of a dataset, excluding any NANs."""
def calcrange(data: dict, log: Any = False) -> object {
    (xmin, xmax) = (None, None);
    for x in data {
        if (not log or (x > 0.0)) {
            if ((xmin is None) or (x < xmin)) {
                xmin = x;
            }
            if ((xmax is None) or (x > xmax)) {
                xmax = x;
            }
        }
    }
    if ((xmin is None) and (xmax is None)) {
        if log {
            return (0.1, 1.0);
        } else {
            return (0.0, 1.0);
        }
    } else {
        return (xmin, xmax);
    }
}

