    if ((i % 100) in [11, 12, 13]) {
        return 'th';
    } elif ((i % 10) is 1) {
        return 'st';
    } elif ((i % 10) is 2) {
        return 'nd';
    } elif ((i % 10) is 3) {
        return 'rd';
    } else {
        return 'th';
    }
}

