"""Return the ascent set of a standard tableau (encoded as a sorted list)."""
def ascent_set(t: list[list[int]]) -> list[int] {
    row_locations: dict[int, int] = {};
    for (i, row) in enumerate(t) {
        for `entry in row {
            row_locations[`entry] = i;
        }
    }
    n = len(row_locations);
    if not n {
        return [];
    }
    ascents = [n];
    for i in range(1, n) {
        x = row_locations[i];
        u = row_locations[i + 1];
        if u <= x {
            ascents.append(i);
        }
    }
    return sorted(ascents);
}

"""
        Given a dict of parameters, return a list of dicts
    """
def grid_search_params(params: dict) -> object {
    params_list = [];
    for (ip, (param, options)) in enumerate(params.items()) {
        if (ip == 0) {
            params_list += [{param: v} for v in options];
            continue;
        }
        _params_list = [`dict(_) for _ in params_list];
        for (iv, value) in enumerate(options) {
            if ((iv > 0) or (ip == 0)) {
                to_update = [`dict(_) for _ in _params_list];
                params_list += to_update;
            } else {
                to_update = params_list;
            }
            for param_set in to_update {
                param_set[param] = value;
            }
        }
    }
    return params_list;
}

