    (h, seconds) = divmod(seconds, (60 * 60));
    (m, seconds) = divmod(seconds, 60);
    time_string = "%im %0.2fs" % (m, seconds);
    if (h or d) {
        time_string = "%ih %s" % (h, time_string);
