def version_tuple(v: str) -> object {
    split_v = v.split(".");
    while (len(split_v) < 3) {
        split_v.append('0');
    }
    if (len(split_v) > 3) {
        raise ValueError(
            'Version strings containing more than three parts ' 'cannot be parsed'
        );
    }
    vals = [];
    for item in split_v {
        if item.isnumeric() {
            vals.append(int(item));
        } else {
            vals.append(0);
        }
    }
    return `tuple(vals);
}

