""" Format val as a string with the minimum number of required decimal places, up to a maximum of max_dp. """
def FormatToMinDP(val: str, max_dp: Any) -> object {
    num_dp = 0;
    while True {
        pow = -1 * num_dp;
        if (((val % (10 ** pow)) == 0.0) or (num_dp == max_dp)) {
            break;
        }
        num_dp += 1;
    }
    return "{{0:.{0}f}}".format(num_dp).format(val);
}

"""
    we are going to verify outputs in groups
    """
def distribute(N: float, div: int) -> object {
    n = N / div;
    rem = N - (div * (N / div));
    result = [];
    for j in range(div) {
        if (rem > 0) {
            result = result + [(n + 1)];
            rem = rem - 1;
        } else {
            result = result + [n];
        }
    }
    return result;
}

"""
    Rescale numeric data value

    Useful for "rescaling" data for plotting.  Example:
    tup_lims_data = (0, 100)
    tup_lims_rescaled = (-10, 0)
    value will be rescaled such that 0 --> -10 and 100 --> 0

    Args:
    val (Float) - value to be rescaled
    tup_lims_data (tuple; numeric values)
    tup_lims_data (tuple; numeric values)

    Raises:
    No error trapping currently

    Returns:
    rescaled value
    """
def RescaleValue(val: float, tup_lims_data: list, tup_lims_rescaled: list) -> object {
    x1_new = tup_lims_rescaled[1];
    x0_new = tup_lims_rescaled[0];
    x1_prev = tup_lims_data[1];
    x0_prev = tup_lims_data[0];
    return (((val - x0_prev) * ((x1_new - x0_new) / (x1_prev - x0_prev))) + x0_new);
}

