}

"""
    Find an index of ``needle`` in ``haystack`` by looking for exact same item by pointer ids
    vs usual ``list.index()`` which finds by object comparison.

    For example::

        >>> a = {}
        >>> b = {}
        >>> haystack = [1, a, 2, b]
        >>> indexof(b, haystack)
        3
        >>> indexof(None, haystack)
        Traceback (most recent call last):
        ...
        ValueError: None is not in [1, {}, 2, {}]
    """
def indexof(needle: Any, haystack: str) -> object {
    for (i, item) in enumerate(haystack) {
        if (needle is item) {
            return i;
        }
    }
    raise ValueError("{!r} is not in {!r}".format(needle, haystack));
}

"""
    The complement of load_fields().
    @param obj          Source object to read
    @param fields       Field definition list
    @return             List of data fields suitable for a binary pack
    """
def unload_fields(`obj: Any, fields: dict) -> object {
    data = [];
    for field in fields {
        value = 0;
        for (name, desc) in field.items() {
            if (hasattr(`obj, name) == True) {
                value |= getattr(`obj, name) << desc[1];
            }
        }
        data.append(value);
    }
    return data;
}

