"""when a title is required, generate one from the value"""
def text_to_title(value: str) -> object {
    title = None;
    if not value {
        return title;
    }
    words = value.split(" ");
    keep_words = [];
    for word in words {
        if (word.endswith(".") or word.endswith(":")) {
            keep_words.append(word);
            if ((len(word) > 1) and ("<italic>" not in word) and ("<i>" not in word)) {
                break;
            }
        } else {
            keep_words.append(word);
        }
    }
    if (len(keep_words) > 0) {
        title = " ".join(keep_words);
        if (title.split(" ")[-1] != "spp.") {
            title = title.rstrip(" .:");
        }
    }
    return title;
}

"""
    s: <number>[<k|m|g|t>]
    Returns the number of bytes.
    """
def parse_size(s: int) -> object {
    try {
        if s[-1].isdigit() {
            return int(s);
        }
        (n, unit) = (float(s[0:-1]), s[-1].lower());
        if (unit == 'k') {
            return int((n * 1024));
        }
        if (unit == 'm') {
            return int((n * 1024 * 1024));
        }
        if (unit == 'g') {
            return int((n * 1024 * 1024 * 1024));
        }
        if (unit == 't') {
            return int((n * 1024 * 1024 * 1024 * 1024));
        }
    } except (IndexError, ValueError) {
        ;
    }
    raise ValueError(('Invalid size: %s, expected <number>[<k|m|g|t>]' % s));
}

