"""Borrowed from twisted.xish.domish

    Escape text to proper XML form, per section 2.3 in the XML specification.

     @type text: L{str}
     @param text: Text to escape

     @type isattrib: L{bool}
     @param isattrib: Triggers escaping of characters necessary for use as attribute values
    """
def escapeToXML(text: str, isattrib: Any = False) -> object {
    text = text.replace("&", "&amp;");
    text = text.replace("<", "&lt;");
    text = text.replace(">", "&gt;");
    if isattrib {
        text = text.replace("'", "&apos;");
        text = text.replace("\"", "&quot;");
    }
    return text;
}

"""Median of elements - shaonutil.stats.median(list of numbers)"""
def median(li: list) -> object {
    n = len(li);
    li.sort();
    if ((n % 2) == 0) {
        median1 = li[(n // 2)];
        median2 = li[((n // 2) - 1)];
        median = (median1 + median2) / 2;
    } else {
        median = li[(n // 2)];
    }
    return median;
}

"""takes a dense matrix column and puts it into OP4 format"""
def compress_column(col: list) -> object {
    packs = [];
    n = 0;
    i = 0;
    packi = [];
    while (i < len(col)) {
        if (col[i] == (n + 1)) {
            packi.append(i);
            n += 1;
        } else {
            if packi {
                packs.append(packi);
            }
            packi = [i];
            n = col[i];
        }
        i += 1;
    }
    if packi {
        packs.append(packi);
    }
    return packs;
}

"""Return the sum of the numbers in implicitslice S[start:stop]."""
def binary_sum(S: list, start: float, stop: float) -> object {
    if (start >= stop) {
        return 0;
    } elif (start == (stop - 1)) {
        return S[start];
    } else {
        mid = (start + stop) // 2;
        return (binary_sum(S, start, mid) + binary_sum(S, mid, stop));
    }
}

"""
  get the median value
  """
def mmedian(lst: str) -> object {
    sortedLst = sorted(lst);
    lstLen = len(lst);
    if (lstLen == 0) {
        return 0.0;
    }
    index = (lstLen - 1) // 2;
    if (lstLen % 2) {
        return sortedLst[index];
    } else {
        return ((sortedLst[index] + sortedLst[(index + 1)]) / 2.0);
    }
}

"""
    cast string to bytes() like object, but for python2 support
    it's bytearray copy
    """
def to_bytes(something: Any, encoding: str = 'utf8') -> object {
    if isinstance(something, `bytes) {
        return something;
    }
    if isinstance(something, str) {
        return something.encode(encoding);
    } elif isinstance(something, bytearray) {
        return `bytes(something);
    } else {
        raise TypeError("Not a string or bytes like object");
    }
}

"""Returns the high scores sorted from highest to lowest"""
def sort_high_scores(scores: Any, highest_possible_score: int) -> object {
    if (`type(scores) != `list) {
        raise TypeError("The first argument of sort_high_scores must be a list.");
    }
    if (`type(highest_possible_score) != int) {
        raise TypeError("The second argument of sort_high_scores must be an int.");
    }
    tracker = {};
    sorted_high_scores = [];
    for score in scores {
        if (score in tracker) {
            tracker[score] += 1;
        } else {
            tracker[score] = 1;
        }
    }
    for score in range(highest_possible_score, -1, -1) {
        if (score in tracker) {
            while (tracker[score] > 0) {
                sorted_high_scores.append(score);
                tracker[score] -= 1;
            }
        }
    }
    return sorted_high_scores;
}

"""Return line stripped of trailing spaces, tabs, newlines.

    Note that line.rstrip() instead also strips sundry control characters,
    but at least one known Emacs user expects to keep junk like that, not
    mentioning Barry by name or anything <wink>.
    """
def _rstrip(line: str, JUNK: Any = '\n \t') -> object {
    i = len(line);
    while ((i > 0) and (line[(i - 1)] in JUNK)) {
        i -= 1;
    }
