"""
    calculates mill residues for a give volume of
    roundwood harvested (mmbf) amd year
    """
def me(yr: float, vol: int) -> object {
    me70 = 0.42;
    me11 = 0.48;
    ann = (me11 - me70) / (2011 - 1970);
    if (yr <= 1970) {
        return (vol * (me70 - ((1970 - yr) * ann)));
    }
    if (yr >= 1970) {
        return (vol * (me70 + ((yr - 1970) * ann)));
    }
}

