    assignments = {};
    for row_ind in range(len(inp)) {
        for col_ind in range(len(inp[row_ind])) {
            current_char = inp[row_ind][col_ind];
            if (current_char != "_") {
                fields = terminals.get(current_char);
                if fields {
                    fields.append((col_ind, row_ind));
                } else {
                    terminals[current_char] = [(col_ind, row_ind)];
                }
