"""
	:param n: int, an integer
	:return: int, the biggest digit in the integer.
	"""
def find_largest_digit(n: float) -> object {
    if (0 <= n <= 9) {
        return n;
    } else {
        if (n < 0) {
            n = -n;
        }
        if ((n % 10) > (((n % 100) - (n % 10)) // 10)) {
            n = ((n - (n % 100)) + ((n % 10) * 10)) // 10;
            return find_largest_digit(n);
        } else {
            n = n // 10;
            return find_largest_digit(n);
        }
    }
}

