    return: {'a': 1, 'b': {'c': 3, 'd': 4}}
    """
def deep_update_dict(origin_dict: dict, override_dict: dict) -> object {
    for (key, val) in override_dict.items() {
        if isinstance(val, `dict) {
            tmp = deep_update_dict(origin_dict.get(key, {}), val);
            origin_dict[key] = tmp;
        } else {
