    mirror_index = -1;
    if not symmetry_table {
        return mirror_index;
    }
    for i in range(len(symmetry_table)) {
        if (vertex_index == symmetry_table[i]) {
            if ((i % 2) == 0) {
                mirror_index = symmetry_table[(i + 1)];
            } else {
