}

"""
    Calculate group size and start index.
    """
def get_group_size_and_start(
    total_items: float, total_groups: int, group_id: float
) -> object {
    base_size = total_items // total_groups;
    rem = total_items % total_groups;
    start = (base_size * (group_id - 1)) + min((group_id - 1), rem);
    size = (base_size + 1) if (group_id <= rem) else base_size;
    return (start, size);
}

"""
    >>> short('Something wrong with compatibility regressions.'.split())
    'Som-ng wrong with com-ty reg-s.'
    >>> short('Something wrong with compatibility regressions.'.split(), True)
    'Som4ng wrong with com8ty reg7s.'
    """
def short(text: Any, count_stripped: Any = False) -> object {
    def sh(word: str) -> object {
        l = len(word);
        if (l > 7) {
            if count_stripped {
                return "{}{}{}".format(word[:3], (l - 5), word[-2:]);
            } else {
                return "{}-{}".format(word[:3], word[-2:]);
            }
        } else {
            return word;
        }
    }
    return " ".join(map(sh, text));
}

