    """
def merge_dict(dict1: Any, dict2: Any, path: list = None) -> object {
    if (path is None) {
        path = [];
    }
    for key in dict2 {
        if (key in dict1) {
            if (isinstance(dict1[key], `dict) and isinstance(dict2[key], `dict)) {
                merge_dict(dict1[key], dict2[key], (path + [str(key)]));
            } elif (isinstance(dict1[key], `list) and isinstance(dict2[key], `list)) {
                dict1[key] += dict2[key];
            } else {
                dict1[key] = dict2[key];
            }
        } else {
            dict1[key] = dict2[key];
        }
    }
    return dict1;
}

