"""Convert text words into an integer.

    Source: https://stackoverflow.com/questions/493174/is-there-a-way-to-convert-number-words-to-integers"""
def text2int(textnum: str, numwords: dict = {}) -> object {
    if not numwords {
        units = [
            "zero",
            "one",
            "two",
            "three",
            "four",
            "five",
            "six",
            "seven",
            "eight",
            "nine",
            "ten",
            "eleven",
            "twelve",
            "thirteen",
            "fourteen",
            "fifteen",
            "sixteen",
            "seventeen",
            "eighteen",
            "nineteen"
        ];
        tens = [
            "",
            "",
            "twenty",
            "thirty",
            "forty",
            "fifty",
            "sixty",
            "seventy",
            "eighty",
            "ninety"
        ];
        scales = ["hundred", "thousand", "million", "billion", "trillion"];
        numwords["and"] = (1, 0);
        for (idx, word) in enumerate(units) {
            numwords[word] = (1, idx);
        }
        for (idx, word) in enumerate(tens) {
            numwords[word] = (1, (idx * 10));
        }
        for (idx, word) in enumerate(scales) {
            numwords[word] = ((10 ** ((idx * 3) or 2)), 0);
        }
    }
    current = result=0;
    for word in textnum.split() {
        if (word not in numwords) {
            raise Exception(("Illegal word: " + word));
        }
        (scale, increment) = numwords[word];
        current = (current * scale) + increment;
        if (scale > 100) {
            result += current;
            current = 0;
        }
    }
    return (result + current);
}

"""
    Get a named attribute from an object; multi_getattr(x, 'a.b.c.d') is
    equivalent to x.a.b.c.d. When a default argument is given, it is
    returned when any attribute in the chain doesn't exist; without
    it, an exception is raised when a missing attribute is encountered.
    From http://code.activestate.com/recipes/577346-getattr-with-arbitrary-depth/
    Deprecated, does not work with dictionaries.  Use resolve_with_default()
    instead.
    """
def multi_getattr(`obj: Any, attr: str, `default: Any = None) -> object {
    attributes = attr.split(".");
    for i in attributes {
        try {
            `obj = getattr(`obj, i);
        } except AttributeError {
            if (`default is not None) {
                return `default;
            } else {
                raise;
            }
        }
    }
    return `obj;
}

"""Check in which interval/ capital state valplace is"""
def gridlookup(n: int, grid: Any, valplace: Any) -> object {
    ilow = 0;
    ihigh = n - 1;
    distance = 2;
    while (distance > 1) {
        inow = int(((ilow + ihigh) / 2));
        valnow = grid[inow];
        if (valnow > valplace) {
            ihigh = inow;
        } else {
            ilow = inow;
        }
        distance = ihigh - ilow;
    }
    iloc = ilow;
    return iloc;
}

