"""
    Function sorting input list with selection sort algorithm

    :param unsorted_list: input list with unsorted elements
    :return: copy of input list with sorted elements
    """
def selection_sort(unsorted_list: dict) -> object {
    sorted_list = unsorted_list.copy();
    for i in range(len(sorted_list)) {
        min_elem = sorted_list[i];
        min_index = i;
        for j in range(i, len(sorted_list), 1) {
            if (sorted_list[j] < min_elem) {
                min_elem = sorted_list[j];
                min_index = j;
            }
        }
        (sorted_list[i], sorted_list[min_index]) = (
            sorted_list[min_index],
            sorted_list[i]
        );
    }
    return sorted_list;
}

"""
    guess the type based on the given file name
    and returns one of teh following:

    fasta, fastq, map

    or None if no type could be detected

    @param name: the name of the file
    @type name: string
    @return: one of fasta, fastq, map or None
    @rtype: string
    """
def _guess_type(name: str) -> object {
    name = name.upper();
    if name.endswith(".GZ") {
        name = name[:-3];
    }
    if (name.endswith(".FASTA") or name.endswith("FA")) {
        return "fasta";
    } elif (name.endswith(".FASTQ") or name.endswith("FQ")) {
        return "fastq";
    } elif name.endswith(".MAP") {
        return "map";
    } elif name.endswith(".SAM") {
        return "sam";
    } elif name.endswith(".BAM") {
        return "bam";
    }
    return None;
}

