"""Returns the index of key in the list if found, -1 otherwise.
    List must be sorted."""
def binary_search(nums: list, key: Any) -> object {
    left = 0;
    right = len(nums) - 1;
    while (left <= right) {
        middle = (left + right) // 2;
        if (nums[middle] == key) {
            return middle;
        } elif (nums[middle] > key) {
            right = middle - 1;
        } elif (nums[middle] < key) {
            left = middle + 1;
        }
    }
    return -1;
}

