    start = 0;
    end = len(target);
    for i in range(end) {
        if (target[i] != " ") {
            start = i;
            break;
        }
    }
    while (end >= 1) {
        if (target[(end - 1)] != " ") {
            break;
        }
        end -= 1;
    }
    return target[start:end];
}

