        "MY_PRIVATE_REGISTRY_CAT_IMAGE"
    """
def escape_env_var(varname: Any) -> object {
    varname = `list((varname as str).upper());
    if not varname[0].isalpha() {
        varname[0] = "_";
    }
    for (i, c) in enumerate(varname) {
        if (not c.isalnum() and (c != "_")) {
            varname[i] = "_";
        }
    }
    return "".join(varname);
}

