"""
    Find right limit.
    Args:
       minpoint (int): x coordinate of the local minimum
       ds (list): list of numbers representing derivative of the time-series signal s
       tau (int): threshold to determine a slope 'too sharp'
    Returns:
       minpoint (int): x coordinate of the right-modified local minimum
    """
def rightlimit(minpoint: Any, ds: list, tau: Any) -> object {
    slope = ds[minpoint];
    while (
        (slope < tau) and (slope > 0) and (minpoint > 0) and (minpoint < (len(ds) - 1))
    ) {
        minpoint += 1;
        slope = ds[minpoint];
    }
    return minpoint;
}

"""
    :param angles: a list of angles
    :param max_positive_angle: the maximum positive angle, angles greater than this will be shifted to negative angles
    :return: list of the same angles, but none exceed the max
    :rtype: list
    """
def change_angle_origin(angles: list, max_positive_angle: Any) -> object {
    if (len(angles) == 1) {
        if (angles[0] > max_positive_angle) {
            return [(angles[0] - 360)];
        } else {
            return angles;
        }
    }
    new_angles = [];
    for angle in angles {
        if (angle > max_positive_angle) {
            new_angles.append((angle - 360));
        } elif (angle == max_positive_angle) {
            if ((angle == angles[0]) and (angles[1] > max_positive_angle)) {
                new_angles.append((angle - 360));
            } elif ((angle == angles[-1]) and (angles[-2] > max_positive_angle)) {
                new_angles.append((angle - 360));
            } else {
                new_angles.append(angle);
            }
        } else {
            new_angles.append(angle);
        }
    }
    return new_angles;
}

