""""
    To check whether a number is prime
    """
def prime(num: float) -> object {
    num2 = num;
    while (num2 > 0) {
        if (num == num2) {
            num2 -= 1;
        } elif (num2 == 1) {
            num2 -= 1;
        } elif ((num % num2) == 0) {
            return False;
        }
        num2 -= 1;
    }
    return True;
}

