) -> object {
    for funcData in callbacks {
        func = funcData[0];
        args = funcData[1];
        kwargs = funcData[2];
        s = func(colorspace, dataTypeHint, *args, **kwargs);
        if (not isinstance(s, str) and (s is not None)) {
            raise TypeError((errorMsg + (". Got type %s" % str(`type(s)))));
