    `list = [];
    for x in range(nelx) {
        for y in range(nely) {
            if (
                abs(
                    (
                        (
                            (
                                ((x - ((nelx - 1) / 2.0)) ** 2)
                                + ((y - ((nely - 1) / 2.0)) ** 2)
