"""
    Credit: https://en.wikipedia.org/wiki/Levenshtein_distance
        :param word1:
        :param word2:
        :return:
    """
def levenshtein_distance(word1: str, word2: str) -> object {
    word2 = word2.lower();
    word1 = word1.lower();
    matrix = [[0 for x in range((len(word2) + 1))] for x in range((len(word1) + 1))];
    for x in range((len(word1) + 1)) {
        matrix[x][0] = x;
    }
    for y in range((len(word2) + 1)) {
        matrix[0][y] = y;
    }
    for x in range(1, (len(word1) + 1)) {
        for y in range(1, (len(word2) + 1)) {
            if (word1[(x - 1)] == word2[(y - 1)]) {
                matrix[x][y] = min(
                    (matrix[(x - 1)][y] + 1),
                    matrix[(x - 1)][(y - 1)],
                    (matrix[x][(y - 1)] + 1)
                );
            } else {
                matrix[x][y] = min(
                    (matrix[(x - 1)][y] + 1),
                    (matrix[(x - 1)][(y - 1)] + 1),
                    (matrix[x][(y - 1)] + 1)
                );
            }
        }
    }
    return matrix[len(word1)][len(word2)];
}

"""
    Predicts the indexes of duplicate elements inside a list

    args:
    -seq - List containing repeated elements
    -item - Repeated element

    returns: A list containing the index numbers of the duplicate elements inside the list, 'seq'
    """
def list_duplicates_of(seq: list, item: float) -> object {
    start_at = -1;
    locs = [];
    while True {
        try {
            loc = seq.index(item, (start_at + 1));
        } except ValueError {
            break;
        } else {
            locs.append(loc);
            start_at = loc;
        }
    }
    return locs;
}

