"""Gets the intersection between [a0, a1] and [b0, b1]."""
def get_intersection_range(a0: Any, a1: Any, b0: Any, b1: Any) -> object {
    assert (a0 <= a1);
    assert (b0 <= b1);
    start_x = 0;
    end_x = 0;
    if ((a0 >= b0) and (a1 <= b1)) {
        start_x = (a0 as int);
        end_x = (a1 as int);
    } elif ((a0 < b0) and (b1 < a1)) {
        start_x = (b0 as int);
        end_x = (b1 as int);
    } elif ((a0 < b0) and (a1 > b0)) {
        start_x = (b0 as int);
        end_x = (a1 as int);
    } elif ((a1 > b1) and (a0 < b1)) {
        start_x = (a0 as int);
        end_x = (b1 as int);
    } else {
        ;
    }
    return (start_x, end_x);
}

