    if (i >= (LWord - 1)) {
        return 0;
    }
    if (Word[i].lower() == Letter.lower()) {
        return 0;
    }
    if (i > 0) {
        if (Word[(i - 1)].lower() == Letter.lower()) {
            return -1;
