""" premier diviseur premier de n """
def diviseur(n: int) -> object {
    i = 2;
    while ((i * i) <= n) {
        (q, r) = divmod(n, i);
        if (r == 0) {
            return i;
        }
        i += 1;
    }
    return n;
}

