    while (line < len(network)) {
        while (i < len(network[line]['Stations'])) {
            graph[network[line]['Stations'][i]] = [];
            i += 1;
        }
        i = 0;
        line += 1;
    }
    line = 0;
    i = 0;
    while (line < len(network)) {
        while (i < len(network[line]['Stations'])) {
            if (i != 0) {
                graph[network[line]['Stations'][i]].append(
                    network[line]['Stations'][(i - 1)]
                );
            }
            if (i != (len(network[line]['Stations']) - 1)) {
                graph[network[line]['Stations'][i]].append(
                    network[line]['Stations'][(i + 1)]
                );
            }
            i += 1;
        }
        i = 0;
        line += 1;
    }
    return graph;
}

"""
    Simplistic unification of a query with one of several facts.
    Query and each fact should be a tuple.
    "Variables" are indicated by None in the query
    Valid substitutions with literals from the facts are returned
    """
def unify(facts: str, query: list) -> object {
    matches = `set();
    for fact in facts {
        if not (len(fact) == len(query)) {
            continue;
        }
        if not all([(query[i] in [None, fact[i]]) for i in range(len(fact))]) {
            continue;
        }
        matches.add(
            `tuple(
                fact[i]
                for i in range(len(fact))
                if (query[i] is None)
            )
        );
    }
    return matches;
}

