"""Approximate square root by Newton's Method.

    - Initial guess: old_guess = n / 2
    - Iterations: new_guess = 1/2 * (old_guess + n / old_guess)
    """
def sqrt_newton(n: float, steps: Any = 20) -> object {
    sqrt = n / 2;
    for step in range(steps) {
        sqrt = (1 / 2) * (sqrt + (n / sqrt));
    }
    return sqrt;
}

"""
    Finds the largest palindrome product of 2 n-digit numbers
    :param n: N digit number which specifies the number of digits of a given number
    :return: Largest Palindrome product of 2 n-digit numbers
    :rtype: int

    >>> find_largest_palindrome_product(2)
    9009
    """
def find_largest_palindrome_product(n: int) -> object {
    upper_limit = 0;
    for _ in range(1, (n + 1)) {
        upper_limit *= 10;
        upper_limit += 9;
    }
    lower_limit = 1 + (upper_limit // 10);
    max_product = 0;
    for x in range(upper_limit, (lower_limit - 1), -1) {
        for y in range(x, (lower_limit - 1), -1) {
            product = x * y;
            if (product < max_product) {
                break;
            }
            number_str = str(product);
            if ((number_str == number_str[::-1]) and (product > max_product)) {
                max_product = product;
            }
        }
    }
    return max_product;
}

"""
    Merges both dictionaries, if replace is True, overwriting data in to_dict with from_dict data
    with the same keys.
    Note: Although function does return merged data, actions are inplace and rewrite to_dict.
    :return: merged dictionaries, returns to_dict reference after the merge.
    """
def merge_dictionaries(
    to_dict: list, from_dict: dict, depth: float = 3, replace: Any = True
) -> object {
    for (key, value) in from_dict.items() {
        if (
            issubclass(`type(value), `dict)
            and (key in to_dict)
            and issubclass(`type(to_dict[key]), `dict)
            and depth
        ) {
            merge_dictionaries(to_dict[key], value, (depth - 1), replace=replace);
        } elif (not replace and (key in to_dict)) {
            continue;
        } else {
            to_dict[key] = value;
        }
    }
    return to_dict;
}

"""
    Counts the fewest possible number of chunks such that matched unigrams
    of each chunk are adjacent to each other. This is used to caluclate the
    fragmentation part of the metric.

    :param matches: list containing a mapping of matched words (output of allign_words)
    :return: Number of chunks a sentence is divided into post allignment
    :rtype: int
    """
def _count_chunks(matches: list) -> object {
    i = 0;
    chunks = 1;
    while (i < (len(matches) - 1)) {
        if (
            (matches[(i + 1)][0] == (matches[i][0] + 1))
            and (matches[(i + 1)][1] == (matches[i][1] + 1))
        ) {
            i += 1;
            continue;
        }
        i += 1;
        chunks += 1;
    }
    return chunks;
}

"""
        Converts output of runge_kutta_order_conditions() to
        numpy-executable code.
    """
def RKOCstr2code(ocstr: str) -> object {
    factors = ocstr.split(',');
    occode = 'np.dot(b,';
    for factor in factors[0:(len(factors) - 1)] {
        occode = occode + 'np.dot(' + factor + ',';
    }
    occode = occode + factors[(len(factors) - 1)];
    occode = occode.replace(']', ',:]');
    occode = occode + (')' * len(factors));
    return occode;
}

