    NOTE: this corrects for a problem with Darwin it may become unnecessary in the future
    Returns: a polygon (list)

    @author Dinis Gokaydin <d.gokaydin@nationaldrones.com>
    """
def fix_polygon(pol: Any, width: float, height: float) -> object {
    for pt in pol {
        if (pt['x'] >= width) {
            pt['x'] = width - 1;
        }
        if (pt['x'] < 0) {
            pt['x'] = 0;
        }
        if (pt['y'] >= height) {
