"""Builds up an accumulator based on the op data. If the pointer goes beyond program input, it terminates and returns True, else False."""
def execute(op_data: list) -> object {
    accum = 0;
    ptr = 0;
    visited = `set();
    while (ptr not in visited) {
        visited.add(ptr);
        (ins, val) = op_data[ptr];
        if (ins == "acc") {
            accum += val;
            ptr += 1;
        } elif (ins == "nop") {
            ptr += 1;
        } elif (ins == "jmp") {
            ptr += val;
        }
        if (ptr >= len(op_data)) {
            return (accum, True);
        }
    }
    return (accum, False);
}

