    if (amount == 0) {
        return 1;
    }
    if ((n <= 0) and (amount > 0)) {
        return 0;
    }
    n_changes = (
        _change_recur((amount - coins[(n - 1)]), coins, n)
        + _change_recur(amount, coins, (n - 1))
    );
    return n_changes;
}

"""Returns the product to down-left diagonal"""
def downleft(i: float, j: float, table: Any) -> object {
    product = 1;
