"""
    This function will do the math required to calculate the
    difference in the stated problem.
    """
def sumSquare(number: int) -> object {
    sumSq = 0;
    sqOfSum = 0;
    for i in range(1, (number + 1)) {
        sumSq += i ** 2;
        sqOfSum += i;
    }
    sqOfSum = sqOfSum ** 2;
    diff = sqOfSum - sumSq;
    return diff;
}

"""
