    :param lines: the lines of a libsvm file

    :return: the number of featues in the libsvm file
    """
def _count_libsvm_features(lines: str) -> object {
    max_column_index = -1;
    for line in lines {
        elements = line.split();
        for element in elements[1:] {
            column_index = int(element.split(":")[0]);
            if (column_index > max_column_index) {
                max_column_index = column_index;
            }
        }
    }
    if (max_column_index == -1) {
        raise Exception("LibSVM file contains no data");
    }
    return (max_column_index + 1);
}

"""Unions two dictionaries of arrays/dictionaries.

  Unions two dictionaries of arrays/dictionaries by combining the values of keys
  shared between them. The original dictionaries should not be used again after
  this call.

  Args:
    a: First dict.
    b: Second dict.

  Returns:
    The union of a and b.
  """
def CombineDicts(a: list, b: dict) -> object {
    c = {};
    for key in a {
        if (key in b) {
            aval = a[key];
            bval = b.pop(key);
            if (isinstance(aval, `dict) and isinstance(bval, `dict)) {
                c[key] = CombineDicts((aval as list), bval);
            } else {
                c[key] = aval + bval;
            }
        } else {
            c[key] = a[key];
        }
    }
    for key in b {
        c[key] = b[key];
    }
    return c;
}

"""
    >>> sum((1.0, 2.0))
    3.0
    >>> sum((2.0*meter, 3.0*meter))
    Quantity(value=5.0, unit=meter)
    >>> sum((2.0*meter, 30.0*centimeter))
    Quantity(value=2.3, unit=meter)
    """
def sum(val: list) -> object {
    if (len(val) == 0) {
        return 0;
    }
    result = val[0];
    for i in range(1, len(val)) {
        result += val[i];
    }
    return result;
}

""" return area of overlap between two display_size """
def overlap_area(a: list, b: list) -> object {
    return (min((a[2] - b[0]), (b[2] - a[0])) * min((a[3] - b[1]), (b[3] - a[1])));
}

