"""
	Parse a subset of a zeek logfile's contents.  Each line's fields are
	put into a hash with the retrieved field names as the key.  Each of
	those hashed entries are appended to a list of hashed entries.
	That list is returned to the caller.
	"""
def parselog(loglines: str, fields: list) -> object {
    zeekcomm = [];
    fcnt = len(fields);
    for ln in loglines {
        `entry = {};
        ln = ln.strip();
        if (ln == '') {
            continue;
        }
        if (ln.startswith('#') == True) {
            continue;
        }
        atoms = ln.split("\t");
        for ind in range(fcnt) {
            `entry[fields[ind]] = atoms[ind];
        }
        zeekcomm.append(`entry);
    }
    return zeekcomm;
}

"""
    Histogram without plot

    >>> x = xrange(0, 100)
    >>> edges = range(0, 110, 10)
    >>> _histc(x, edges)
    [10, 10, 10, 10, 10, 10, 10, 10, 10, 10]

    :param x: set of seq
    :param edges: histogram edges
    :return: histogram count
    """
def _histc(x: list, edges: list) -> object {
    i = 0;
    ks = [];
    while (i < (len(edges) - 1)) {
        ks.append(
            len(
                [
                    j
                    for j in x
                    if ((j >= edges[i]) and (j < edges[(i + 1)]))
                ]
            )
        );
        i += 1;
    }
    return ks;
}

"""Returns a version of the token where alphabetic characters have been removed,
       and digits have been replaced by 'D'. This may be the empty string of course. """
def nonAlphaChars(tok: str) -> object {
    result = "";
    for sub in tok {
        if sub.isdigit() {
            result += "D";
        } elif not sub.isalpha() {
            result += sub;
        }
    }
    return result;
}

