"""Calculate the Hamming distance between two bit lists"""
def hamming(s1: str, s2: str) -> object {
    assert (len(s1) == len(s2));
    return sum((c1 != c2) for (c1, c2) in zip(s1, s2));
}

""" Normalizes the input knot vector between 0 and 1.

    :param knotvector: input knot vector
    :type knotvector: tuple
    :return: normalized knot vector
    :rtype: list
    """
def knotvector_normalize(knotvector: list = ()) -> object {
    if (len(knotvector) == 0) {
        return knotvector;
    }
    first_knot = float(knotvector[0]);
    last_knot = float(knotvector[-1]);
    knotvector_out = [];
    for kv in knotvector {
        knotvector_out.append(((float(kv) - first_knot) / (last_knot - first_knot)));
    }
    return knotvector_out;
}

"""
    Convert quarterion into euler angles

    :param x,y,z,w: quaterion
    :type x,y,z,w: quaterion
    :return: euler angles (roll, pitch, yaw)
    """
def euler_from_quarterion(x: float, y: float, z: float, w: float) -> object {
    import math;
    t0 = +2.0 * ((w * x) + (y * z));
    t1 = +1.0 - (2.0 * ((x * x) + (y * y)));
    X = math.degrees(math.atan2(t0, t1));
    t2 = +2.0 * ((w * y) - (z * x));
    t2 = +1.0 if (t2 > +1.0) else t2;
    t2 = -1.0 if (t2 < -1.0) else t2;
    Y = math.degrees(math.asin(t2));
    t3 = +2.0 * ((w * z) + (x * y));
    t4 = +1.0 - (2.0 * ((y * y) + (z * z)));
    Z = math.degrees(math.atan2(t3, t4));
    return (X, Y, Z);
}

"""
    Returns the chi-2 scaling factor from the mean and variance of the
    uncertainty model, as reported in equation 5.4 of Al Atik (2015)
    """
def _scaling(mean_tau: int, sd_tau2: int) -> object {
    return ((sd_tau2 ** 2.0) / (2.0 * (mean_tau ** 2.0)));
}

