"""
      Compare the end return codes for tree.endpoint
    """
def similarTuple(left: list, right: list, max: int) -> object {
    for i in range(0, max) {
        if (left[i] > right[i]) {
            if ((left[i] - right[i]) > 0.5) {
                return False;
            }
        } elif ((right[i] - left[i]) > 0.5) {
            return False;
        }
    }
    return True;
}

