}

"""Return a pair (index, pos), indicating the next occurrence of
    char in str. index is the position of the character considering
    only ordinals up to and including char, and pos is the position in
    the full string. index/pos is the starting position in the full
    string."""
def selective_find(str: list, char: Any, index: float, pos: Any) -> object {
    l = len(str);
    while 1 {
        pos += 1;
        if (pos == l) {
            return (-1, -1);
        }
        c = str[pos];
        if (c == char) {
            return ((index + 1), pos);
        } elif (c < char) {
            index += 1;
        }
    }
}

"""
    Round the number to the nearest whole number dividable by 25.
    This will round up or down, to find the closest number

    Examples:
    ---------

        >>> nearest_25(5)
        0
        >>> nearest_25(25)
        25
        >>> nearest_25(40)
        50
        >>> nearest_25(810)
        800
    """
def nearest_25(num: float) -> object {
    num = float(num) / 100;
    num = round((num * 4)) / 4;
    num = num * 100;
    return int(num);
}

"""A function with an analytical Hilbert transform."""
