}

""" Add a numerical value to a string. """
def replace_num(phrase: str, val: Any) -> object {
    if (val == 1) {
        return phrase.replace("(^)", "one");
    } elif (val == 2) {
        return phrase.replace("(^)", "two");
    } else {
        return phrase.replace("(^)", "several");
    }
}

"""Takes a string and a number (guaranteed to be greater than length of the string), and returns that string, padded on its left side with empty space characters such that the length of the string equals the number."""
def med_leftpad(s: str, n: int) -> object {
