"""
    Computes the symmetric modular reduction.
    :param x: the number to reduce
    :param m: the modulus
    :return: x reduced in the interval [-m/2, m/2]
    """
def symmetric_mod(x: float, m: float) -> object {
    return (int(((x + m + (m // 2)) % m)) - int((m // 2)));
}

"""Solves a%c=b, returning c"""
def mod_inverse(a: Any, b: int) -> object {
    (u1, u2, u3) = (1, 0, a);
    (v1, v2, v3) = (0, 1, b);
    while (v3 != 0) {
        q = u3 // v3;
        (v1, v2, v3, u1, u2, u3) = (
            (u1 - (q * v1)),
            (u2 - (q * v2)),
            (u3 - (q * v3)),
            v1,
            v2,
            v3
        );
    }
    return (u1 % b);
}

"""
    Split line to a sequence of iterating alpha and digit strings

    :param s:
    :type s: str
    :return: list
    :rtype: list

    >>> split_alnum("Fa 0/1")
    ['Fa ', 0, '/', 1]
    >>> split_alnum("Fa 0/1.15")
    ['Fa ', 0, '/', 1, '.', 15]
    >>> split_alnum("ge-1/0/1")
    ['ge-', 1, '/', 0, '/', 1]
    >>> split_alnum("ge-1/0/1.15")
    ['ge-', 1, '/', 0, '/', 1, '.', 15]
    """
def split_alnum(s: str) -> object {
    def convert(x: Any) -> object {
        try {
            return int(x);
        } except ValueError {
            return x;
        }
    }
    r = [];
    digit = None;
    for c in s {
        d = c.isdigit();
        if (d != digit) {
            digit = d;
            r += [c];
        } else {
            r[-1] += c;
        }
    }
    return [convert(x) for x in r];
}

"""
  Return index-th permutation of a list.

  Keyword arguments:
  list  --- the list to be permuted
  index --- index in range (0, factorial(len(list)))
  """
def permute(`list: list, index: float) -> object {
    if (len(`list) < 2) {
        return `list;
    }
    (rest, choice) = divmod(index, len(`list));
    return (
        [`list[choice]]
        + permute((`list[0:choice] + `list[(choice + 1):len(`list)]), rest)
    );
}

"""Extracts original error from a wrapper listing hosts
    where the error occurred"""
def unwrap_error_with_hosts(error_obj: dict) -> object {
    error_id = error_obj.get('id');
    description = error_obj.get('description');
    details = error_obj.get('details', {});
    nodes = [];
    if ((error_id == 'errorOnNodes') and ('error' in details)) {
        error_id = details['error']['id'];
        description = details['error']['description'];
        nodes = details['hostnames'];
        details = details['error'].get('details', {});
    }
    return (error_id, description, details, nodes);
}

"""
    Helper function to format the stdout from the get_coredump_network_config function.

    cmd_ret
        The return dictionary that comes from a cmd.run_all call.
    """
def _format_coredump_stdout(cmd_ret: dict) -> object {
    ret_dict = {};
    for line in cmd_ret["stdout"].splitlines() {
        line = line.strip().lower();
        if line.startswith("enabled:") {
            enabled = line.split(":");
            if ("true" in enabled[1]) {
                ret_dict["enabled"] = True;
            } else {
                ret_dict["enabled"] = False;
                break;
            }
        }
        if line.startswith("host vnic:") {
            host_vnic = line.split(":");
            ret_dict["host_vnic"] = host_vnic[1].strip();
        }
        if line.startswith("network server ip:") {
            ip = line.split(":");
            ret_dict["ip"] = ip[1].strip();
        }
        if line.startswith("network server port:") {
            ip_port = line.split(":");
            ret_dict["port"] = ip_port[1].strip();
        }
    }
    return ret_dict;
}

