    Tries to extracts the OID from the X500 name.
    :param subject:
    :param oid:
    :return:
    """
def try_get_dn_part(subject: dict, oid: Any = None) -> object {
    try {
        if (subject is None) {
            return None;
        }
        if (oid is None) {
            return None;
        }
        for sub in subject {
            if ((oid is not None) and (sub.oid == oid)) {
                return sub.value;
            }
        }
    } except Exception as e {
        ;
    }
    return None;
}

