    """
def beach_validation(beach: str) -> object {
    while (
        (beach != "5")
        and (beach != "4")
        and (beach != "3")
        and (beach != "2")
        and (beach != "1")
        and (beach != "0")
        and (beach != "-1")
        and (beach != "-2")
