"""
    Determines the k-value of the point p on the line segment a-b. The k-value is the normalized
    location on the line ab, with k(a)=0 and k(b)=1

    Parameters
    ----------
    p : (x,y)
        Coordinates of a point. The point is assumed to be on the line through a & b.
    a : (x,y)
        Coordinates of the beginning of the line segment.
    b : (x,y)
        Coordinates of the end of the line segment.

    Returns
    ----------
    float
        The k-value of p on ab.
    """
def kvalue(p: list, a: Any, b: list) -> object {
    if (a == b) {
        return None;
    } elif (a[0] == b[0]) {
        return ((p[1] - a[1]) / (b[1] - a[1]));
    } else {
        return ((p[0] - a[0]) / (b[0] - a[0]));
    }
}

"""
    return string in conll format
    """
def conllify(sentences: str) -> object {
    conll = [];
    for (sent_id, s) in enumerate(sentences, 1) {
        for (token_id, `tuple) in enumerate(s, 1) {
            token = str(`tuple[0]);
            tag = str(`tuple[1]);
            row = '\t'.join([str(token_id), token, tag]);
            conll += [row];
        }
        conll += [''];
    }
    conll = ('\n'.join(conll) as list[str]);
    return conll;
}

""" takes a qty and a unit (as a string) and returns the quantity in m3/year
        accepts:
        m3/sec
        m3/day
        m3/year
        Returns None if QUANTITY_UNITS doesn't match one of the options.
    """
def normalize_quantity(qty: float, qty_unit: str) -> object {
    if (qty_unit is None) {
        return None;
    }
    qty_unit = qty_unit.strip();
    if (qty_unit == 'm3/year') {
        return qty;
    } elif (qty_unit == 'm3/day') {
        return (qty * 365);
    } elif (qty_unit == 'm3/sec') {
        return (qty * 60 * 60 * 24 * 365);
    } else {
        return None;
    }
}

