"""
    csv should be a string that meets the RFC 4180 specification,
    with the additional requirement of a header line.
    This function returns a list of dictionaries.
    """
def convert_simple(csv: str) -> object {
    csv = csv.rstrip().strip();
    lines = csv.splitlines();
    header = lines.pop(0).split(",");
    return_list = [];
    for line in lines {
        tmp_dict = {};
        quoted = False;
        i = 0;
        header_indx = 0;
        text_buffer = "";
        while (i < len(line)) {
            if (line[i] == "\"") {
                if quoted {
                    if (((i + 1) < len(line)) and (line[(i + 1)] == "\"")) {
                        text_buffer += "\"";
                        i += 1;
                    } else {
                        quoted = False;
                    }
                } else {
                    quoted = True;
                }
            } elif ((line[i] == ",") and not quoted) {
                tmp_dict[header[header_indx]] = text_buffer;
                text_buffer = "";
                header_indx += 1;
            } else {
                text_buffer += line[i];
            }
            i += 1;
        }
        tmp_dict[header[header_indx]] = text_buffer;
        return_list.append(tmp_dict);
    }
    return return_list;
}

"""
    Translate gene identifiers in a signature dictionary.

    Args:
        signatures (dict of list): signature dictionary
        rosetta (dict): translation table mapping one gene identifier to another
        ignore_missing (boolean): If true, no error will be raised if an identifier is not in
            the translation dictionary. Respective entries will be skipped.

    Returns:
        dict of list: translated signature dictionary

    Raises:
        KeyError: if a gene is not in the rosetta dictionary unless ignore_missing is specified
    """
def translate_signatures(
    signatures: dict, rosetta: list, ignore_missing: Any = False
) -> object {
    if ignore_missing {
        signatures = {
            tissue: [
                gene
                for gene in genes
                if (gene in rosetta)
            ] for (tissue, genes) in signatures.items()
        };
    }
    return {
        tissue: [rosetta[gene] for gene in genes]
        for (tissue, genes) in signatures.items()
    };
}

