"""
    ..doctest:
    >>> def f(c): return c.isupper()
    >>> get_hq_start_end('', f)
    (0, 0)
    >>> get_hq_start_end('GC', f)
    (0, 2)
    >>> get_hq_start_end('aGCc', f)
    (1, 3)
    """
def get_hq_start_end(seq: list, is_hq_f: Any) -> object {
    (start, end) = (0, 0);
    i = 0;
    while (i < len(seq)) {
        if is_hq_f(seq[i]) {
            start = i;
            break;
        }
        i += 1;
    }
    i = len(seq) - 1;
    while (i >= 0) {
        if is_hq_f(seq[i]) {
            end = i + 1;
            break;
        }
        i -= 1;
    }
    return (start, end);
}

"""
    Look at every pair of polygon points that follow each other:
    which is every line in the polygon.

    Call the two points in every line point_a and point_b.
    There is also a line from the last point in the list to the first point in the list.

    Calculate the next point based on the percentage and the difference between x and y values of two points.
    """
def get_next_polygon_points(polygon_points: list, percentage: float) -> object {
    next_points = [];
    for index in range(len(polygon_points)) {
        point_a = polygon_points[index];
        point_b = polygon_points[((index + 1) % len(polygon_points))];
        diff_x = point_b[0] - point_a[0];
        diff_y = point_b[1] - point_a[1];
        next_x = point_a[0] + (percentage * diff_x);
        next_y = point_a[1] + (percentage * diff_y);
        next_points.append((next_x, next_y));
    }
    return next_points;
}

""" Return P[A > a] for the given set of areas.
    Extract areas from the hierarchical tree using

    areas = [tree.node[n]['cycle_area'] for n in tree.nodes_iter() \
            if not tree.node[n]['external']].
    """
def cum_size_distribution(areas: str, a: Any) -> object {
    return (
        sum(
            [
                1.0
                for A in areas
                if (A > a)
            ]
        )
        / len(areas)
    );
}

