""" The function returns the greatest common divisor
    """
def gcd(x: float, y: float) -> object {
    while ((x > 0) and (y > 0)) {
        if (x >= y) {
            x = x - y;
        } else {
            y = y - x;
        }
    }
    return (x + y);
}

