""" Low discrepancy halton sequence with a given prime """
def halton_seq(prime: float, index: Any = 1) -> object {
    (r, f, i) = (0.0, 1.0, index);
    while (i > 0) {
        f /= prime;
        r += f * (i % prime);
        i = int((i / float(prime)));
    }
    return r;
}

