"""(list, int) -> int
    Precondition: L[b:] is not empty.
    Return the index of the smallest value in L[b:].

    >>> find_min([3, -1, 7, 5], 0)
    1
    """
def find_min(L: list, b: float) -> object {
    smallest = b;
    i = b + 1;
    while (i != len(L)) {
        if (L[i] < L[smallest]) {
            smallest = i;
        }
        i = i + 1;
    }
    return smallest;
}

