"""assumes v1, and v2 are lists of ints.
       Returns a list containing the pointwise sum of the elements
       in v1 and v2. For example, addVectors([4, 5], [1, 2, 3]) returns
       [5, 7, 3], and addVectors([], []) returns []. Does not modify inputs."""
def addVectors(v1: str, v2: str) -> object {
    if (len(v1) > len(v2)) {
        result = v1;
        other = v2;
    } else {
        result = v2;
        other = v1;
    }
    for i in range(len(other)) {
        result[i] += other[i];
    }
    return result;
}

"""
    Compute the score of the explanation method based on the features employed for the explanation compared to the features truely used by the black box
    """
def compute_score_interpretability_method(
    features_employed_by_explainer: str, features_employed_black_box: str
) -> object {
    precision = 0;
    recall = 0;
    for feature_employe in features_employed_by_explainer {
        if (feature_employe in features_employed_black_box) {
            precision += 1;
        }
    }
    for feature_employe in features_employed_black_box {
        if (feature_employe in features_employed_by_explainer) {
            recall += 1;
        }
    }
    return (
        (precision / len(features_employed_by_explainer)),
        (recall / len(features_employed_black_box))
    );
}

