"""
    Te idea here is that by doing the first run, the biggest element will
    be the last element in the list, and that is definitly is
    best position, so no need to try to swap him again.

    The complexity of this algorithm is O(?)
    """
def buble_sort_imp_1(l: list) -> object {
    swap = True;
    n = len(l);
    while swap {
        swap = False;
        for i in range((n - 1)) {
            if (l[i] > l[(i + 1)]) {
                (l[i], l[(i + 1)]) = (l[(i + 1)], l[i]);
                swap = True;
            }
        }
        n -= 1;
    }
    return l;
}

"""
    Splits the provided string around the delimiter character that
    has been provided and allows proper escaping of it using the
    provided escape character.

    This is considered to be a very expensive operation when compared
    to the simple split operation and so it should be used carefully.

    :type value: String
    :param value: The string value that is going to be split around
    the proper delimiter value taking into account the escaping.
    :type delimiter: String
    :param delimiter: The delimiter character to be used in the split
    operation.
    :type max: int
    :param max: The maximum number of split operations that are going
    to be performed by this operation.
    :type escape: String
    :param escape: The "special" escape character that will allow the
    delimiter to be also present in the choices selection.
    :type unescape: bool
    :param unescape: If the final resulting string should be already
    unescaped (normalized).
    :rtype: List
    :return: The final list containing the multiple string parts separated
    by the delimiter character and respecting the escape sequences.
    """
def split_unescape(
    value: str,
    delimiter: Any = " ",
    max: Any = -1,
    escape: Any = "\\",
    unescape: Any = True
) -> object {
    result = [];
    current = [];
    iterator = iter(value);
    count = 0;
    for char in iterator {
        if (char == escape) {
            try {
                if not unescape {
                    current.append(escape);
                }
                current.append(next(iterator));
            } except StopIteration {
                if unescape {
                    current.append(escape);
                }
            }
        } elif ((char == delimiter) and not (count == max)) {
            result.append("".join(current));
            current = [];
            count += 1;
        } else {
            current.append(char);
        }
    }
    result.append("".join(current));
    return result;
}

"""
    n and k must be ints.

    returns a list of as-even-as-possible shares when n is divided into k pieces.

    Excess is left for the end.  If you want random order, shuffle the output.

    >>> even_split(2,1)
    [2]

    >>> even_split(2,2)
    [1, 1]

    >>> even_split(3,2)
    [1, 2]

    >>> even_split(11,3)
    [3, 4, 4]
    """
def even_split(n: int, k: int) -> object {
    ans = [];
    if ((`type(n) is not int) or (`type(k) is not int)) {
        raise TypeError("n and k must be ints");
    }
    r = n % k;
    ans = [(n / k)] * (k - r);
    ans.extend(([((n / k) + 1)] * r));
    return ans;
}

