    [[[[1, 2]], [3, 4], [], [6, 7]]]

    """
def deep_remove(l: Any, *what: Any) -> object {
    if isinstance(l, list) {
        l = l[:];
        for to_remove in what {
            if (to_remove in l) {
                (l as list).remove(to_remove);
