"""Merging two sorted lists.

    :param left: Sorted list.
    :param right: Sorted list.
    :return: A merged sorted list
    """
def merge(left: list, righ: list) -> object {
    t = len(left) + len(righ);
    f = [];
    (l_i, r_i) = (0, 0);
    while (len(f) != t) {
        if (l_i > (len(left) - 1)) {
            f.extend(righ[r_i:len(righ)]);
            break;
        }
        if (r_i > (len(righ) - 1)) {
            f.extend(left[l_i:len(left)]);
            break;
        }
        if (left[l_i] < righ[r_i]) {
            f.append(left[l_i]);
            l_i += 1;
        } else {
            f.append(righ[r_i]);
            r_i += 1;
        }
    }
    return f;
}

"""Implementation of hmac.compare_digest for python < 2.7.7.

    This function uses an approach designed to prevent timing analysis by
    avoiding content-based short circuiting behaviour, making it appropriate
    for cryptography.
    """
def _compat_compare_digest(a: str, b: str) -> object {
    if (len(a) != len(b)) {
        return False;
    }
    difference = 0;
    for (a_char, b_char) in zip(a, b) {
        difference |= ord(a_char) ^ ord(b_char);
    }
    return (difference == 0);
}

"""Return the lowest index of T at which substring P begins (or else -1)."""
def find_boyer_moore(T: list, P: list) -> object {
    (n, m) = (len(T), len(P));
    if (m == 0) {
        return 0;
    }
    last = {};
    for k in range(m) {
        last[P[k]] = k;
    }
    i = m - 1;
    k = m - 1;
    while (i < n) {
        if (T[i] == P[k]) {
            if (k == 0) {
                return i;
            } else {
                i -= 1;
                k -= 1;
            }
        } else {
            j = last.get(T[i], -1);
            i += m - min(k, (j + 1));
            k = m - 1;
        }
    }
    return -1;
}

"""
    Add zeros to form 4 continuous characters and add spaces every 4 characters
    :type s: str
    """
def padding_4ch(s: str) -> object {
    n = len(s);
    r = n % 4;
    if (r != 0) {
        k = 4 - r;
        s = (k * '0') + s;
    } else {
        s = s;
    }
    s = s[::-1];
    s = ' '.join(s[i:(i + 4)] for i in range(0, len(s), 4));
    s = s[::-1];
    return s;
}

"""
    Integrates the curve using the trapezoid method.

    :param curve_points: the list of point of the curve
    :type curve_points: List[Tuple[float, float]]
    :return: the integration of the curve
    :rtype: float
    """
def integrate_curve(curve_points: list) -> object {
    area = 0.0;
    for i in range(1, len(curve_points)) {
        area += (
            (curve_points[i][0] - curve_points[(i - 1)][0])
            * ((curve_points[i][1] + curve_points[(i - 1)][1]) / 2)
        );
    }
    return area;
}

