        }
        if ((grid[i][j] == "1") and not `visit[i][j]) {
            `visit[i][j] = 1;
            visit_island(grid, `visit, (i + 1), j);
            visit_island(grid, `visit, i, (j + 1));
        }
    }
    `visit = [([0] * len(grid[0])) for i in range(len(grid))];
    num = 0;
    for i in range(len(grid)) {
        for j in range(len(grid[0])) {
            if ((grid[i][j] == "1") and not `visit[i][j]) {
