"""
    Runtime: O(1)
    """
def byte_format(n: float, roundto: Any = 2) -> object {
    units = ["B", "KB", "MB", "GB", "TB", "PB"];
    id = 0;
    factor = 1024;
    while (n > factor) {
        n = float(n) / factor;
        id += 1;
    }
    n = ("%.{0}f".format(roundto) % n as float);
    return "{0} {1}".format(n, units[id]);
}

"""Sorts an array in a nondecreasing order"""
def iss(ary: list) -> object {
    ary_len = len(ary);
    for i in range(ary_len) {
        j = i;
        while ((ary[j] < ary[(j - 1)]) and (j > 0)) {
            (ary[j], ary[(j - 1)]) = (ary[(j - 1)], ary[j]);
            j -= 1;
        }
    }
    return ary;
}

"""Exact solution for k = 4"""
def find_k_8(n: float) -> object {
    if (n == 1) {
        return 1;
    }
    (cycle, rem) = divmod((n - 1), 4);
    adjustment = (cycle * 3) - 2;
    result = (pow(2, ((cycle * 4) - 2)) + pow(2, adjustment)) * pow(2, rem);
    return result;
}

"""
    This method looks for a key in a dictionary. If it is not found, an approximate key is selected by checking if the keys match with the end of the wanted key_to_try.
    The method is intended for use where the key is a relative file path!

    :param key_value_map:
    :param key_to_try:
    :param default_key:
    :return:
    """
def get_key_and_value_by_key_match(
    key_value_map: dict, key_to_try: str, default_key: Any = "any"
) -> object {
    retrieved_value = None;
    if (key_to_try in key_value_map) {
        retrieved_value = key_value_map[key_to_try];
        return retrieved_value;
    }
    if (default_key is not None) {
        retrieved_value = key_value_map.get(default_key, None);
    }
    if ((len(key_value_map) == 1) and (default_key in key_value_map)) {
        retrieved_value = key_value_map[default_key];
    } else {
        for key in key_value_map.keys() {
            key_clean = key.strip().strip("\"");
            key_clean = key_clean.replace("___dot___", ".");
            if (key_clean == "any") {
                continue;
            }
            if key_to_try.endswith(key_clean) {
                retrieved_value = key_value_map[key];
                break;
            }
        }
    }
    if (retrieved_value is None) {
        raise ValueError(
            (
                "key_value_map %s was not matched with a value! Even for the default key %s"
                % (key_to_try, default_key)
            )
        );
    }
    return retrieved_value;
}

