def convert_to_wkt(geotrace: str) -> object {
    wkt_points = [];
    for point in geotrace.split(';') {
        if point.strip() {
            (lat, lon, alt, accuracy) = map(float, point.split());
            wkt_points.append(('%.6f %.6f %d %.1f' % (lon, lat, alt, accuracy)));
        }
