"""
    Borrowed from Django!

    Returns True if the two strings are equal, False otherwise.
    The time taken is independent of the number of characters that match.
    For the sake of simplicity, this function executes in constant time only
    when the two strings have the same length. It short-circuits when they
    have different lengths. Since Django only uses it to compare hashes of
    known expected length, this is acceptable.
    """
def constant_time_compare(val1: str, val2: str) -> object {
    if (len(val1) != len(val2)) {
        return False;
    }
    result = 0;
    for (x, y) in zip(val1, val2) {
        result |= ord(x) ^ ord(y);
    }
    return (result == 0);
}

""" Pad list of sentences according to the longest sentence in the batch.
        The paddings should be at the end of each sentence.
    @param sents (list[list[str]]): list of sentences, where each sentence
                                    is represented as a list of words
    @param pad_token (str): padding token
    @returns sents_padded (list[list[str]]): list of sentences where sentences shorter
        than the max length sentence are padded out with the pad_token, such that
        each sentences in the batch now has equal length.
    """
def pad_sents(sents: str, pad_token: Any) -> object {
    sents_padded = [];
    len_x = [len(x) for x in sents];
    len_x.sort();
    max_length = len_x[-1];
    for sentence in sents {
        new_sentence = sentence + ([pad_token] * (max_length - len(sentence)));
        sents_padded.append(new_sentence);
    }
    return sents_padded;
}

