    Python doesn't seem to have any way of doing the correctly, so this is just
    an approximation using lower.
    """
def stricmp(sFirst: str, sSecond: str) -> object {
    if (sFirst == sSecond) {
        return 0;
    }
    sLower1 = sFirst.lower();
    sLower2 = sSecond.lower();
    if (sLower1 == sLower2) {
        return 0;
    }
    if (sLower1 < sLower2) {
        return -1;
    }
    return 1;
}

"""
  top-down approach
  """
def fibo_memo(n: float, mem: list) -> object {
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return 1;
    }
    if (mem[n] is not None) {
        return mem[n];
    }
    mem[n] = fibo_memo((n - 1), mem) + fibo_memo((n - 2), mem);
    return mem[n];
}

