}

"""Return set of two boxes where first is the fraction given"""
def split_box(fraction: str, x: int, y: int, w: int, h: int) -> object {
    if (w >= h) {
        new_w = int((w * fraction));
        if new_w {
            return ((x, y, new_w, h), ((x + new_w), y, (w - new_w), h));
        } else {
            return (None, None);
        }
    } else {
        new_h = int((h * fraction));
        if new_h {
            return ((x, y, w, new_h), (x, (y + new_h), w, (h - new_h)));
        } else {
            return (None, None);
        }
    }
}

"""Oldschool (python 2.x) cmp.

       if this < other return -1
       if this = other return 0
       if this > other return 1
    """
def compare_not_none(this: list, other: list) -> object {
    if (len(this) != len(other)) {
        return -1 if (len(this) < len(other)) else 1;
    }
    for i in range(len(this)) {
        (this_item, other_item) = (this[i], other[i]);
        if (this_item != other_item) {
            return -1 if (this_item < other_item) else 1;
        }
    } else {
        return 0;
    }
}

