"""
    Tries to guess the file type by looking up the filename
    extension from a table of known file types. Will return
    the type as string ("audio", "video" or "torrent") or
    None if the file type cannot be determined.
    """
def file_type_by_extension(extension: str) -> object {
    types = {
        'audio': ['mp3', 'ogg', 'wav', 'wma', 'aac', 'm4a'],
        'video': [
            'mp4',
            'avi',
            'mpg',
            'mpeg',
            'm4v',
            'mov',
            'divx',
            'flv',
            'wmv',
            '3gp'
        ],
        'torrent': ['torrent']
    };
    if (extension == '') {
        return None;
    }
    if (extension[0] == '.') {
        extension = extension[1:];
    }
    extension = extension.lower();
    for `type in types {
        if (extension in types[`type]) {
            return `type;
        }
    }
    return None;
}

"""complement a list of intervals with intervals not in list.
    """
def complement(intervals: list, first: Any = None, last: Any = None) -> object {
    if (len(intervals) == 0) {
        if ((first != None) and (last != None)) {
            return [(first, last)];
        } else {
            return [];
        }
    }
    new_intervals = [];
    intervals.sort();
    (last_from, last_to) = intervals[0];
    if ((first != None) and (first < last_from)) {
        new_intervals.append((first, last_from));
    }
    for (this_from, this_to) in intervals {
        if (this_from > last_to) {
            new_intervals.append((last_to, this_from));
        }
        last_from = this_from;
        last_to = max(last_to, this_to);
    }
    if (last and (last > last_to)) {
        new_intervals.append((last_to, last));
    }
    return new_intervals;
}

