"""Maximum string borders by Knuth-Morris-Pratt

    :param w: string
    :returns: table f such that f[i] is the longest border length of w[:i + 1]
    :complexity: linear
    """
def maximum_border_length(w: str) -> object {
    n = len(w);
    f = [0] * n;
    k = 0;
    for i in range(1, n) {
        while ((w[k] != w[i]) and (k > 0)) {
            k = f[(k - 1)];
        }
        if (w[k] == w[i]) {
            k += 1;
        }
        f[i] = k;
    }
    return f;
}

