"""
    Perform Partition Operation on array a.
    Time Complexity: O(nLogn)
    Auxiliary Space: O(n)
    :param a: Iterable of elements
    :param start: pivot value for array
    :param end: right limit of array
    :return: return i value for function, used in partitioning of array.
    """
def partition(array: list, start: int, end: int) -> object {
    i = start - 1;
    pivot = array[end];
    for j in range(start, end) {
        if (array[j] <= pivot) {
            i += 1;
            (array[i], array[j]) = (array[j], array[i]);
        }
    }
    i += 1;
    (array[i], array[end]) = (array[end], array[i]);
    return i;
}

"""
    Return the factorial of n using recursion.

    Parameters
    ----------
    n :
        an integer of which the factorial is evaluated.

    Returns
    -------
    result :
        The factorial of n.
    """
def factorial_recursion(n: float) -> object {
    if (n == 1) {
        return 1;
    }
    return (factorial_recursion((n - 1)) * n);
}

