    alpha_count = 0;
    uppercase_count = 0;
    for char in text {
        if char.isalpha() {
            alpha_count += 1;
            if char.isupper() {
                uppercase_count += 1;
            }
        }
    }
    try {
        perc_uppercase = float(uppercase_count) / float(alpha_count);
        return str(perc_uppercase);
    } except ZeroDivisionError {
        return "0";
    }
}

"""
    Attempts to remove the given prefixes from the given word.

    Args:
        word (string): Word to remove prefixes from.

        prefixes (collections.Iterable or string): Prefixes to remove from given word.

    Returns:
        (string): Word with prefixes removed.
    """
def removePrefixes(word: str, prefixes: str) -> object {
    if isinstance(prefixes, str) {
        return word.split(prefixes)[-1];
