"""
    Coerce config variables to proper types
    """
def coerce_value(val: str) -> object {
    def isnumeric(val: str) -> object {
        try {
            float(val);
            return True;
        } except ValueError {
            return False;
        }
    }
    if isnumeric(val) {
        try {
            return int(val);
        } except ValueError {
            return float(val);
        }
    }
    lower_val = str(val.lower());
    if (lower_val in ('true', 'false')) {
        if ('f' in lower_val) {
            return False;
        } else {
            return True;
        }
    }
    if (',' in val) {
        return [coerce_value(v.strip()) for v in val.split(',')];
    }
    return val;
}

