def tamiz3(m: int) -> object {
    (found, numbers, i) = ([], [], 2);
    while (i <= m) {
        if (i not in numbers) {
            found.append(i);
            for j in range(i, (m + 1), i) {
                numbers.append(j);
            }
        }
        i += 1;
    }
    return found;
}

