}

"""Return an offset along the y axis.

    Parameters
    ----------
    value : float
    location : {'first', 'last', 'inner', 'outer'}
    side : {'first', 'last'}
    is_vertical : bool
    is_flipped_y : bool

    Returns
    -------
    float
    """
def _get_y_offset(
    value: str, location: Any, side: Any, is_vertical: Any, is_flipped_y: Any
) -> object {
    if is_vertical {
        if not is_flipped_y {
            value = -value;
        }
    } elif is_flipped_y {
        if (
            (location == "first")
            or ((side == "first") and (location == "outer"))
            or ((side == "last") and (location == "inner"))
        ) {
            value = -value;
        }
    } elif (
        (location == "last")
        or ((side == "first") and (location == "inner"))
        or ((side == "last") and (location == "outer"))
    ) {
        value = -value;
    }
    return value;
}

