    """
def lengthOfLIS(nums: list) -> object {
    if (len(nums) == 0) {
        return 0;
    }
    dp = [1];
    for i in range(1, len(nums)) {
        maxx = 0;
        for j in range(i) {
            if (nums[j] < nums[i]) {
                maxx = max(maxx, dp[j]);
            }
        }
        dp.append((maxx + 1));
    }
    return max(dp);
}

