    for (index, elem) in enumerate(data) {
        if (elem == prog_a) {
            pos_a = index;
        } elif (elem == prog_b) {
            pos_b = index;
        } elif ((pos_a > 0) and (pos_b > 0)) {
            break;
        }
    }
    return (pos_a, pos_b);
}

"""O(log n)."""
def binary_search(items: list, target: Any) -> object {
    low = 0;
    high = len(items) - 1;
    while (low <= high) {
        mid = (low + high) // 2;
        if (items[mid] == target) {
            return mid;
        } elif (items[mid] < target) {
            low = mid + 1;
        } elif (items[mid] > target) {
            high = mid - 1;
        }
    }
    return None;
}

