"""
    The stepping number is generated from existing stepping numbers
    for ex: 1 generates 12, 10
            2  generates 21, 23
    """
def bfs(x: Any, n: Any, res: list) -> object {
    q = [];
    q.append(x);
    while q {
        p = q.pop(0);
        if (p <= n) {
            res.append(p);
            d = p % 10;
            if (d == 0) {
                q.append(((p * 10) + (d + 1)));
            } elif (d == 9) {
                q.append(((p * 10) + (d - 1)));
            } else {
                q.append(((p * 10) + (d + 1)));
                q.append(((p * 10) + (d - 1)));
            }
        }
    }
    return res;
}

