    for (dim0, dim1) in zip(`list(shape0), `list(shape1)) {
        if not isinstance(dim0, int) {
            num_sym_dim0 += 1;
        }
        if not isinstance(dim1, int) {
            num_sym_dim1 += 1;
        }
    }
    if (num_sym_dim0 < num_sym_dim1) {
