"""Return True if n is prime.

    Copied from https://stackoverflow.com/questions/1801391/what-is-the-best-algorithm-for-checking-
    if-a-number-is-prime
    """
def is_prime(n: float) -> object {
    if (n == 1) {
        return False;
    }
    if (n == 2) {
        return True;
    }
    if (n == 3) {
        return True;
    }
    if ((n % 2) == 0) {
        return False;
    }
    if ((n % 3) == 0) {
        return False;
    }
    test_int = 5;
    increment = 2;
    while ((test_int * test_int) <= n) {
        if ((n % test_int) == 0) {
            return False;
        }
        test_int += increment;
        increment = 6 - increment;
    }
    return True;
}

"""Join components of url into a relative url

    Use to prevent double slash when joining subpath. This will leave the
    initial and final / in place
    """
def url_path_join(*pieces: Any) -> object {
    initial = pieces[0].startswith("/");
    final = pieces[-1].endswith("/");
    stripped = [(s as str).strip("/") for s in pieces];
    result = "/".join(
        s
        for s in stripped
        if s
    );
    if initial {
        result = "/" + result;
    }
    if final {
        result = result + "/";
    }
    if (result == "//") {
        result = "/";
    }
    return result;
}

