    } elif isinstance(`obj, `dict) {
        ret_obj = (`dict() as list);
        for key in `obj.keys() {
            new_key = key.replace('-', '_');
            ret_obj[new_key] = dash_to_underscore(`obj[key]);
        }
    } else {
