    if str(mem_str)[-1].upper().endswith("G") {
        return int(round((float(mem_str[:-1]) * 1024 * 1024)));
    } elif str(mem_str)[-1].upper().endswith("M") {
        return int(round((float(mem_str[:-1]) * 1024)));
    } else {
        return int(round(float(mem_str)));
    }
}

"""Closest values

    :param L: list of values
    :returns: two values from L with minimal distance
    :modifies: the order of L
    :complexity: O(n log n), for n=len(L)
    """
def closest_values(L: list) -> object {
    assert (len(L) >= 2);
    L.sort();
    (valmin, argmin) = min(((L[i] - L[(i - 1)]), i) for i in range(1, len(L)));
    return (L[(argmin - 1)], L[argmin]);
}

