"""Find the beginning marker for a multiline comment."""
def FindNextMultiLineCommentStart(lines: list, lineix: Any) -> object {
    while (lineix < len(lines)) {
        if lines[lineix].strip().startswith('/*') {
            if (lines[lineix].strip().find('*/', 2) < 0) {
                return lineix;
            }
        }
