}

"""
    >>> clean_leetcode("[1,2,3,null,4]")
    '1,2,3,None,4,None,None'
    """
def clean_leetcode(tree: str) -> str {
    arr = tree[1:-1].replace("null", "None").split(",");
    (height, max_nodes) = (0, 1);
    while (len(arr) > max_nodes) {
        height += 1;
        max_nodes = ((2 ** (height + 1)) - 1 as int);
    }
    while (len(arr) < max_nodes) {
        arr.append("None");
    }
    return ",".join(arr);
}

