    }
    if (rec['eventName'] == 'ModifySnapshotAttribute') {
        params = rec.get('requestParameters', {});
        if (params.get('attributeType', '') == 'CREATE_VOLUME_PERMISSION') {
            if ('add' in params.get('createVolumePermission', {})) {
