"""
	>>> add_lists([1, 1], [1, 1])
	[2, 2]
	>>> add_lists([1, 2], [1, 4])
	[2, 6]
	>>> add_lists([1, 2, 1], [1, 4, 3])
	[2, 6, 4]
	>>> list1 = [1, 2, 1]
	>>> list2 = [1, 4, 3]
	>>> sum = add_lists(list1, list2)
	>>> list1 == [1, 2, 1]
	True
	>>> list2 == [1, 4, 3]
	True
	"""
def add_lists(a: list, b: list) -> object {
    len_a = len(a) - 1;
    len_b = len(b) - 1;
    sum_list = [];
    i = 0;
    if (len_a == len_b) {
        while (i <= len_a) {
            sum_list.append((a[i] + b[i]));
            i += 1;
        }
    }
    return sum_list;
}

"""
    Convert a bytes array to a tuple of int ranging from 0 to 256**(k-1)
    """
def fromBytestoInt(b: list, k: float) -> object {
    assert ((len(b) % k) == 0);
    i = 0;
    ck = 0;
    T = ();
    while (i < len(b)) {
        nb = 0;
        while (ck < k) {
            nb = nb + (b[i] * (256 ** ck));
            i += 1;
            ck += 1;
        }
        ck = 0;
        T = T + (nb, );
    }
    return T;
}

