    :param j: row index
    :param M:
    """
def get_pdistindex(i: float, j: int, M: float) -> object {
    if (i == j) {
        raise ValueError;
    }
    if (i < j) {
        (i, j) = (j, i);
    }
    return (((M * i) + j) - (((i + 2) * (i + 1)) // 2));
}

