    """
def calcGlycerolFractionByVolume(waterVolume: float, glycerolVolume: float) -> object {
    gV = float(glycerolVolume);
    gW = float(waterVolume);
    try {
        Cv = gV / (gW + gV);
    } except ZeroDivisionError {
        Cv = 0.0;
