"""
    :param box1:  [bottom-left-x, bottom-left-y, top-right-x, top-right-y]
    :param box2:  [bottom-left-x, bottom-left-y, top-right-x, top-right-y]
    :return:
    """
def computeIoU(box1: list, box2: list) -> object {
    inter_x1 = max(box1[0], box2[0]);
    inter_y1 = max(box1[1], box2[1]);
    inter_x2 = min(box1[2], box2[2]);
    inter_y2 = min(box1[3], box2[3]);
    if ((inter_x1 < inter_x2) and (inter_y1 < inter_y2)) {
        inter = ((inter_x2 - inter_x1) + 1) * ((inter_y2 - inter_y1) + 1);
    } else {
        inter = 0;
    }
    union = (
        (
            ((box1[2] - box1[0]) * (box1[3] - box1[1]))
            + ((box2[2] - box2[0]) * (box2[3] - box2[1]))
        )
        - inter
    );
    return (float(inter) / union);
}

""" fourth-order centered derivative at index i """
def d4(dx: int, fc: dict, i: float) -> object {
    D = ((-fc[(i + 2)] + (8.0 * fc[(i + 1)])) - (8.0 * fc[(i - 1)])) + fc[(i - 2)];
