    Parameters
    ----------
        n: integer
            number of coordinates to use between endpoints
        a: float
            starting point
        b: float
            ending point

    Returns
    -------
        coordinates: list
            list of n coordinates between the beginning point and including the endpoint spacing the interval into n+1 equal subdivisions
    """
def coor(n: float, a: int, b: float) -> object {
    coordinates = [];
    length = (b - a) / float((n + 1));
    for i in range((n + 1)) {
        coordinates.append((a + (length * (i + 1))));
    }
    return coordinates;
}

