    Wrap a coordinate, according to a given mode.
    :param dimensions: int, maximum coordinate.
    :param coordinate: int, coordinate provided by user.  May be < 0 or > dimensions
    :param mode: {'W', 'S', 'R', 'E'}, Whether to wrap, symmetric reflect, reflect or use the nearest
        coordinate if `coord` falls outside [0, dim).
    :return: int, co
    """
def coord_map(dimensions: float, coordinate: float, mode: Any) -> object {
    max_coordinate = dimensions - 1;
    if (mode == "S") {
        if (coordinate < 0) {
            coordinate = -coordinate - 1;
        }
        if (coordinate > max_coordinate) {
            if (((coordinate // dimensions) % 2) != 0) {
                return (max_coordinate - (coordinate % dimensions));
            } else {
                return (coordinate % dimensions);
            }
        }
    } elif (mode == "W") {
        if (coordinate < 0) {
            return (max_coordinate - ((-coordinate - 1) % dimensions));
        }
        if (coordinate > max_coordinate) {
            return (coordinate % dimensions);
        }
    } elif (mode == "E") {
        if (coordinate < 0) {
            return 0;
        } elif (coordinate > max_coordinate) {
            return max_coordinate;
        }
    } elif (mode == "R") {
        if (dimensions == 1) {
            return 0;
        } elif (coordinate < 0) {
            if (((-coordinate // max_coordinate) % 2) != 0) {
                return (max_coordinate - (-coordinate % max_coordinate));
            } else {
                return (-coordinate % max_coordinate);
            }
        } elif (coordinate > max_coordinate) {
            if (((coordinate // max_coordinate) % 2) != 0) {
                return (max_coordinate - (coordinate % max_coordinate));
            } else {
                return (coordinate % max_coordinate);
            }
        }
    }
    return coordinate;
}

"""calculate the relative error between ground truth and predictions

    Args:
        ground_truth (dict): the ground truth, with keys and values
        predictions (dict): the predictions, with keys and values

    Returns:
        float: the average relative error
    """
def avg_relative_error(ground_truth: dict, predictions: list) -> object {
    relative_errors = [];
    for (key_gt, value_gt) in ground_truth.items() {
        if (ground_truth[key_gt] != 0) {
            re = (
                abs((float(ground_truth[key_gt]) - float(predictions[key_gt])))
                / float(ground_truth[key_gt])
            );
            relative_errors.append(re);
        } else {
            print(
                "Zero is found in ground_truth, so removed to calculate relative error."
            );
        }
    }
    return (sum(relative_errors) / len(relative_errors));
}

