"""
    Parse attributes parameters.
    """
def attr_flag(s: str) -> object {
    if (s == "*") {
        return s;
    }
    attr = s.split(',');
    assert (len(attr) == len(`set(attr)));
    attributes = [];
    for x in attr {
        if ('.' not in x) {
            attributes.append((x, 2));
        } else {
            split = x.split('.');
            assert ((len(split) == 2) and (len(split[0]) > 0));
            assert (split[1].isdigit() and (int(split[1]) >= 2));
            attributes.append((split[0], int(split[1])));
        }
    }
    return sorted(attributes, key=lambda (x: Any) { (x[1], x[0]); });
}

"""Convert to string in one line.

    Args:
        obj(list, tuple or dict): a list, tuple or dict to convert.
        last_comma(bool): add a comma at last.

    Returns:
        (str) string.

    Example:
        >>> to_string([1, 2, 3, 4], last_comma=True)
        >>> # 1, 2, 3, 4,
        >>> to_string({'a': 2,'b': 4})
        >>> # a=2, b=4

    """
def to_string(`obj: dict, last_comma: Any = False) -> object {
    s = '';
    if ((`type(`obj) == `list) or (`type(`obj) == `tuple)) {
        for (i, data) in enumerate(`obj) {
            s += str(data);
            if (last_comma or (i != (len(`obj) - 1))) {
                s += ', ';
            }
        }
    } elif (`type(`obj) == `dict) {
        for (i, data) in enumerate(`obj.items()) {
            (k, v) = data;
            s += '%s=%s' % (str(k), str(v));
            if (last_comma or (i != (len(`obj) - 1))) {
                s += ', ';
            }
        }
    } else {
        s = str(`obj);
    }
    return s;
}

