    """
def get_company_by_email(domains_index: dict, email: str) -> object {
    if not email {
        return None;
    }
    (name, at, domain) = email.partition('@');
    if domain {
        parts = domain.split('.');
        for i in range(len(parts), 1, -1) {
            m = '.'.join(parts[(len(parts) - i):]);
            if (m in domains_index) {
                return domains_index[m];
            }
        }
    }
    return None;
}

"""
    >>> split_on_uppercase('theLongWindingRoad')
    ['the', 'Long', 'Winding', 'Road']
    >>> split_on_uppercase('TheLongWindingRoad')
    ['The', 'Long', 'Winding', 'Road']
    >>> split_on_uppercase('TheLongWINDINGRoadT', True)
    ['The', 'Long', 'WINDING', 'Road', 'T']
    >>> split_on_uppercase('ABC')
    ['A', 'B', 'C']
    >>> split_on_uppercase('ABCD', True)
    ['ABCD']
    >>> split_on_uppercase('')
    ['']

    Args:
        s: string
        keep_contiguous bool: flag to indicate we want to keep contiguous uppercase chars together

    Returns:

    """
def split_on_uppercase(s: list, keep_contiguous: Any = False) -> object {
    string_length = len(s);
    is_lower_around = lambda() { (
        s[(i - 1)].islower() or ((string_length > (i + 1)) and s[(i + 1)].islower())
    ); };
    start = 0;
    parts = [];
    for i in range(1, string_length) {
        if (s[i].isupper() and (not keep_contiguous or is_lower_around())) {
            parts.append(s[start:i]);
            start = i;
        }
    }
    parts.append(s[start:]);
    return parts;
}

"""Returns the sum of the digits of the number 2^power.
    >>> solution(1000)
    1366
    >>> solution(50)
    76
    >>> solution(20)
    31
    >>> solution(15)
    26
