    after the last / and the last #. Also replaces - and . with _.

    Parameters
    ----------
    key: str
        Some URI

    Returns
    -------
    key_short: str
        A shortened, but more ambiguous, identifier
    """
def shorter_name(key: str) -> object {
    key_short = key;
    for sep in ['#', '/'] {
