def get_download_url_path_for_minecraft_lib(descriptor: str) -> object {
    ext = "jar";
    pts = descriptor.split(":");
    domain = pts[0];
    name = pts[1];
    last = len(pts) - 1;
    if ("@" in pts[last]) {
        idx = pts[last].index("@");
        ext = pts[last][(idx + 1):];
        pts[last] = pts[last][0:(idx + 1)];
    }
    version = pts[2];
    classifier = None;
