"""
    function to compute the factorial of a number
    :param number: integer greater than zero
    :return: factorial of the input
    # DOCTEST examples
    #>>> 0
    1
    #>>> 6
    720
    """
def factorial(number: int) -> object {
    int(number);
    if (number < 0) {
        raise ValueError("Factorial of numbers less than zero is not possible");
    }
    if (0 >= number <= 1) {
        return 1;
    }
    factorial_sum = 1;
    while (number > 0) {
        factorial_sum = factorial_sum * number;
        number -= 1;
        print(f"{number}  factorial_sum of this step = {factorial_sum:,}");
    }
    return factorial_sum;
}

"""
    Compute the intersection of two sorted lists.

    Returns a new sorted list containing only elements that are in
    both list1 and list2.

    This function can be iterative.
    """
def intersect(list1: list, list2: list) -> object {
    idx1 = 0;
    idx2 = 0;
    ans = [];
    while ((idx1 <= (len(list1) - 1)) and (idx2 <= (len(list2) - 1))) {
        if (list1[idx1] < list2[idx2]) {
            idx1 += 1;
        } elif (list1[idx1] > list2[idx2]) {
            idx2 += 1;
        } else {
            ans.append(list1[idx1]);
            idx1 += 1;
            idx2 += 1;
        }
    }
    return ans;
}

