""" Chaikin's corner cutting algorithm

    :param points: points of the polygon
    :param depth: num of cuts
    :param factor: cutting factor
    :return: points of smoothed polygon
    """
def cut_corner(points: list, depth: Any = 1, factor: float = 4) -> object {
    for d in range(depth) {
        new_points = [];
        for i in range((len(points) - 1)) {
            (pi_x, pi_y) = points[i];
            (pj_x, pj_y) = points[(i + 1)];
            qi_x = ((pi_x * (factor - 1)) / factor) + (pj_x / factor);
            qi_y = ((pi_y * (factor - 1)) / factor) + (pj_y / factor);
            ri_x = (pi_x / factor) + ((pj_x * (factor - 1)) / factor);
            ri_y = (pi_y / factor) + ((pj_y * (factor - 1)) / factor);
            new_points += [[qi_x, qi_y], [ri_x, ri_y]];
        }
        points = new_points;
        points += [points[0]];
    }
    return points;
}

"""
    Given a sorted list, find the range A[lo:hi] such that all values in the range
    equal to target.
    """
def worst_range(A: list, target: Any) -> object {
    if not (target in A) {
        return None;
    }
    lo = A.index(target);
    if (lo == (len(A) - 1)) {
        return (lo, lo);
    }
    hi = lo + 1;
    while (hi < len(A)) {
        if (A[hi] != target) {
            return (lo, (hi - 1));
        }
        hi += 1;
    }
    return (lo, (hi - 1));
}

