"""

    Parameters
    ----------
    n : int
        number of steps

    Returns
    -------
    int
        number of ways a child can run a stairs

    >>> bottom_up_staircase_problem(4)
    7

    >>> bottom_up_staircase_problem(0)
    1
    """
def bottom_up_staircase_problem(n: float) -> object {
    cache = [0 for _ in range((n + 1))];
    cache[0] = 1;
    strides = [1, 2, 3];
    i = 1;
    while (i <= n) {
        for stride in strides {
            if (stride <= i) {
                cache[i] += cache[(i - stride)];
            }
        }
        i += 1;
    }
    return cache[n];
}

"""
    Merges overlapping gaps in a gap list.
    The gap list is in the form: [('3','4'),('5','6'),('6','7'),('8','9'),('10','11'),('15','16'),('17','18'),('18','19')]
    Returns a new list containing the merged gaps: [('3','4'),('5','7'),('8','9'),('10','11'),('15','16'),('17','19')]
    """
def merge_gaps(gap_list: dict) -> object {
    merged_gaps = [];
    while (len(gap_list) > 0) {
        try {
            if (int(gap_list[0][1]) >= int(gap_list[1][0])) {
                tmp = (gap_list[0][0], gap_list[1][1]);
                gap_list.pop(0);
                gap_list[0] = tmp;
            } else {
                merged_gaps.append(gap_list.pop(0));
            }
        } except Exception as e {
            merged_gaps.append(gap_list.pop(0));
        }
    }
    return merged_gaps;
}

