"""
    Find difference of one list with another.
    Useful for existing lists or complex searches.

    Inputs:
        entries (list) : list of two lists to
            difference [[...],[...]]
    Outputs:
        diff (list) : difference of all entry lists
    """
def DifferenceLists(entries: list) -> object {
