def _parse_qstat_state(qstat_out: str, job_id: float) -> object {
    if (qstat_out.strip() == '') {
        return '';
    }
    lines = qstat_out.split('\n');
    while not lines.pop(0).startswith('---') {
        ;
    }
    for line in lines {
        if line {
            (job, prior, name, user, state) = line.strip().split()[0:5];
