);

import from "react" { useCallback, useRef }

def:pub useInfiniteScrollingObserver(
    status: str,
    fetch: object,
    setQueryParams: object,
    hasMore: bool,
    threshold: float = 0.5
) -> list[object] {
    observer = useRef(None);

    def last_element_ref(element: object) {
        if status == "LOADING MORE" {
            return;
        }
        if observer.current {
            observer.current.disconnect();
        }
        def on_intersect(entries: list[object]) {
            `entry = entries[0] as dict[str, object];
            if `entry["isIntersecting"] and hasMore {
            }
        }
        observer.current = new(IntersectionObserver, on_intersect, {"threshold": threshold});  # jac:ignore[E1053]
        if element {
            observer.current.observe(element);
        }
    }

    callback = useCallback(last_element_ref, [fetch, setQueryParams, hasMore, status, threshold]);
    return [callback];
}

