class Queue[T] {
    has _items: list[T] = [];

    def init(array: list[T] | None = None) {
        self._items = list(array) if array is not None else [];
    }

    def enqueue(item: T) {
        self._items.insert(0, item);
    }

    def dequeue() -> T {
        return self._items.pop();
    }

    def clear {
        self._items = [];
    }

    def isEmpty() -> bool {
        return len(self._items) == 0;
    }

    def toArray() -> list[T] {
        return list(self._items);
    }
}

