import os;
import asyncio;
import from "child_process" { `spawn as nativeSpawn, SpawnOptions, ChildProcess }

def log(data: str) {
    console.log(f"{data}");
}

async def `spawn(command: str, args: list[str], options: SpawnOptions | None = None) -> ChildProcess {
    env = {**os.environ, "FORCE_COLOR": "true"};
    opts = (options or {}) | {"env": env};
    child = nativeSpawn(command, args, opts);
    loop = asyncio.get_event_loop();
    done = loop.create_future();
    child.stdout.on("data", log);
    child.stderr.on("data", log);
    child.on("close", lambda (code: int) {
        if code != 0 {
            done.set_exception(RuntimeError(f"Process exited with code {code}"));
        } else {
            done.set_result(child);
        }
    });
    return await done;
}

def indexOfOrDefault[T](array: list[T] | None = None, item: T | None = None, defaultValue: int = -1) -> int {
    arr = array if array is not None else [];
    index = arr.index(item);
    if index < 0 {
        index = defaultValue;
    }
    return index;
}

