def _mapIdsToNodes(
    ids: list[str] | None,
    nodes: dict[str, NormalizedDynamicBookmark],
) -> list[NormalizedDynamicBookmark] {
    idList = ids if ids is not None else [];
    return [nodes[nodeId] for nodeId in idList if nodeId in nodes];
}

def _traverseTree(
    bookmark: NormalizedDynamicBookmark,
    nodes: dict[str, NormalizedDynamicBookmark],
    trackedByNodeId: dict[str, bool],
) -> bool {
    tracked = isTracked(bookmark);
    if isFolder(bookmark) {
        children = _mapIdsToNodes(bookmark.children, nodes);
        for child in children {
            if _traverseTree(child, nodes, trackedByNodeId) {
                tracked = True;
            }
        }
    }
    if tracked {
        trackedByNodeId[bookmark.id] = True;
    }
    return tracked;
}

