def:pub useClickAway(ref: Ref[object], onClickAway: Callable[[Event], None], events: list[str] = defaultEvents) {
    savedCallback = useRef(onClickAway);
    useEffect(lambda {
        savedCallback.current = onClickAway;
    }, [onClickAway]);
    useEffect(lambda {
        def handler(event: Event) {
            el = ref.current;
            if el and not el.contains(event.target as object) {  # jac:ignore[E1030]
                savedCallback.current(event);
            }
        }
        for eventName in events {
            on(document, eventName, handler);
        }
        return lambda {
            for eventName in events {
                off(document, eventName, handler);
            }
        };
    }, [events, ref]);
}

