import re;
import from "./dateUtils.jac" { formatDateKey }

def parsePriority(value: str) -> str | None {
    lower = value.lower();
    if lower in ["high", "urgent", "critical", "1"] {
        return "high";
    }
    if lower in ["medium", "med", "2"] {
        return "medium";
    }
    if lower in ["low", "3"] {
        return "low";
    }
    return None;
}

def parseDueDate(dateStr: str) -> str | None {
    lower = dateStr.lower().strip();
    if re.match(r"^\d{4}-\d{2}-\d{2}$", lower) {
        return lower;
    }
    today = Date();
    if lower == "today" {
        return formatDateKey(today) as str;
    }
    if lower == "tomorrow" {
        tomorrow = Date(today.getTime() + (24 * 60 * 60 * 1000));
        return formatDateKey(tomorrow) as str;
    }
    days = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
    if lower in days {
        dayIndex = days.index(lower);
        currentDay = today.getDay();
        daysAhead = dayIndex - currentDay;
        if daysAhead <= 0 {
            daysAhead = daysAhead + 7;
        }
        target = Date(today.getTime() + (daysAhead * 24 * 60 * 60 * 1000));
        return formatDateKey(target) as str;
    }
    return None;
}

