def:pub shallowEqual(objA: object | int | float | str | bool | None, objB: object | int | float | str | bool | None) -> bool {
    if (`is(objA, objB)) {
        return True;
    }
    if (not isinstance(objA, dict) or objA is None or not isinstance(objB, dict) or objB is None) {
        return False;
    }
    keysA = list(objA.keys());
    keysB = list(objB.keys());
    if (len(keysA) != len(keysB)) {
        return False;
    }
    for i = 0 while i < len(keysA) with i += 1 {
        key = keysA[i];
        if (not _has_own(objB, key) or not `is(objA[key], objB[key])) {
            return False;
        }
    }
    return True;
}

