import json;

def:pub decycle(object: object, replacer: Callable[[object], object] | None = None) -> object {
    objects: dict[int, str] = {};

    def derez(value: object, path: str) -> object {
        if replacer is not None {
            value = replacer(value);
        }
        if (
            (isinstance(value, dict) or isinstance(value, list))
            and value is not None
        ) {
            old_path = objects.get(id(value));
            if old_path is not None {
                return {"$ref": old_path};
            }
            objects[id(value)] = path;
            if isinstance(value, list) {
                new_item: list[object] = [];
                for (i, element) in enumerate(value) {
                    new_item.append(derez(element, path + f"[{i}]"));
                }
                return new_item;
            }
            new_item: dict[str, object] = ({} as list[object]);
            for name in value.keys() {
                new_item[name] = derez(
                    value[name],
                    path + f"[{json.dumps(name)}]"
                );
            }
            return new_item;
        }
        return value;
    }

    return derez(object, "$");
}

import math;
import re;


def:pub formatNumber(val: int | str, decimal: int = 2, autoPadZero: bool = True) -> str {
    num = float(str(val));
    if math.isnan(num) {
        return "-";
    }
    parts = str(num).split(".");
    b = parts[1] if len(parts) > 1 else None;
    trunc_str = f"{int(num):,}";
    str_val = f"{trunc_str}.{b}" if b is not None else trunc_str;
    if autoPadZero {
        split_parts = str_val.split(".");
        a = split_parts[0];
        b_part = split_parts[1] if len(split_parts) > 1 else "";
        if len(b_part) < decimal {
            str_val = f"{a}.{b_part}{'0' * (decimal - len(b_part))}";
        }
    }
    if decimal == 0 {
        return re.sub(r"\.\d*$", "", str_val);
    }
    return re.sub(r"\.\d*$", lambda (m: re.Match[str]) { m.group(0)[:decimal + 1] }, str_val);
}


