glob:pub PATH_PARAM_RE: str = r"\{[^{}]+\}";

def:pub defaultPathSerializer(pathSerializer: PathSerializer) -> str {
    path = pathSerializer.path;
    url = pathSerializer.url;
    _url = pathSerializer.url;
    matches = re.findall(PATH_PARAM_RE, _url);
    if matches {
        for `match in matches {
            explode = False;
            name = `match[1:-1];
            style = "simple";
            if name.endswith("*") {
                explode = True;
                name = name[0:-1];
            }
            if name.startswith(".") {
                name = name[1:];
                style = "label";
            } elif name.startswith(";") {
                name = name[1:];
                style = "matrix";
            }
            value = path.get(name);
            if value is None {
                continue;
            }
            if isinstance(value, list) {
                url = url.replace(
                    `match,
                    serializeArrayParam({
                        "explode": explode,
                        "name": name,
                        "style": style,
                        "value": value,
                    }),
                    1,
                );
                continue;
            }
            if isinstance(value, dict) {
                url = url.replace(
                    `match,
                    serializeObjectParam({
                        "explode": explode,
                        "name": name,
                        "style": style,
                        "value": value,
                        "valueOnly": True,
                    }),
                    1,
                );
                continue;
            }
            if style == "matrix" {
                url = url.replace(
                    `match,
                    ";" + serializePrimitiveParam({"name": name, "value": str(value)}),
                    1,
                );
                continue;
            }
            replaceValue = quote(
                ("." + str(value)) if style == "label" else str(value),
                safe="-_.!~*'()",
            );
            url = url.replace(`match, replaceValue, 1);
        }
    }
    return url;
}

def:pub getUrl(
    querySerializer: QuerySerializer,
    url: str,
    baseUrl: str | None = None,
    path: dict[str, object] | None = None,
    query: dict[str, object] | None = None,
) -> str {
    pathUrl = url if url.startswith("/") else ("/" + url);
    result = (baseUrl if baseUrl is not None else "") + pathUrl;
    if path is not None {
        result = defaultPathSerializer(PathSerializer(path=path, url=result));
    }
    search = querySerializer(query) if query is not None else "";
    if search.startswith("?") {
        search = search[1:];
    }
    if search {
        result += "?" + search;
    }
    return result;
}

def:pub getValidRequestBody(
    body: object | None = None,
    bodySerializer: BodySerializer | None = None,
    serializedBody: object | None = None,
) -> object | None {
    hasBody = body is not None;
    isSerializedBody = hasBody and bodySerializer is not None;
    if isSerializedBody {
        if serializedBody is not None {
            hasSerializedBody = serializedBody != "";
            return serializedBody if hasSerializedBody else None;
        }
        return body if body != "" else None;
    }
    if hasBody {
        return body;
    }
    return None;
}

