def:pub checkRateLimit(identifier: str) -> dict[str, object] | None {
    now = int(time.time() * 1000);
    `entry = hits.get(identifier);
    if `entry is None or `entry["resetAt"] <= now {
        hits[identifier] = {"count": 1, "resetAt": now + windowMs};
        return None;
    }
    `entry["count"] = `entry["count"] + 1;
    if `entry["count"] > maxRequests {
        retryAfter = int(math.ceil((`entry["resetAt"] - now) / 1000));
        return {
            "status": 429,
            "body": {
                "error": {
                    "code": "RATE_LIMITED",
                    "message": f"Too many requests. Retry after {retryAfter}s.",
                    "retry_after": retryAfter,
                },
            },
            "headers": {
                "Retry-After": str(retryAfter),
                "X-RateLimit-Limit": str(maxRequests),
                "X-RateLimit-Remaining": "0",
                "X-RateLimit-Reset": str(int(math.ceil(`entry["resetAt"] / 1000))),
            },
        };
    }
    return None;
}

