    if isinstance(value, dict) {
        maybeMessage = str(value["message"]) if "message" in value else "";
        maybeStack = str(value["stack"]) if "stack" in value else "";
        return f"{maybeMessage} {maybeStack}";
    }
    return str(value);
}

def isRecoverableChunkLoadError(value: object | str | int | float | bool | None) -> bool {
    text = getErrorText(value);
    return (
        ("ChunkLoadError" in text)
        or ("Loading chunk" in text)
        or ("/_next/static/chunks/" in text)
        or (("MIME type" in text) and ("text/html" in text))
        or ("ERR_ABORTED 404" in text)
    );
}

def reloadOnceForFreshChunks() -> None {
    now: float = Date.now() as float;
    stored = window.sessionStorage.getItem(CHUNK_RECOVERY_KEY);  # jac:ignore[E1030]
    lastAttempt: float = float(stored as str) if stored else 0.0;
    if (now - lastAttempt) < CHUNK_RECOVERY_COOLDOWN_MS {
        return;
    }
    window.sessionStorage.setItem(CHUNK_RECOVERY_KEY, String(now));  # jac:ignore[E1030]
    window.location.reload();  # jac:ignore[E1030]
}

def:pub useChunkLoadRecovery() -> None {
    useEffect(lambda {
        def handleError(event: object) {
            target = event?.target;
            scriptSrc = target?.src;
            linkHref = target?.href;
            resourceUrl = (scriptSrc or linkHref or "") as str;
            errObj = event?.error;
            errMsg = event?.message;
            errFile = event?.filename;
            errorDetails: object | str = errObj or errMsg or errFile or resourceUrl;
            if isRecoverableChunkLoadError(errorDetails) or ("/_next/static/" in resourceUrl) {
                reloadOnceForFreshChunks();
            }
        }
        def handleUnhandledRejection(event: object) {
            reason = event?.reason;
            if isRecoverableChunkLoadError(reason) {
                reloadOnceForFreshChunks();
            }
        }
        window.addEventListener("error", handleError, True);  # jac:ignore[E1030]
        window.addEventListener("unhandledrejection", handleUnhandledRejection);  # jac:ignore[E1030]
        return lambda {
            window.removeEventListener("error", handleError, True);  # jac:ignore[E1030]
            window.removeEventListener("unhandledrejection", handleUnhandledRejection);  # jac:ignore[E1030]
        };
    }, []);
}

def:pub useSessionToolChunkPrefetch(enabled: bool = True) -> None {
    useEffect(lambda {
        if not enabled {
            return;
        }
        cancelled = False;
        Promise.all([
            `import("@monaco-editor/react"),  # jac:ignore[W2001]
            `import("@excalidraw/excalidraw"),  # jac:ignore[W2001]
        ]).catch(lambda (error: object) {
            if (not cancelled) and isRecoverableChunkLoadError(error) {
                reloadOnceForFreshChunks();
            }
        });
        return lambda { cancelled = True; };
    }, [enabled]);
}

