"""Trace every pipeline route from an intake valve, tolerating dead ends.

The visit statement's else clause logs a dead end gracefully instead
of failing silently, and finishes the walk when it truly runs dry.
"""

node Valve {
    has name: str;
    has pressure: float;
}

edge Pipe {
    has capacity: int;
}

walker Tracer {
    has route: list[str] = [];
    has dead_ends: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can `flow with Valve entry {
        self.route.append(here.name);
        print(f"pressure {here.pressure} bar at valve {here.name}");

        # No outgoing pipes? Log it and carry on with whatever is queued
        visit [->:Pipe:->] else {
            print(f"  dead end at {here.name}");
            self.dead_ends += 1;
        }
    }

    can finish with Root exit {
        print("-- Trace summary --");
        print("Route: " + " -> ".join(self.route));
        print(f"Dead ends hit: {self.dead_ends}");
    }
}

with entry {
    intake = Valve(name="Intake", pressure=4.2);
    splitter = Valve(name="Splitter", pressure=3.1);
    filter_a = Valve(name="FilterA", pressure=2.0);
    cap = Valve(name="Cap", pressure=1.1);

    root ++> intake;
    intake +>: Pipe(capacity=100) :+> splitter;
    splitter +>: Pipe(capacity=40) :+> filter_a;
    filter_a +>: Pipe(capacity=10) :+> cap;

    root spawn Tracer();
}

"""Org-chart salary and headcount rollup.

Employees report to managers through ReportsTo edges (report -> manager).
A rollup walker descends from the CEO to every employee, and because exit
abilities are deferred until all descendants finish, each manager's exit
sees the completed subtree totals of every direct report -- a bottom-up
post-order aggregation without any explicit recursion.
"""

node Employee {
    has name: str;
    has salary: int;
    has rollup_salary: int = 0;
    has team_size: int = 0;
}

edge ReportsTo: Employee --> Employee {}

walker OrgRollup {
    has headcount: int = 0;

    can descend with Employee entry {
        self.headcount += 1;
        visit [<-:ReportsTo:<-];  # step down to direct reports
    }

    can tally with Employee exit {
        # Every subordinate below has already exited, so its rollup
        # fields are final and can be folded in here.
        total_salary = here.salary;
        total_people = 1;
        for `report in [<-:ReportsTo:<-] {
            total_salary += `report.rollup_salary;
            total_people += `report.team_size + 1;  # report + their subtree
        }
        here.rollup_salary = total_salary;
        here.team_size = total_people - 1;
    }
}

with entry {

    # Reset leftovers from any previous run of this demo.
    for stale_node in [root -->][?:Employee] {
        del stale_node;
    }
    ceo = Employee(name="Morgan (CEO)", salary=500);
    eng_vp = Employee(name="Lee (VP Eng)", salary=300);
    sales_vp = Employee(name="Pat (VP Sales)", salary=280);
    dev1 = Employee(name="Sasha (Dev)", salary=150);
    dev2 = Employee(name="Jamie (Dev)", salary=140);
    qa = Employee(name="Riley (QA)", salary=120);
    acct = Employee(name="Casey (Acct)", salary=110);

    dev1 +>: ReportsTo() :+> eng_vp;
    dev2 +>: ReportsTo() :+> eng_vp;
    qa +>: ReportsTo() :+> eng_vp;
    acct +>: ReportsTo() :+> sales_vp;
    eng_vp +>: ReportsTo() :+> ceo;
    sales_vp +>: ReportsTo() :+> ceo;

    result = ceo spawn OrgRollup();

    print(f"Org headcount: {result.headcount}");
    print(f"{'Employee':<20} {'Own':>5} {'TeamPay':>8} {'TeamSize':>9}");
    for emp in [ceo, eng_vp, sales_vp, dev1] {
        print(
            f"{emp.name:<20} {emp.salary:>5} "
            f"{emp.rollup_salary:>8} {emp.team_size:>9}"
        );
    }
    print(f"Total payroll (CEO subtree): {ceo.rollup_salary}");
}

"""Warehouse supply-chain demand propagation.

The network flows upstream through Supplies edges (factory -> depot ->
store) whose capacity splits how demand is shared. Demand packets are
spawned as walkers at retail stores; each facility adds its received
quantity to its backlog, then forwards the demand upstream, splitting it
across supplier lanes proportionally to lane capacity.
"""

node Facility {
    has name: str;
    has kind: str;      # "factory" | "depot" | "store"
    has backlog: int = 0;
}

edge Supplies: Facility --> Facility {
    has capacity: int;
}

walker DemandPacket {
    has qty: int;

    can `flow with Facility entry {
        here.backlog += self.qty;

        # Demand flows against the Supplies direction: upstream
        # suppliers are the sources of this facility's incoming lanes.
        suppliers = [<-:Supplies:<-];
        lanes = [edge <-:Supplies:<-];
        if len(suppliers) == 0 {
            skip;  # reached a source (factory): demand stops here
        }

        total_capacity = 0;
        for lane in lanes {
            total_capacity += lane.capacity;
        }

        for i in range(len(suppliers)) {
            lane = lanes[i];
            share = int(self.qty * lane.capacity / total_capacity);
            if share > 0 {
                upstream = suppliers[i];
                upstream spawn DemandPacket(qty=share);
            }
        }
    }
}

with entry {

    # Reset leftovers from any previous run of this demo.
    for stale_node in [root -->][?:Facility] {
        del stale_node;
    }
    factory_north = Facility(name="Factory North", kind="factory");
    factory_south = Facility(name="Factory South", kind="factory");
    depot_east = Facility(name="Depot East", kind="depot");
    depot_west = Facility(name="Depot West", kind="depot");
    store_a = Facility(name="Store A", kind="store");
    store_b = Facility(name="Store B", kind="store");

    # Big lane north (3x), small lane south; two lanes into Depot East.
    factory_north +>: Supplies(capacity=300) :+> depot_west;
    factory_south +>: Supplies(capacity=100) :+> depot_west;
    factory_north +>: Supplies(capacity=200) :+> depot_east;
    factory_south +>: Supplies(capacity=200) :+> depot_east;
    depot_west +>: Supplies(capacity=150) :+> store_a;
    depot_east +>: Supplies(capacity=150) :+> store_a;
    depot_east +>: Supplies(capacity=400) :+> store_b;

    # Weekend orders placed at the retail stores.
    store_a spawn DemandPacket(qty=90);
    store_b spawn DemandPacket(qty=120);

    network = [
        factory_north,
        factory_south,
        depot_east,
        depot_west,
        store_a,
        store_b,
    ];
    print("Backlog per facility after propagation:");
    for site in network {
        label = site.name;
        load = site.backlog;
        print(f"  {site.kind:<8} {label:<14} {load:>4} units");
    }
}

