"""Return decoded text if it's not already bytes."""
def safe_decode(txt: object) -> object {
    try {
        return (txt as bytes).decode();
    } except AttributeError {
        return txt;
    }
}

"""The lLeetCode solutions runner judges this to be the fastest of all four."""
def findComplement_v4(num: int) -> int {
    mask: int = ((2 ** num.bit_length()) - 1) as int;
    if mask < 1 {
        mask = 1;
    }
    return num ^ mask;
}

"""
    :param img_ratio: Float
    :param monitor_ratio: Float
    :param file: Str
    :return: Bool
    """
def same_ratio(img_ratio: float, monitor_ratio: float, file: str) -> bool {
    file as str;
    percent = img_ratio / monitor_ratio;
    diff = int((abs((percent - 1)) * 100));
    if (percent > 1) {
        print(
            (
                "Image is "
                + str(diff)
                + "% too wide for screen. Sides must be cropped off, or top/bottom filled."
            )
        );
        same = False;
    } elif (percent < 1) {
        print(
            (
                "Image is "
                + str(diff)
                + "% too narrow for screen. Top/bottom must be cropped off, or sides filled."
            )
        );
        same = False;
    } else {
        print("Image is the same aspect ratio as the screen.");
        n = input("Press enter to exit.");
        n as str;
        same = True;
    }
    return same;
}

"""A tuple containing x- and y- slice tuples from a string or tuple."""
def tupletupleint(
    items: str | tuple[tuple[int | float | str, int | float | str], tuple[int | float | str, int | float | str]]
) -> tuple[tuple[int, int], tuple[int, int]] {
    if isinstance(items, str) {
        text: str = items as str;
        for s in " ()[]" {
            text = text.replace(s, "");
        }
        (x1, x2, y1, y2) = text.split(",");
        out = ((int(float(x1)), int(float(x2))), (int(float(y1)), int(float(y2))));
    } else {
        ((x1, x2), (y1, y2)) = items;
        out = ((int(float(x1)), int(float(x2))), (int(float(y1)), int(float(y2))));
    }
    return out;
}

"""
    Remaps input_val from source domain to target domain.
    No clamping is performed, the result can be outside of the target domain
    if the input is outside of the source domain.
    """
def remap_unbound(
    input_val: int | float,
    in_from: int | float,
    in_to: int | float,
    out_from: int | float,
    out_to: int | float,
) -> int | float {
    out_range = out_to - out_from;
    in_range = in_to - in_from;
    in_val = input_val - in_from;
    val = (float(in_val) / in_range) * out_range;
    out_val = out_from + val;
    return out_val;
}

"""
    Calculates goodness of fit for the provided values, and scales based on the total number of individuals that exist.
    The calculation is 1 - (abs(x - y)/max(x, y)) * n/n_tot for x, y simulated and actual values, n, n_tot for metric
    and total
    number of individuals.

    :param simulated_value: the simulated value of the metric
    :param actual_value: the actual value of the metric
    :param number_individuals: the number of individuals this metric relates to
    :param total_individuals: the total number of individuals across all sites for this metric
    :return: the scaled fit value
    """
def scale_simulation_fit(
    simulated_value: float,
    actual_value: float,
    number_individuals: int,
    total_individuals: int
) -> float {
    return (
        (
            (
                1.0
                - (
                    abs(simulated_value - actual_value)
                    / max(simulated_value, actual_value)
                )
            )
            * number_individuals
        )
        / total_individuals
    );
}

"""
    Gets a string representing the number of seconds in hours, minutes, and seconds,
    but will not print leading zeroes.
    """
def time_string(seconds: int) -> str {
    (minutes, seconds) = divmod(seconds, 60);
    (hours, minutes) = divmod(minutes, 60);
    hour_string = ("%dh " % hours) if (hours > 0) else "";
    minute_string = ("%dm " % minutes) if (minutes > 0) else "";
    second_string = ("%ds" % seconds) if (seconds > 0) else "";
    return ("%s%s%s" % (hour_string, minute_string, second_string));
}

"""Get maximal x for the points."""
def _gr_ymax_(graph: list[tuple[int | float, int | float]]) -> int | float | None {
    ymx: int | float | None = None;
    for (_, y) in graph {
        if ymx is None {
            ymx = y;
        } elif y >= ymx {
            ymx = y;
        }
    }
    return ymx;
}

"""
    Returns bytearray of at least size bytes equivalent of integer n that is
    left zero padded to size bytes. For n positive, if the bytearray
    equivalent of n is longer than size  and strict is False the bytearray
    is extended to the length needed to fully represent n. Otherwise if strict
    is True or n is negative it is truncated to the least significant size bytes.

    Big endian is the default.
    If reverse is true then it reverses the order of the bytes in the resultant
    bytearray for little endian with right zero padding.
    """
def bytify(
    n: int = 0, size: int = 1, reverse: bool = False, strict: bool = False
) -> bytearray {
    if n < 0 or strict {
        n = n & (((2 ** (size * 8)) - 1) as int);
    }
    b = bytearray();
    count = 0;
    while n {
        b.insert(0, (n & 255));
        count += 1;
        n >>= 8;
    }
    if count < size {
        b = bytearray(([0] * (size - count))) + b;
    }
    if reverse {
        b.reverse();
    }
    return b;
}

