"""
Calculate the max needed length for a output col by getting the headline, the content of the rows
(different data types) and in some cases a specific key
"""
def col_length(headline: str, content: list[str] | dict | int, dict_key: str | None = None) -> int {
    length = len(headline);
    if type(content) == list {
        for x in content {
            if type(x) == str {
                if len(x) > length {
                    length = len(x);
                }
            }
        }
    } elif type(content) == dict {
        for key in content {
            if type(content[key]) == dict {
                if dict_key in (content[key] as dict) {
                    if len(str((content[key] as dict)[dict_key as str])) > length {
                        length = len(str((content[key] as dict)[dict_key as str]));
                    }
                } else {
                    x = key;
                    for key in content[x] {
                        if type(content[x][key]) == dict {
                            if dict_key in (content[x][key] as dict) {
                                if type(content[x][key]) == dict {
                                    if len((content[x][key] as dict)[dict_key as str]) > length {
                                        length = len((content[x][key] as dict)[dict_key as str]);
                                    }
                                }
                            }
                        }
                    }
                }
            } elif type(content[key]) == int or type(content[key]) == float {
                if len(str(content[key])) > length {
                    length = len(str(content[key]));
                }
            }
        }
    } elif type(content) == int {
        if len(str(content)) > length {
            length = len(str(content));
        }
    }
    return length;
}

"""
    Takes two sorted lists of tuples and returns a
    combined list sorted by lowest first element
    Paramters:
      a, b - a sorted list of tuples
    """
def order_to_process(a: list, b: list) -> list {
    ret_l: list = [];
    while (a and b) {
        ret_l.append(a.pop(0) if (a <= b) else b.pop(0));
    }
    ret_l.extend(a);
    ret_l.extend(b);
    return ret_l;
}

"""divide a by b and round result to the nearest integer

    When the ratio is exactly half-way between two integers,
    the even integer is returned.
    """
def _divide_and_round(a: int, b: int) -> int {
    (q, r) = divmod(a, b);
    r *= 2;
    greater_than_half = (r > b) if (b > 0) else (r < b);
    if (greater_than_half or ((r == b) and ((q % 2) == 1))) {
        q += 1;
    }
    return q;
}

