"""Converts the pixel to grayscale using the given weights (or 1 by default) casting to int"""
def gray(px: list, *weights: float, cast: type = int) -> object {
    y: float = cast(0) as float;
    w: float = cast(0) as float;
    for x in range(len(px)) {
        z: float = cast(px[x]) as float;
        try {
            y += z * weights[x];
            w += weights[x];
        } except Exception {
            y += z;
            w += 1;
        }
    }
    return (y / w);
}

