"""
Calculate the max needed length for a output col by getting the headline, the content of the rows
(different data types) and in some cases a specific key
"""
def col_length(headline: str, content: list[str] | dict[str, dict[str, str] | int | float] | int, dict_key: str | None = None) -> int {
    length = len(headline);
    if type(content) == list {
        for x in content {
            if type(x) == str {
                if len(x) > length {
                    length = len(x);
                }
            }
        }
    } elif type(content) == dict {
        for key in content {
            if type(content[key]) == dict {
                row_dict = content[key] as dict;
                if dict_key in row_dict {
                    cell = row_dict[dict_key] as str;
                    if len(str(cell)) > length {
                        length = len(str(cell));
                    }
                } else {
                    x = key;
                    outer_dict = content[x] as dict;
                    for key in outer_dict {
                        if type(outer_dict[key]) == dict {
                            inner_dict = outer_dict[key] as dict;
                            if dict_key in inner_dict {
                                if type(inner_dict[dict_key]) == dict {
                                    nested_cell = inner_dict[dict_key] as dict;
                                    if len(nested_cell) > length {
                                        length = len(nested_cell);
                                    }
                                }
                            }
                        }
                    }
                }
            } elif type(content[key]) == int or type(content[key]) == float {
                if len(str(content[key])) > length {
                    length = len(str(content[key]));
                }
            }
        }
    } elif type(content) == int {
        if len(str(content)) > length {
            length = len(str(content));
        }
    }
    return length;
}

"""Try really hard to scale 'points' by 'scalar'.

    @type  points: mixed
    @param points: Points can either be:

        - a sequence of pairs, in which case the second item will be scaled,
        - a list, or
        - a number

    @type  scalar: number
    @param scalar: the amount to multiply points by
    """
def scale(points: list | int | float, scalar: int | float) -> object {
    if (`type(points) is `list) {
        try {
            return [(k, (p * scalar)) for (k, p) in points];
        } except TypeError {
            return [(p * scalar) for p in points];
        }
    } else {
        return (points * scalar);
    }
}

