"""Merge sort, duh?

    :param list: List of things to sort
    :return: Cool sorted list
    """
def merge_sort(`list: list) -> list {
    if (len(`list) > 1) {
        middle = len(`list) // 2;
        left: list = merge_sort(`list[:middle]);
        right: list = merge_sort(`list[middle:]);
        `list: list = [];
        while ((len(left) > 0) and (len(right) > 0)) {
            if (left[0] < right[0]) {
                `list.append(left[0]);
                left.pop(0);
            } else {
                `list.append(right[0]);
                right.pop(0);
            }
        }
        for item in left {
            `list.append(item);
        }
        for item in right {
            `list.append(item);
        }
    }
    return `list;
}

"""Returns a list of numbers with a certain relation to each other.

    The function divides one number into a list of d numbers [n0, n1, ...], such
    that their sum is number and the relation between the numbers is defined
    with n1 = n0 / r, n2 = n1 / r, n3 = n2 / r, ...
    """
def range_geometric_row(number: float, d: int, r: float = 1.1) -> list[float] {
    if (r <= 0) {
        raise ValueError("r must be > 0");
    }
    n0: float = number / ((1 - ((1 / r) ** d)) / (1 - (1 / r)));
    numbers: list[float] = [n0];
    for i in range((d - 1)) {
        numbers.append((numbers[-1] / r));
    }
    return numbers;
}

