    cn: dict[str, str] = {};
    for pair in connection_string.split(";") {
        suffix: str = "";
        pair_text: str = pair;
        if pair.endswith("=") {
            pair_text = pair.rstrip("=");
            suffix = "=";
        }
        parts: list[str] = pair_text.split("=");
        key: str = parts[0];
        value: str = parts[1];
        value += suffix;
        cn[key] = value;
    }
    return cn;
}

