def __extract_network_from_docker_container(docker_container: dict) -> str {
    network_bindings = docker_container.get("networkBindings");
    bindings: list[str] | str = [];
    if network_bindings {
        bindings = [
            (
                (network["bindIP"] as str)
                + " ("
                + str(network["hostPort"])
                + "[host] -> "
                + str(network["containerPort"])
                + "[network])"
            ) for network in (network_bindings as list[dict])
        ];
    }
    if (bindings is []) {
        bindings = "no network binding";
    } else {
        bindings = ", ".join(bindings as list[str]);
    }
    return ((docker_container["name"] as str) + " -> " + bindings as str);
}

"""
    Takes an attribute name and tries to make it HTML correct.

    This function takes an attribute name as a string, as it may be
    passed in to a formatting method using a keyword-argument syntax,
    and tries to convert it into a real attribute name.  This is
    necessary because some attributes may conflict with Python
    reserved words or variable syntax (such as 'for', 'class', or
    'z-index'); and also to help with backwards compatibility with
    older versions of MoinMoin where different names may have been
    used (such as 'content_id' or 'css').

    Returns a tuple of strings: (namespace, attribute).

    Namespaces: The default namespace is always assumed to be 'html',
    unless the input string contains a colon or a double-underscore;
    in which case the first such occurance is assumed to separate the
    namespace prefix from name.  So, for example, to get the HTML
    attribute 'for' (as on a <label> element), you can pass in the
    string 'html__for' or even '__for'.

    Hyphens:  To better support hyphens (which are not allowed in Python
    variable names), all occurances of two underscores will be replaced
    with a hyphen.  If you use this, then you must also provide a
    namespace since the first occurance of '__' separates a namespace
    from the name.

    Special cases: Within the 'html' namespace, mainly to preserve
    backwards compatibility, these exceptions ars recognized:
    'content_type', 'content_id', 'css_class', and 'css'.
    Additionally all html attributes starting with 'on' are forced to
    lower-case.  Also the string 'xmlns' is recognized as having
    no namespace.

    Examples:
        'id' -> ('html', 'id')
        'css_class' -> ('html', 'class')
        'content_id' -> ('html', 'id')
        'content_type' -> ('html', 'type')
        'html__for' -> ('html', 'for)
        'xml__space' -> ('xml', 'space')
        '__z__index' -> ('html', 'z-index')
        '__http__equiv' -> ('html', 'http-equiv')
        'onChange' -> ('html', 'onchange')
        'xmlns' -> ('', 'xmlns')
        'xmlns__abc' -> ('xmlns', 'abc')

    (In actuality we only deal with namespace prefixes, not any real
    namespace URI...we only care about the syntax not the meanings.)
    """
def rewrite_attribute_name(name: str, default_namespace: str = 'html') -> tuple[str, str] {
    if (':' in name) {
        parts: list[str] = name.split(':', 1);
        ns = parts[0];
        name = parts[1];
    } elif ('__' in name) {
        parts: list[str] = name.split('__', 1);
        ns = parts[0];
        name = parts[1];
    } elif (name == 'xmlns') {
        ns = '';
    } else {
        ns = default_namespace;
    }
    name.replace('__', '-');
    if (ns == 'html') {
        if (name == 'content_type') {
            name = 'type';
        } elif (name == 'content_id') {
            name = 'id';
        } elif (name in ('css_class', 'css')) {
            name = 'class';
        } elif name.startswith('on') {
            name = name.lower();
        }
    }
    return (ns, name);
}

"""
    Calculates goodness of fit for the provided values, and scales based on the total number of individuals that exist.
    The calculation is 1 - (abs(x - y)/max(x, y)) * n/n_tot for x, y simulated and actual values, n, n_tot for metric
    and total
    number of individuals.

    :param simulated_value: the simulated value of the metric
    :param actual_value: the actual value of the metric
    :param number_individuals: the number of individuals this metric relates to
    :param total_individuals: the total number of individuals across all sites for this metric
    :return: the scaled fit value
    """
def scale_simulation_fit(
    simulated_value: float,
    actual_value: float,
    number_individuals: float,
    total_individuals: float
) -> float {
    return (
        (
            (
                1
                - (
                    abs((simulated_value - actual_value))
                    / max(simulated_value, actual_value)
                )
            )
            * number_individuals
        )
        / total_individuals
    );
}

"""t^1/2 fit w/ 2 params: slope a and horizontal shift t0."""
def square_root_2param_t0_fit(t: float, a: float, t0: float) -> float {
    return (a * ((t - t0) ** 0.5));
}

"""Gives the number of possibilities of n objects chosen r times, order matters"""
def combinations(n: int, r: int) -> object {
    product: float = 1.0;
    for i in range(((n - r) + 1), (n + 1)) {
        product *= i;
    }
    for x in range(2, (r + 1)) {
        product /= x;
    }
    return product;
}

"""take a string of the form "YYYY-MM-DD" (or "YYYY"), terurn a tuple (year, month, date) of three integers"""
def to_ymd(s: str) -> object {
    if not s {
        return;
    }
    s = s + '--';
    y: str | int | None = s.split('-')[0];
    m: str | int | None = s.split('-')[1];
    d: str | int | None = s.split('-')[2];
    if y {
        y = int(y as str);
    } else {
        y = None;
    }
    if m {
        m = int(m as str);
    } else {
        m = None;
    }
    if d {
        d = int(d as str);
    } else {
        d = None;
    }
    return (y, m, d);
}

