"""Specify an elasticsearch aggregation from schema facet configuration.
    """
def build_aggregation(
    facet_name: str,
    facet_options: dict[str, str],
    min_doc_count: int = 0
) -> tuple[str, dict[str, dict[str, str | int | list[str]]] | dict[str, dict[str, dict[str, dict[str, dict[str, str]]]]]] {
    exclude: list[str] = [];
    if facet_name == 'type' {
        field = 'embedded.@type.raw';
        exclude = ['Item'];
    } elif facet_name.startswith('audit') {
        field = facet_name;
    } else {
        field = 'embedded.' + facet_name + '.raw';
    }
    agg_name = facet_name.replace('.', '-');
    facet_type = facet_options.get('type', 'terms');
    agg: dict[str, dict[str, str | int | list[str]]] | dict[str, dict[str, dict[str, dict[str, dict[str, str]]]]];
    if facet_type == 'terms' {
        terms_agg: dict[str, dict[str, str | int | list[str]]] = {
            'terms': {'field': field, 'min_doc_count': min_doc_count, 'size': 100}
        };
        if exclude {
            terms_agg['terms']['exclude'] = exclude;
        }
        agg = terms_agg;
    } elif facet_type == 'exists' {
        agg = {
            'filters': {
                'filters': {
                    'yes': {'exists': {'field': field}},
                    'no': {'missing': {'field': field}}
                }
            }
        } as dict[str, dict[str, dict[str, dict[str, dict[str, str]]]]];
    } else {
        raise ValueError(
            'Unrecognized facet type {} for {} facet'.format(facet_type, field)
        );
    }
    return (agg_name, agg);
}

"""Function extracted from Keras - check keras.engine.training_utils
    for the original version.

    Returns a list of batch indices (tuples of indices).
    # Arguments
        size: Integer, total size of the data to slice into batches.
        batch_size: Integer, batch size.
    # Returns
        A list of tuples of array indices.
    """
def make_batches(size: int, batch_size: int) -> list {
    num_batches = ((size + batch_size) - 1) // batch_size;
    return [
        ((i * batch_size), min(size, ((i + 1) * batch_size)))
        for i in range(num_batches)
    ];
}

"""
    This will return the path to the calling function
    :param func:
    :return:
"""
obj _CodeObj {
    has co_filename: str;
}

obj _FuncPathSource {
    has func_code: _CodeObj;
    has __code__: _CodeObj;
}

def function_path(func: _FuncPathSource) -> str {
    if func?.func_code {
        return func.func_code.co_filename.replace('\\', '/');
    }
    return func.__code__.co_filename.replace('\\', '/');
}

