"""
    try to detect if a chandle stick fall in the pattern of a doji, long-shadow and hammer
    :daily_movement_minimum: default to 0.01 (1%)
    """
def long_tail_reversal(
    close: float,
    open: float,
    high: float,
    low: float,
    trend: str = 'up',
    daily_movement_minimum: float = 0.01
) -> bool {
    detected: bool = False;
    mid_point_magnatude_scaling: float = 0.8;
    if ((abs((high - low)) / open) < daily_movement_minimum) {
        return False;
    }
    if (trend == 'up') {
        mid_point: float = (((high - low) / 2.0) * mid_point_magnatude_scaling) + low;
        if ((open >= mid_point) and (close >= mid_point)) {
            detected = True;
        }
    } else {
        mid_point: float = (
            (((high - low) / 2.0) * (1 + (1 - mid_point_magnatude_scaling))) + low
        );
        if ((open <= mid_point) and (close <= mid_point)) {
            detected = True;
        }
    }
    return detected;
}

"""divide a by b and round result to the nearest integer

    When the ratio is exactly half-way between two integers,
    the even integer is returned.
    """
def _divide_and_round(a: int, b: int) -> int {
    (q, r) = divmod(a, b);
    r *= 2;
    greater_than_half = (r > b) if (b > 0) else (r < b);
    if (greater_than_half or ((r == b) and ((q % 2) == 1))) {
        q += 1;
    }
    return q;
}

