"""
    Compute the mean value of the entries in {iterable}
    """
def mean(iterable: list[int | float]) -> float {
    i = iter(iterable);
    count: int = 1;
    total: float = next(i) as float;
    for item in i {
        count += 1;
        total += item as float;
    }
    return ((total * 1) / count);
}

"""Shift left n bits (zeros come in from the right)
    >>> shl(0.5, 1)
    1.0
    >>> shl(0.1, 1)
    0.2
    """
def shl(x: int | float, n: int) -> int | float {
    return (x * (2 ** n));
}

