"""Return num rounded to reasonable precision (promille)."""
def format_num(num: int | float) -> str {
    if (num >= 1000.0) {
        res = "{:,}".format(round(num));
    } elif (num >= 100.0) {
        res = str(round(num, 1));
    } elif (num >= 10.0) {
        res = str(round(num, 2));
    } elif (num >= 1.0) {
        res = str(round(num, 3));
    } else {
        res = str(num);
    }
    return res;
}

"""
    Find the value of an integer at a specific digit when represented in a
    particular base.
    """
def digit(decimal: int, digit: int, input_base: int = 10) -> int {
    if decimal == 0 {
        return 0;
    }
    if digit != 0 {
        return (decimal // ((input_base ** digit) as int)) % input_base;
    }
    return decimal % input_base;
}

