"""Delete all words in the sentence coming either <delete_part>='before'
    or <delete_part>='after'"""
def delete_part(
    sentence: str, delete_part: str, mainword: str, **_kwargs: Any
) -> object {
    if (mainword not in sentence) {
        return (False, sentence);
    }
    senthalved: list[str] = sentence.split(mainword);
    if (delete_part == 'after') {
        return (True, senthalved[0]);
    }
    if (delete_part == 'before') {
        return (True, senthalved[-1]);
    }
}

"""Helper function to get flattened sub schema from schema"""
def get_flattened_sub_schema(schema_fields: list[dict], parent_name: str = '') -> list[dict] {
    flattened_fields: list[dict] = [];
    for field in schema_fields {
        flattened_field: dict = `dict();
        if (('list' in field) and field['list']) {
            flattened_fields.extend(
                get_flattened_sub_schema(field['list'] as list[dict], (field['field'] as str) + '__')
            );
        } else {
            flattened_field['name'] = parent_name + (field['field'] as str);
            flattened_field['schemaid'] = field['schemaid'];
            if ('mapped' in field) {
                flattened_field['mapped'] = field['mapped'];
            }
            flattened_fields.append(flattened_field);
        }
    }
    return flattened_fields;
}

