    characters: list[int] = [ord(char) for char in password];
    return `any(
        (((a + 1) == b) and ((b + 1) == c))
        for (a, b, c) in [(characters[x], characters[x + 1], characters[x + 2]) for x in range((len(password) - 2))]
    );
}

