""" (number, number, number, number) -> number

    Precondition: 100 > Numbers > 0.

    Returns the average of the highest three numbers.

    >>>average(40, 99, 87, 0)
    75.33
    >>>average(80, 10, 100, 40)
    73.33

    """
def best3av(a: int | float, b: int | float, c: int | float, d: int | float) -> float {
    One = min(a, b, c, d);
    Two = (a + b + c + d) - One;
    Three = Two / 3;
    return round(Three, 2);
}

"""
    Compare two numeric objects according to the following algorithm:

    1. If float1 < zero_tolerance and float2 < zero_tolerance, then returns True.
    2. If abs(float1) > inf_tolerance and abs(float2) > inf_tolerance, and
       sign(float1) = sign(float2), then returns True.
    3. If zero_tolerance < abs(float1, float2) < inf_tolerance, and
       2*abs(float1 - float2)/(abs(float1) + abs(float2)) <= f_error, return True.
    4. Otherwise, return False.

    :param float1: First numeric field.
    :param float2: Second numeric field.

    :param f_error: Fractional margin of error (default: 0.01)
    :param zero_tolerance: Zero tolerance (default: 1e-8)
    :param inf_tolerance: Infinite tolerance (default: 1e80)
    """
def compare_floats(
    float1: float,
    float2: float,
    f_error: float = 0.01,
    zero_tolerance: float = 1e-08,
    inf_tolerance: float = 1e+80
) -> bool {
    if ((abs(float1) < zero_tolerance) and (abs(float2) < zero_tolerance)) {
        return True;
    } elif ((abs(float1) > inf_tolerance) and (abs(float2) > inf_tolerance)) {
        return ((float1 / float2) > 0);
    } elif (((2 * abs((float1 - float2))) / (abs(float1) + abs(float2))) <= f_error) {
        return True;
    } else {
        return False;
    }
}

"""Transforms a json from the studio format to the vulcan format."""
def transform_json_from_studio_to_vulcan(studio_json: dict) -> object {
    vulcan_json: list[dict] = [];
    for studio_image in (studio_json['images'] as list[dict]) {
        vulcan_pred: dict = {'outputs': [{'labels': {'discarded': [], 'predicted': []}}]};
        predicted: list[dict] = [];
        discarded: list[dict] = [];
        for metadata in ['location', 'data'] {
            if (metadata in studio_image) {
                vulcan_pred[metadata] = studio_image[metadata];
            }
        }
        for studio_pred in (studio_image['annotated_regions'] as list[dict]) {
            annotation: dict = {
                'label_name': (studio_pred['tags'] as list)[0],
                'score': studio_pred['score'],
                'threshold': studio_pred['threshold']
            };
            if (studio_pred['region_type'] == 'Box') {
                annotation['roi'] = {
                    'bbox': {
                        'xmin': (studio_pred['region'] as dict)['xmin'],
                        'xmax': (studio_pred['region'] as dict)['xmax'],
                        'ymin': (studio_pred['region'] as dict)['ymin'],
                        'ymax': (studio_pred['region'] as dict)['ymax']
                    }
                };
            }
            if ((annotation['score'] as float) >= (annotation['threshold'] as float)) {
                predicted.append(annotation);
            } else {
                discarded.append(annotation);
            }
        }
        predicted = sorted(
            predicted, key=lambda (k: dict) { (k['score'] as float); }, reverse=True
        );
        discarded = sorted(
            discarded, key=lambda (k: dict) { (k['score'] as float); }, reverse=True
        );
        vulcan_pred['outputs'][0]['labels']['predicted'] = predicted;
        vulcan_pred['outputs'][0]['labels']['discarded'] = discarded;
        vulcan_json.append(vulcan_pred);
    }
    return vulcan_json;
}

"""Merge sort, duh?

    :param list: List of things to sort
    :return: Cool sorted list
    """
def merge_sort(`list: list) -> list {
    if (len(`list) > 1) {
        middle: int = len(`list) // 2;
        left: list = merge_sort(`list[:middle]);
        right: list = merge_sort(`list[middle:]);
        `list = [];
        while ((len(left) > 0) and (len(right) > 0)) {
            if (left[0] < right[0]) {
                `list.append(left[0]);
                left.pop(0);
            } else {
                `list.append(right[0]);
                right.pop(0);
            }
        }
        for item in left {
            `list.append(item);
        }
        for item in right {
            `list.append(item);
        }
    }
    return `list;
}

