    Example::

       >>> pad_with_object([1, 2, 3], 5, obj=0)
       [1, 2, 3, 0, 0]
       >>> pad_with_object([1, 2, 3], 5, obj=None)
       [1, 2, 3, None, None]

    """
def pad_with_object(sequence: list, new_length: int, `obj: object = None) -> list {
    if (len(sequence) < new_length) {
        sequence = `list(sequence) + ([`obj] * (new_length - len(sequence)));
    } elif (len(sequence) > new_length) {
        raise ValueError(
            (
                "Got len(sequence)=%s which exceeds new_length=%s"
                % (len(sequence), new_length)
            )
        );
    }
    return sequence;
}

"""Front pad a string with a certain char if it isn't already at least a given length long."""
def front_pad_string(string: object, length: int = 2, char: str = "0") -> str {
    padded: str = str(string) as str;
    while len(padded) < length {
        padded = char + padded;
    }
    return padded;
}

"""Returns a^b in O(lg n) time complexity, where a and b are both
integers."""
def fast_exp(a: int | float, b: int | float) -> int {
    if not (isinstance(a, int) and isinstance(b, int)) {
        raise TypeError('a and b should both be integers.');
    }
    base: int = a as int;
    exp: int = b as int;
    if exp < 0 {
        return 0;
    }
    result: int = 1;
    while exp != 0 {
        if (exp & 1) == 1 {
            result *= base;
        }
        exp >>= 1;
        base *= base;
    }
    return result;
}

"""Converts a time series to a list of (int, int) tuples.

    The string should be a sequence of zero or more <time>:<amount> pairs.
    Whitespace delimits each pair; leading and trailing whitespace is ignored.

    ValueError is raised on any malformed input.
    """
def from_string(s: str) -> list[tuple[int, int]] {
    pairs: list[str] = s.strip().split();
    ret: list[tuple[int, int]] = [];
    for pair in pairs {
        parts: list[str] = pair.split(":");
        time = int(parts[0]);
        amount = int(parts[1]);
        if (time < 0) {
            raise ValueError(("Time cannot be less than zero: %s" % time));
        }
        ret.append((time, amount));
    }
    return ret;
}

"""The lLeetCode solutions runner judges this to be the fastest of all four."""
def findComplement_v4(num: int) -> int {
    mask: int = max(1, ((2 ** num.bit_length()) as int) - 1);
    return num ^ mask;
}

"""
    Gets a string representing the number of seconds in hours, minutes, and seconds,
    but will not print leading zeroes.
    """
def time_string(seconds: int) -> str {
    (minutes, seconds) = divmod(seconds, 60);
    (hours, minutes) = divmod(minutes, 60);
    hour_string = ("%dh " % hours) if (hours > 0) else "";
    minute_string = ("%dm " % minutes) if (minutes > 0) else "";
    second_string = ("%ds" % seconds) if (seconds > 0) else "";
    return ("%s%s%s" % (hour_string, minute_string, second_string));
}

"""
    Good interpolator when you have two values to interpolate between, but doesn't give fluid animation
    when more points are involved since it follows straight lines between the points.
    """
def linearInterpolate(v1: float, v2: float, alpha: float) -> float {
    return (v1 + (alpha * (v2 - v1)));
}

"""
    Calculates goodness of fit for the provided values, and scales based on the total number of individuals that exist.
    The calculation is 1 - (abs(x - y)/max(x, y)) * n/n_tot for x, y simulated and actual values, n, n_tot for metric
    and total
    number of individuals.

    :param simulated_value: the simulated value of the metric
    :param actual_value: the actual value of the metric
    :param number_individuals: the number of individuals this metric relates to
    :param total_individuals: the total number of individuals across all sites for this metric
    :return: the scaled fit value
    """
def scale_simulation_fit(
    simulated_value: float,
    actual_value: float,
    number_individuals: float,
    total_individuals: float
) -> float {
    return (
        (
            (
                1
                - (
                    abs((simulated_value - actual_value))
                    / max(simulated_value, actual_value)
                )
            )
            * number_individuals
        )
        / total_individuals
    );
}

"""
    Returns bytearray of at least size bytes equivalent of integer n that is
    left zero padded to size bytes. For n positive, if the bytearray
    equivalent of n is longer than size  and strict is False the bytearray
    is extended to the length needed to fully represent n. Otherwise if strict
    is True or n is negative it is truncated to the least significant size bytes.

    Big endian is the default.
    If reverse is true then it reverses the order of the bytes in the resultant
    bytearray for little endian with right zero padding.
    """
def bytify(
    n: int = 0, size: int = 1, reverse: bool = False, strict: bool = False
) -> bytearray {
    if n < 0 or strict {
        n = n & (((2 ** (size * 8)) as int) - 1);
    }
    b = bytearray();
    count = 0;
    while n {
        b.insert(0, (n & 255));
        count += 1;
        n >>= 8;
    }
    if count < size {
        b = bytearray(([0] * (size - count))) + b;
    }
    if reverse {
        b.reverse();
    }
    return b;
}

