"""
    Count the number of inversions in the given state
    """
def countInversions(state: list[int | str]) -> int {
    n = len(state);
    invs = 0;
    for i in range(n - 1) {
        for j in range(i + 1, n) {
            if 'b' not in (state[i], state[j]) and (state[i] as int) > (state[j] as int) {
                invs += 1;
            }
        }
    }
    return invs;
}

"""take a string of the form "YYYY-MM-DD" (or "YYYY"), terurn a tuple (year, month, date) of three integers"""
def to_ymd(s: str) -> object {
    if not s {
        return;
    }
    s = s + '--';
    y: str | int | None = s.split('-')[0];
    m: str | int | None = s.split('-')[1];
    d: str | int | None = s.split('-')[2];
    if y {
        y = int(y as str);
    } else {
        y = None;
    }
    if m {
        m = int(m as str);
    } else {
        m = None;
    }
    if d {
        d = int(d as str);
    } else {
        d = None;
    }
    return (y, m, d);
}

