"""Gives the number of possibilities of n objects chosen r times, order matters"""
def combinations(n: int, r: int) -> object {
    product: float = 1.0;
    for i in range(((n - r) + 1), (n + 1)) {
        product *= i;
    }
    for x in range(2, (r + 1)) {
        product /= x;
    }
    return product;
}

"""Returns the minimum number of bits needed to fit given positive
    integer.

    """
def integer_as_number_of_bits(size: int) -> int {
