"""
    try to detect if a chandle stick fall in the pattern of a doji, long-shadow and hammer
    :daily_movement_minimum: default to 0.01 (1%)
    """
def long_tail_reversal(
    close: float,
    open: float,
    high: float,
    low: float,
    trend: str = 'up',
    daily_movement_minimum: float = 0.01
) -> bool {
    detected = False;
    mid_point_magnatude_scaling = 0.8;
    if ((abs((high - low)) / open) < daily_movement_minimum) {
        return False;
    }
    if (trend == 'up') {
        mid_point = (((high - low) / 2.0) * mid_point_magnatude_scaling) + low;
        if ((open >= mid_point) and (close >= mid_point)) {
            detected = True;
        }
    } else {
        mid_point = (
            (((high - low) / 2.0) * (1 + (1 - mid_point_magnatude_scaling))) + low
        );
        if ((open <= mid_point) and (close <= mid_point)) {
            detected = True;
        }
    }
    return detected;
}

"""Function extracted from Keras - check keras.engine.training_utils
    for the original version.

    Returns a list of batch indices (tuples of indices).
    # Arguments
        size: Integer, total size of the data to slice into batches.
        batch_size: Integer, batch size.
    # Returns
        A list of tuples of array indices.
    """
def make_batches(size: int, batch_size: int) -> list[tuple[int, int]] {
    num_batches = ((size + batch_size) - 1) // batch_size;
    return [
        ((i * batch_size), min(size, ((i + 1) * batch_size)))
        for i in range(num_batches)
    ];
}

