"""base=2: [False, False, False, False, False, False, False, True] -> 128"""
def val_to_dec(value: list[bool], base: int = 2) -> int {
    res = 0;
    for (idx, val) in enumerate(value) {
        res += int(val) * ((base ** idx) as int);
    }
    return res;
}

"""Try really hard to scale 'points' by 'scalar'.

    @type  points: mixed
    @param points: Points can either be:

        - a sequence of pairs, in which case the second item will be scaled,
        - a list, or
        - a number

    @type  scalar: number
    @param scalar: the amount to multiply points by
    """
def scale(points: list | int | float, scalar: int | float) -> list | int | float {
    if (`type(points) is `list) {
        try {
            return [(k, ((p as int | float) * scalar)) for (k, p) in (points as list)];
        } except TypeError {
            return [((p as int | float) * scalar) for p in (points as list)];
        }
    } else {
        return ((points as int | float) * scalar);
    }
}

