"""
    Takes two sorted lists of tuples and returns a
    combined list sorted by lowest first element
    Paramters:
      a, b - a sorted list of tuples
    """
def order_to_process(a: list, b: list) -> list {
    ret_l: list = [];
    while (a and b) {
        ret_l.append(a.pop(0) if (a <= b) else b.pop(0));
    }
    ret_l.extend(a);
    ret_l.extend(b);
    return ret_l;
}

"""
Calculate the max needed length for a output col by getting the headline, the content of the rows
(different data types) and in some cases a specific key
"""
def col_length(headline: str, content: list[str] | dict[str, dict[str, str | dict] | int | float] | int, dict_key: str | None = None) -> int {
    length = len(headline);
    if type(content) == list {
        for x in content {
            if type(x) == str {
                if len(x) > length {
                    length = len(x);
                }
            }
        }
    } elif type(content) == dict {
        for key in content {
            if type(content[key]) == dict {
                row = content[key] as dict;
                if dict_key in row {
                    val = row[dict_key as str];
                    if len(str(val)) > length {
                        length = len(str(val));
                    }
                } else {
                    x = key;
                    for key in content[x] {
                        if type(content[x][key]) == dict {
                            nested = content[x][key] as dict;
                            if dict_key in nested {
                                if type(content[x][key]) == dict {
                                    nested_val = nested[dict_key as str];
                                    if len(nested_val) > length {
                                        length = len(nested_val);
                                    }
                                }
                            }
                        }
                    }
                }
            } elif type(content[key]) == int or type(content[key]) == float {
                if len(str(content[key])) > length {
                    length = len(str(content[key]));
                }
            }
        }
    } elif type(content) == int {
        if len(str(content)) > length {
            length = len(str(content));
        }
    }
    return length;
}

