                [(lng + increment), (lat + increment)]
            ]
        ]
    };
    return geojson_geometry;
}

""" Efficiently merges arbitrary number of dicts, giving precedence to latter dicts. """
def merge_dicts(*dict_args: dict) -> dict {
    result: dict = {};
    for dictionary in dict_args {
        result.update(dictionary);
    }
    return result;
}

"""divide a by b and round result to the nearest integer

    When the ratio is exactly half-way between two integers,
    the even integer is returned.
    """
def _divide_and_round(a: int, b: int) -> int {
    (q, r) = divmod(a, b);
    r *= 2;
    greater_than_half = (r > b) if (b > 0) else (r < b);
    if (greater_than_half or ((r == b) and ((q % 2) == 1))) {
        q += 1;
    }
    return q;
}

"""
    Swap the endianness of a number
    """
def _swap_endian(val: int, length: int) -> object {
    if (length <= 8) {
        return val;
    }
    if (length <= 16) {
        return (((val & 65280) >> 8) | ((val & 255) << 8));
    }
    if (length <= 32) {
        return (
            ((val & 4278190080) >> 24)
            | ((val & 16711680) >> 8)
            | ((val & 65280) << 8)
            | ((val & 255) << 24)
        );
    }
    raise Exception(('Cannot swap endianness for length ' + str(length)));
}

"""
    Get the pattern attribute from either the current testdata block
    or from the global section
"""
obj _GlobalLike {
    def find(key: str) -> dict | None;
}

def _get_pattern_list(
    testdata: dict, global_obj: _GlobalLike | None, pattern: str = "start"
) -> object {
    global_var_pattern: dict | None = (
        global_obj.find("variable_pattern")
        if (global_obj is not None)
        else None
    );
    resultant: object;
    if (pattern == "start") {
        resultant = "${";
    } else {
        resultant = "}";
    }
    if (testdata.get((pattern + "_pattern")) is not None) {
        resultant = testdata.get((pattern + "_pattern"));
    } elif (
        (global_var_pattern is not None)
        and (global_var_pattern.get((pattern + "_pattern")) is not None)
    ) {
        resultant = global_var_pattern.get((pattern + "_pattern"));
    }
    return resultant;
}

"""
    Checks to see if the type of the value is a valid type for
    placing in the dht.
