        work: str = pair;
        if pair.endswith("=") {
            work = pair.rstrip("=");
            suffix = "=";
        }
        parts: list[str] = work.split("=");
        key: str = parts[0];
        value: str = parts[1];
        value += suffix;
        cn[key] = value;
    }
    return cn;
