"""Returns a^b in O(lg n) time complexity, where a and b are both
integers."""
def fast_exp(a: int | float, b: int | float) -> int {
    if isinstance(b, int) and not isinstance(a, int) {
        raise TypeError('a and b should both be integers.');
    }
    ai: int = a as int;
    bi: int = b as int;
    if bi < 0 {
        return 0;
    }
    result: int = 1;
    while bi != 0 {
        if (bi & 1) == 1 {
            result *= ai;
        }
        bi >>= 1;
        ai *= ai;
    }
    return result;
}

"""Converts a time series to a list of (int, int) tuples.

    The string should be a sequence of zero or more <time>:<amount> pairs.
    Whitespace delimits each pair; leading and trailing whitespace is ignored.

    ValueError is raised on any malformed input.
    """
def from_string(s: str) -> list[tuple[int, int]] {
    pairs: list[str] = s.strip().split();
    ret: list[tuple[int, int]] = [];
    for pair in pairs {
        parts: list[str] = pair.split(":");
        time: int = int(parts[0]);
        amount: int = int(parts[1]);
        if (time < 0) {
            raise ValueError(("Time cannot be less than zero: %s" % time));
        }
        ret.append((time, amount));
    }
    return ret;
}

""" interpret input distribution descriptions into usable entries """
def interpret_distribution(key: str, value: str) -> object {
    parts: list[str] = value.split('(');
    dist_name: str = parts[0].strip();
    args: list[str] = parts[1].strip(')').split(',');
    converted: dict = {};
    if (dist_name not in ['uniform', 'normal', 'constant']) {
        raise IOError(
            (
                'Variable distributions can only be "uniform", "normal", or "constant"; '
                + 'got "{}" for "{}"'.format(dist_name, key)
            )
        );
    }
    converted['dist'] = dist_name;
    if (dist_name == 'uniform') {
        converted['lowerBound'] = float(args[0]);
        converted['upperBound'] = float(args[1]);
    } elif (dist_name == 'normal') {
        converted['mean'] = float(args[0]);
        converted['std'] = float(args[1]);
        if (len(args) > 2) {
            converted['lowerBound'] = float(args[2]);
            converted['upperBound'] = float(args[3]);
        }
    } elif (dist_name == 'constant') {
        converted['value'] = float(args[0]);
    }
    return converted;
}

