      a, b - a sorted list of tuples
    """
def order_to_process(a: list[tuple], b: list[tuple]) -> list[tuple] {
    ret_l: list[tuple] = [];
    while (a and b) {
        ret_l.append(a.pop(0) if (a <= b) else b.pop(0));
