"""Transforms a json from the studio format to the vulcan format."""
def transform_json_from_studio_to_vulcan(studio_json: dict) -> object {
    vulcan_json: list = [];
    for studio_image in (studio_json['images'] as list) {
        vulcan_pred: dict = {'outputs': [{'labels': {'discarded': [], 'predicted': []}}]};
        predicted: list[dict] = [];
        discarded: list[dict] = [];
        for metadata in ['location', 'data'] {
            if (metadata in studio_image) {
                vulcan_pred[metadata] = studio_image[metadata];
            }
        }
        for studio_pred in (studio_image['annotated_regions'] as list) {
            annotation: dict = {
                'label_name': studio_pred['tags'][0],
                'score': studio_pred['score'],
                'threshold': studio_pred['threshold']
            };
            if (studio_pred['region_type'] == 'Box') {
                annotation['roi'] = {
                    'bbox': {
                        'xmin': studio_pred['region']['xmin'],
                        'xmax': studio_pred['region']['xmax'],
                        'ymin': studio_pred['region']['ymin'],
                        'ymax': studio_pred['region']['ymax']
                    }
                };
            }
            if ((annotation['score'] as float) >= (annotation['threshold'] as float)) {
                predicted.append(annotation);
            } else {
                discarded.append(annotation);
            }
        }
        predicted = sorted(
            predicted, key=lambda (k: dict) { (k['score'] as float); }, reverse=True
        );
        discarded = sorted(
            discarded, key=lambda (k: dict) { (k['score'] as float); }, reverse=True
        );
        vulcan_pred['outputs'][0]['labels']['predicted'] = predicted;
        vulcan_pred['outputs'][0]['labels']['discarded'] = discarded;
        vulcan_json.append(vulcan_pred);
    }
    return vulcan_json;
}

"""! @brief Return the bitwise inverted value of the argument given a specified width.

    @param value Integer value to be inverted.
    @param width Bit width of both the input and output. If not supplied, this defaults to 32.
    @return Integer of the bitwise inversion of @a value.
    """
def bit_invert(value: int, width: int = 32) -> int {
    return (((1 << width) - 1) & ~value);
}

