""" (number, number, number, number) -> number

    Precondition: 100 > Numbers > 0.

    Returns the average of the highest three numbers.

    >>>average(40, 99, 87, 0)
    75.33
    >>>average(80, 10, 100, 40)
    73.33

    """
def best3av(a: int | float, b: int | float, c: int | float, d: int | float) -> float {
    One: int | float = min(a, b, c, d);
    Two: int | float = (a + b + c + d) - One;
    Three: float = Two / 3;
    return round(Three, 2);
}

"""
    Returns :samp:`sequence` :obj:`list` end-padded with :samp:`{obj}`
    elements so that the length of the returned list equals :samp:`{new_length}`.

    :type sequence: iterable
    :param sequence: Return *listified* sequence which has been end-padded.
    :type new_length: :obj:`int`
    :param new_length: The length of the returned list.
    :type obj: :obj:`object`
    :param obj: Object used as padding elements.
    :rtype: :obj:`list`
    :return: A :obj:`list` of length :samp:`{new_length}`.
    :raises ValueError: if :samp:`len({sequence}) > {new_length})`.

    Example::

       >>> pad_with_object([1, 2, 3], 5, obj=0)
       [1, 2, 3, 0, 0]
       >>> pad_with_object([1, 2, 3], 5, obj=None)
       [1, 2, 3, None, None]

    """
def pad_with_object(sequence: list, new_length: int, `obj: object = None) -> list {
    if (len(sequence) < new_length) {
        sequence = `list(sequence) + ([`obj] * (new_length - len(sequence)));
    } elif (len(sequence) > new_length) {
        raise ValueError(
            (
                "Got len(sequence)=%s which exceeds new_length=%s"
                % (len(sequence), new_length)
            )
        );
    }
    return sequence;
}

"""
    This function converts time in a form of integers to a hh:mm:ss format
    Returns an array | Ex: 01:32:34
    """
def convert_time(time: int) -> str {
    time_list: list[int] = [(60 * 60), 60, 1];
    output_list: list[str] = [];
    for i in time_list {
        (amount, remainder) = divmod(time, i);
        if (len(str(amount)) < 2) {
            output_list.append(f'0{str(amount)}');
        } else {
            output_list.append(str(amount));
        }
        time = remainder;
    }
    return ':'.join(output_list);
}

