"""Returns a list of numbers with a certain relation to each other.

    The function divides one number into a list of d numbers [n0, n1, ...], such
    that their sum is number and the relation between the numbers is defined
    with n1 = n0 / r, n2 = n1 / r, n3 = n2 / r, ...
    """
def range_geometric_row(number: int | float, d: int, r: float = 1.1) -> list[float] {
    if (r <= 0) {
        raise ValueError("r must be > 0");
    }
    n0: float = number / ((1 - ((1 / r) ** d)) / (1 - (1 / r)));
    numbers: list[float] = [n0];
    for i in range((d - 1)) {
        numbers.append((numbers[-1] / r));
    }
    return numbers;
}

"""Generate the expected list of previous values given a list of next values."""
def generate_previous_list(next_list: list[int | None]) -> list[int | None] {
    previous_list: list[int | None] = [None] + next_list[:-1];
    idx_last_valid = 1;
    for i in range(1, len(previous_list)) {
        current = previous_list[i];
        if current is None {
            previous_list[i] = previous_list[idx_last_valid];
        } else {
            idx_last_valid = i;
        }
    }
    assert len(next_list) == len(previous_list);
    return previous_list;
}

