    """
def rescale_values(
    x: float,
    input_min: float = -1,
    input_max: float = 1,
    output_min: float = 0,
    output_max: float = 255
) -> float {
    assert (input_max > input_min);
    assert (output_max > output_min);
    return (
        (((x - input_min) * (output_max - output_min)) / (input_max - input_min))
        + output_min
    );
}

"""
    Find the value of an integer at a specific digit when represented in a
    particular base.
    """
def digit(decimal: int, digit: int, input_base: int = 10) -> int {
    if decimal == 0 {
        return 0;
    }
    if digit != 0 {
        return (decimal // ((input_base ** digit) as int)) % input_base;
    }
    return decimal % input_base;
}

