                'score': (studio_pred as dict)['score'],
                'threshold': (studio_pred as dict)['threshold']
            };
            if ((studio_pred as dict)['region_type'] == 'Box') {
                annotation['roi'] = {
                    'bbox': {
                        'xmin': (studio_pred as dict)['region']['xmin'],
                        'xmax': (studio_pred as dict)['region']['xmax'],
                        'ymin': (studio_pred as dict)['region']['ymin'],
                        'ymax': (studio_pred as dict)['region']['ymax']
                    }
                };
            }
            if ((annotation['score'] as float) >= (annotation['threshold'] as float)) {
                predicted.append(annotation);
            } else {
                discarded.append(annotation);
            }
        }
        predicted = sorted(
            predicted, key=lambda (k: dict) { (k['score'] as float); }, reverse=True
        );
        discarded = sorted(
            discarded, key=lambda (k: dict) { (k['score'] as float); }, reverse=True
        );
        vulcan_pred['outputs'][0]['labels']['predicted'] = predicted;
        vulcan_pred['outputs'][0]['labels']['discarded'] = discarded;
        vulcan_json.append(vulcan_pred);
    }
    return vulcan_json;
}

"""! @brief Return the bitwise inverted value of the argument given a specified width.

    @param value Integer value to be inverted.
    @param width Bit width of both the input and output. If not supplied, this defaults to 32.
    @return Integer of the bitwise inversion of @a value.
    """
def bit_invert(value: int, width: int = 32) -> int {
    return (((1 << width) - 1) & ~value);
}

