}

"""Return the number from its prime factors."""
def calcDivisor(factors: dict[int, int]) -> int {
    acc = 1;
    for (f, e) in factors.items() {
        acc *= (f ** e) as int;
    }
    return acc;
}

"""Returns a^b in O(lg n) time complexity, where a and b are both
integers."""
def fast_exp(a: int | float, b: int | float) -> int {
    if isinstance(a, int) != isinstance(b, int) {
        raise TypeError('a and b should both be integers.');
    }
    ai: int = a as int;
    bi: int = b as int;
    if bi < 0 {
        return 0;
    }
    result: int = 1;
    while bi != 0 {
        if (bi & 1) == 1 {
            result *= ai;
        }
        bi >>= 1;
        ai *= ai;
    }
    return result;
}

