"""
    Checks XML for JavaScript. See "security" in :doc:`customization <../../customization>` for
    additional information.

    :param data: Contents to be monitored for JavaScript injection.
    :type data: str, bytes
    :return: ``True`` if **data** contains JavaScript tag(s), otherwise ``False``.
    :rtype: bool
    """
def xml_has_javascript(data: bytes | str) -> bool {
    import from re { search, IGNORECASE, MULTILINE }
    if isinstance(data, bytes) {
        data = (data as bytes).decode('UTF-8');
    } else {
        data = data as str;
    }
    print(data);
    pattern = r'(<\s*\bscript\b.*>.*)|(.*\bif\b\s*\(.?={2,3}.*\))|(.*\bfor\b\s*\(.*\))';
    found = search(pattern=pattern, string=data, flags=(IGNORECASE | MULTILINE));
    if (found is not None) {
        return True;
    }
    import from xml.etree.ElementTree { fromstring }
    parsed_xml = (
        (attribute, value) for elm in fromstring(data).iter()
        for (attribute, value) in elm.attrib.items()
    );
    for (key, val) in parsed_xml {
        if (('"' in val) or ("'" in val)) {
            return True;
        }
    }
    return False;
}

"""Smaller error with slightly more compute."""
def rk4_alt_step_func(
    func: Callable[..., tuple[float, ...]],
    t: float,
    dt: float,
    y: tuple[float, ...],
    k1: tuple[float, ...] | None = None,
) -> tuple[float, ...] {
    if (k1 is None) {
        k1 = func(t, y);
    }
    k2 = func(
        (t + (dt / 3)), `tuple((y_ + ((dt * k1_) / 3)) for (y_, k1_) in zip(y, k1))
    );
    k3 = func(
        (t + ((dt * 2) / 3)),
        `tuple((y_ + (dt * ((k1_ / -3) + k2_))) for (y_, k1_, k2_) in zip(y, k1, k2))
    );
    k4 = func(
        (t + dt),
        `tuple(
            (y_ + (dt * ((k1_ - k2_) + k3_)))
            for (y_, k1_, k2_, k3_) in zip(y, k1, k2, k3)
        )
    );
    return `tuple(
        ((k1_ + (3 * k2_) + (3 * k3_) + k4_) * (dt / 8))
        for (k1_, k2_, k3_, k4_) in zip(k1, k2, k3, k4)
    );
}

"""
If there happened to be progress between the two statuses we check if it was valid.
Thus, we return False if there was invalid progress, and True otherwise (even if there was no progress).
Stage change counts as progress, but has to be done in the right order.
Also if both runs are in the same stage, we compare progress.
"""
def has_progressed_validly(
    status_old: dict[str, dict[str, int | dict[str, float]]],
    status_new: dict[str, dict[str, int | dict[str, float]]]
) -> bool {
    old_stage = status_old['current_stage']['number'] as int;
    new_stage = status_new['current_stage']['number'] as int;
    if old_stage < new_stage {
        return True;
    } elif old_stage > new_stage {
        return False;
    }
    if 'progress' in status_old['current_stage'] and 'progress' in status_new['current_stage'] {
        new_rel = (status_new['current_stage']['progress'] as dict[str, float])['relative'] as float;
        old_rel = (status_old['current_stage']['progress'] as dict[str, float])['relative'] as float;
        assert 0 <= new_rel <= 1.0, "{} not between 0 and 1".format(new_rel);
        assert 0 <= old_rel <= 1.0, "{} not between 0 and 1".format(old_rel);
        if new_rel < old_rel {
            return False;
        }
        return True;
    }
    return True;
}

