    """
def find_element_by_key(`obj: dict | list | object, key: str) -> object {
    path: list[str] = key.split(".", 1);
    if (len(path) == 1) {
        if isinstance(`obj, `list) {
            return [(i as dict).get(path[0]) for i in (`obj as list)];
        } elif isinstance(`obj, `dict) {
            return (`obj as dict).get(path[0]);
        } else {
            return `obj;
        }
    } elif isinstance(`obj, `list) {
        return [find_element_by_key((i as dict).get(path[0]), path[1]) for i in (`obj as list)];
    } elif isinstance(`obj, `dict) {
        return find_element_by_key((`obj as dict).get(path[0]), path[1]);
    } else {
        return `obj;
    }
}

