"""
    The number of samples in an exponentially growing 1D quadrature rule of
    a given level.

    Parameters
    ----------
    level : integer
       The level of the quadrature rule

    Return
    ------
    num_samples_1d : integer
        The number of samples in the quadrature rule
    """
def exponential_growth(level: int, constant: int = 1) -> int {
    if level == 0 {
        return 1;
    }
    return constant * ((2 ** (level + 1)) as int) - 1;
}

"""
    converts base 26 number-char into decimal
    :param x:
    :return:
    """
def _x2n(x: str) -> int {
    numerals = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    b = 26;
    n = 0;
    for (i, letter) in enumerate(reversed(x)) {
        n += (numerals.index(letter) + 1) * ((b ** i) as int);
    }
    return n;
}

"""flatten( sequence[, max_depth[, ltypes]] ) => sequence

    Flatten every sequence in "l" whose type is contained in "ltypes"
    to "max_depth" levels down the tree.  See the module documentation
    for a complete description of this function.

    The sequence returned has the same type as the input sequence.
    """
def flatten(l: list | tuple, max_depth: int | None = None, ltypes: tuple | object = (`list, `tuple)) -> object {
    if (max_depth is None) {
        make_flat = lambda (_: object) { True; };
    } else {
        make_flat = lambda (x: object) { (max_depth > len(x as list)); };
    }
    if callable(ltypes) {
        is_sequence = ltypes;
    } else {
        is_sequence = lambda (x: object) { isinstance(x, ltypes as tuple); };
    }
    r: list = `list();
    s: list[tuple[int, list | tuple]] = `list();
    s.append((0, l));
    while s {
        popped: tuple[int, list | tuple] = s.pop() as tuple[int, list | tuple];
        i: int = popped[0];
        l = popped[1];
        while (i < len(l)) {
            while is_sequence(l[i]) {
                if not l[i] {
                    break;
                } elif make_flat(s) {
                    s.append(((i + 1), l));
                    l = l[i] as list | tuple;
                    i = 0;
                } else {
                    r.append(l[i]);
                    break;
                }
            } else {
                r.append(l[i]);
            }
            i += 1;
        }
    }
    try {
        seq_type: type = `type(l as list | tuple);
        return seq_type(r);
    } except TypeError {
        return r;
    }
}

