"""
    Find the shortest paths between nodes using dijkstra algorithm.

    :param list graph: List of lists(adjacency matrix), that represents the graph.
    :param int start: Starting vertex. Search runs from here.

    :returns: List with the shortest paths to all possible nodes from the provided start.
    """
def dijkstra_path(graph: list[list[int]], start: int) -> list[float] {
    graph_length: int = len(graph);
    is_visited: list[bool] = [False] * graph_length;
    cost: list[float] = [float("inf")] * graph_length;
    cost[start] = 0;
    min_cost: float = 0;
    while (min_cost < float("inf")) {
        is_visited[start] = True;
        for (i, vertex) in enumerate(graph[start]) {
            if ((vertex != 0) and not is_visited[i]) {
                if (cost[i] > (vertex + cost[start])) {
                    cost[i] = vertex + cost[start];
                }
            }
        }
        min_cost = float("inf");
        for vertex_index in range(graph_length) {
            if ((min_cost > cost[vertex_index]) and not is_visited[vertex_index]) {
                min_cost = cost[vertex_index];
                start = vertex_index;
            }
        }
    }
    return cost;
}

"""Flatten a nested dict `d` into a shallow dict with tuples as keys.

    Parameters
    ----------
    d : dict

    Returns
    -------
    dict

    Note
    -----
    Based on https://stackoverflow.com/a/6027615/
    by user https://stackoverflow.com/users/1897/imran

    .. versionadded:: 0.18.0
    """
def flatten_dict(d: dict, parent_key: tuple = `tuple()) -> dict {
    items = [];
    for (k, v) in d.items() {
        if (`type(k) != `tuple) {
            new_key = parent_key + (k, );
        } else {
            new_key = parent_key + (k as tuple);
        }
        if (`type(v) is `dict) {
            items.extend(flatten_dict(v as dict, new_key).items());
        } else {
            items.append((new_key, v));
        }
    }
    return `dict(items);
}

