"""Return merged, sorted array and number of split inversions."""
def _merge_and_count_split_inv(left: list, right: list) -> object {
    (max_left, max_right) = (len(left), len(right));
    if ((max_left == 0) or (max_right == 0)) {
        return ((left + right), 0);
    }
    merged: list = [];
    inv_count: int = 0;
    i = j = 0;
    while ((i < max_left) and (j < max_right)) {
        if (left[i] <= right[j]) {
            merged.append(left[i]);
            i += 1;
        } else {
            merged.append(right[j]);
            j += 1;
            inv_count += max_left - i;
        }
    }
    while (i < max_left) {
        merged.append(left[i]);
        i += 1;
    }
    while (j < max_right) {
        merged.append(right[j]);
        j += 1;
    }
    return (merged, inv_count);
}

""" expand the segment"""
def expand_segment(
    num_frames: int, num_target_frames: int, start_frame: int, stop_frame: int
) -> tuple[int, int, bool] {
    num_frames_seg = (stop_frame - start_frame) + 1;
    changes = False;
    num_target_frames = min(num_target_frames, num_frames);
    if (num_frames_seg < num_target_frames) {
        while True {
            if (start_frame > 0) {
                start_frame -= 1;
                num_frames_seg += 1;
                changes = True;
            }
            if (num_frames_seg == num_target_frames) {
                break;
            }
            if (stop_frame < (num_frames - 1)) {
                stop_frame += 1;
                num_frames_seg += 1;
                changes = True;
            }
            if (num_frames_seg == num_target_frames) {
                break;
            }
        }
    }
    return (start_frame, stop_frame, changes);
}

"""Updates the signature dictionary.

    Args:
        signatures (dict): Signature dictionary, which can be empty.
        v (dict): A dictionary, where the keys are:
            mime: the file mime type
            signs: a list of comma separated strings containing the offsets and the hex signatures.

    Returns:
        dict: The signature dictionary with signatures from v
    """
def update_signatures(signatures: dict[str, dict[str, str]], v: dict) -> dict[str, dict[str, str]] {
    mime = v.get("mime") as str;
    signs = v.get("signs") as list[str];
    for sign in signs {
        arr = sign.split(",");
        offset = arr[0];
        hex = arr[1];
        if (hex == "00") {
            continue;
        }
        offset_signatures = signatures.get(offset, {} as dict[str, str]);
        offset_signatures[hex] = mime;
        signatures[offset] = offset_signatures;
    }
    return signatures;
}

