"""
    :param min_size lower bound of the interval to divide into bins
    :param max_size upper bound of the interval to divide into bins
    :param bin_no the interval will be divided into that many bins
    :returns list of tuples, representing the lower and upper limits of each subinterval after dividing into bins

    This function separates the input interval into bins
    """
def binner(min_size: float, max_size: float, bin_no: int) -> list[tuple[float, float]] {
    bin_size: float = float((max_size - min_size)) / float(bin_no);
    Bins: list[tuple[float, float]] = [
        ((min_size + (bin_size * k)), (min_size + (bin_size * (k + 1))))
        for k in range(0, bin_no)
    ];
    return Bins;
}

"""Sort three elements in place in ascending order and return the middle index."""
def _median3(comparables: list[int | float | str], lo: int, mid: int, hi: int) -> int {
    if (comparables[lo] as any) > (comparables[mid] as any) {
        (comparables[lo], comparables[mid]) = (comparables[mid], comparables[lo]);
    }
    if (comparables[mid] as any) > (comparables[hi] as any) {
        (comparables[mid], comparables[hi]) = (comparables[hi], comparables[mid]);
    }
    if (comparables[lo] as any) > (comparables[mid] as any) {
        (comparables[lo], comparables[mid]) = (comparables[mid], comparables[lo]);
    }
    return mid;
}

"""Returns the biggest element from the list that is less or equal to the value. Return None if not found
    """
def get_biggest_value_less_or_equal_to(iter: list[int] | range, value: int) -> object {
    if (`type(iter) == `list) {
        i = [
            x
            for x in (iter as list[int])
            if (x <= value)
        ];
        return max(i) if i else None;
    } elif (`type(iter) == range) {
        r = iter as range;
        if (value in range(r.start, r.stop)) {
            return (value - ((value - r.start) % r.step));
        } elif (value > (r.stop - 1)) {
            return (r.stop - 1);
        } else {
            return None;
        }
    } else {
        raise ValueError("iter must be of type list or range");
    }
}

