"""
        Converts floating point to HH:MM:[SS.S]

        Inputs
           value       : floating point number
           ndec        : number of decimal points to print seconds
           showSeconds : If True, show seconds, otherwise just
                         use HH:MM. Default:True
           delimiter   : the characters to be used between the numbers.

        Output
           a string of format hh:mm:[ss.s]

        Examples:
           convertHmsString(15.0)
           convertHmsString(15.0, ndec=2)
           convertHmsString(15.0, ndec=2, delimiter='hms')
           convertHmsString(15.0, ndec=2, delimiter='dms')
    """
def convertHmsString(
    value: int | float | object, ndec: int = 0, showSeconds: bool = True, delimiter: str = ':'
) -> object {
    spacing: str | list[str] = delimiter;
    if (len(spacing) == 1) {
        spacing = [spacing] * 3;
    }
    t: object = value;
    st: str = str(`type(value));
    if ((st.find('int') >= 0) or (st.find('float') >= 0)) {
        x: float = abs(value as float);
        h: int = int(x);
        m: int = int((60 * (x - h)));
        sec: float = 3600.0 * (x - h - (m / 60.0));
        t = str(("%.2d" % h)) + spacing[0] + str(('%.2d' % m));
        if showSeconds {
            t = (t as str) + spacing[1];
            format: str = '%0' + str((ndec + 3)) + '.' + str(ndec) + 'f';
            if (ndec <= 0) {
                format = '%.2d';
            }
            t = (t as str) + str((format % sec));
            if (spacing[2] not in [' ', ':']) {
                t = (t as str) + spacing[2];
            }
        }
        if ((value as float) < 0.0) {
            t = '-' + (t as str);
        }
    }
    return t;
}

