"""
    Since there are a lot of unnecessary repeation, we can bypass them with a memo
    The memo's index represent the length of the current substring and the value is the number of ways to decode it
    """
def decodeMemo(num: str) -> int {
    memo: list[int | None] = [None for _ in range((len(num) + 1))];
    def helper(num: str, l: int, mem: list[int | None]) -> int {
        if (l == 0) {
            return 1;
        }
        s = len(num) - l;
        if (num[s] == "0") {
            return 0;
        }
        if mem[l] {
            return mem[l] as int;
        }
        result = helper(num, (l - 1), mem);
        if ((l >= 2) and (int(num[s:(s + 2)]) <= 26)) {
            result += helper(num, (l - 2), mem);
        }
        mem[l] = result;
        return result;
    }
    return helper(num, len(num), memo);
}

"""
    This function is taken from the original tf repo.
    It ensures that all layers have a channel number that is divisible by 8
    It can be seen here:
    https://github.com/tensorflow/models/blob/master/research/slim/nets/mobilenet/mobilenet.py
    :param v:
    :param divisor:
    :param min_value:
    :return:
    """
def make_divisible(v: int | float, divisor: int | float, min_value: int | float | None = None) -> int | float {
    if (min_value is None) {
        min_value = divisor;
    }
    new_v: int | float = max(min_value as int | float, ((int((v + (divisor / 2))) // divisor) * divisor));
    if (new_v < (0.9 * v)) {
        new_v += divisor;
    }
    return new_v;
}

