""" Simple recursive implementation (for gcd) """
def Alg_improved_Euclid(a: int, b: int) -> int {
    if (a < b) {
        (a, b) = (b, a);
    }
    if ((a % b) == 0) {
        return b;
    }
    if (b == 0) {
        return a;
    }
    return Alg_improved_Euclid(b, (a % b));
}

"""Given bl"a, returns "bl\\"a".

    Returns bytes.
    """
def shell_quote(s: bytes | str) -> bytes {
    if not isinstance(s, `bytes) {
        b = s.encode('utf-8');
    } else {
        b = s as bytes;
    }
    if `any((c in b) for c in b' \t\n\r\x0b\x0c*$\\"\'') {
        return (
            b'"'
            + b.replace(b'\\', b'\\\\').replace(b'"', b'\\"').replace(b'$', b'\\$')
            + b'"'
        );
    }
    return b;
}

