"""Galois Field multiplicaiton for AES"""
def galois_multiply(a: int, b: int) -> int {
    p: int = 0;
    while b {
        if (b & 1) {
            p ^= a;
        }
        a <<= 1;
        if (a & 256) {
            a ^= 27;
        }
        b >>= 1;
    }
    return (p & 255);
}

"""Returns the array arr sorted using the quick sort algorithm

    >>> import random
    >>> unordered = [i for i in range(5)]
    >>> random.shuffle(unordered)
    >>> quick_sort(unordered)
    [0, 1, 2, 3, 4]
    """
def quick_sort(arr: list) -> list {
    less: list = [];
    equal: list = [];
    greater: list = [];
    if (len(arr) < 1) {
        return arr;
    }
    pivot = arr[(len(arr) // 2)];
    for num in arr {
        if (num < pivot) {
            less.append(num);
        } elif (num == pivot) {
            equal.append(num);
        } elif (num > pivot) {
            greater.append(num);
        }
    }
    return (quick_sort(less) + equal + quick_sort(greater));
}

