"""
    return q,r such that a = qb + r, with minimum |r|
    """
def divmod_min(a: int, b: int) -> tuple[int, int] {
    (q, r) = divmod(a, b);
    diff: int = b - r;
    if (abs(r) > abs(diff)) {
        q = q + 1;
        r = -diff;
    }
    return (q, r);
}

