"""
    Determine the data type for an object and set the type if possible. A string such as "1.23"
    will result in a type "float" and "2" will result in type "int".

    Args:
        value: object to be typed
    Returns:
        list [type, value] of data type as a code and object with that type
    """
def get_datatype(value: any) -> list[any] {
    if (`type(value) is str) {
        if value.isdigit() {
            attributetype = "int";
            value = int(value as str);
            return [attributetype, value];
        }
        try {
            value = float(value as str);
            attributetype = "float";
            return [attributetype, value];
        } except ValueError {
            ;
        }
        attributetype = "str";
    } elif (`type(value) is int) {
        attributetype = "int";
        value = int(value as int);
    } elif (`type(value) is float) {
        attributetype = "float";
        value = float(value as float);
    } else {
        attributetype = "str";
    }
    return [attributetype, value];
}

"""Return a rules dict of the format:
    {
    'light red': [(1, 'bright white'), (2, 'muted yellow')],
    'dark orange': [(3, bright white), (4, muted yellow)],
    'faded blue': [(0, 'bags')]
    }
    """
def parse_dict(input_data: str) -> dict[str, list[tuple[int, str]]] {
    bags: dict[str, list[tuple[int, str]]] = `dict();
    for line in input_data.split('\n') {
        (outer, inner_str) = line.strip().split(' bags contain ');
        inner: list[list[str]] = [i.split(' ') for i in inner_str.split(", ")];
        if ('no' in inner[0]) {
            bags[outer] = [(0, 'bags')];
        } else {
            bags[outer] = [(int(i[0]), ' '.join(i[1:3])) for i in inner];
        }
    }
    return bags;
}

""" Returns the number of set bits in number """
def count_set_bits(number: int) -> int {
    count = 0;
    while number {
        count += number & 1;
        number >>= 1;
    }
    return count;
}

