"""Implement a sorted in order by value list."""
def quick_sort(alist: list) -> list {
    if (len(alist) < 2) {
        return alist;
    }
    if (len(alist) == 2) {
        if (alist[0] > alist[1]) {
            (alist[0], alist[1]) = (alist[1], alist[0]);
        }
        return alist;
    }
    pivot = alist[0];
    less: list = [];
    greater: list = [];
    for num in alist {
        if (num < pivot) {
            less.append(num);
        }
        if (num > pivot) {
            greater.append(num);
        }
    }
    return (quick_sort(less) + [pivot] + quick_sort(greater));
}

"""Computes a^b mod n. Complexity O(log(b))"""
def modular_exp(a: int, b: int, n: int) -> int {
    res: int = 1;
    q: int = a;
    while (b > 0) {
        if ((b % 2) == 1) {
            res = (q * res) % n;
        }
        q = (q * q) % n;
        b //= 2;
    }
    return res;
}

"""Linear rampup"""
def linear_rampup(current: float, rampup_length: float) -> float {
    assert ((current >= 0) and (rampup_length >= 0));
    if (current >= rampup_length) {
        return 1.0;
    }
    return (current / rampup_length);
}

