def arrayMultiplyByScalar(inputArray: list[list | int | float] | int | float, scalar: int | float) -> list[list | int | float] | int | float {
    if isinstance(inputArray, `list) {
        return [arrayMultiplyByScalar(arrayItem, scalar) for arrayItem in inputArray];
    }
    return (inputArray * scalar);
}

"""Return the index where to insert item x in list a, assuming a is sorted.

    The return value i is such that all e in a[:i] have e <= x, and all e in
    a[i:] have e > x.  So if x already appears in the list, a.insert(x) will
    insert just after the rightmost x already there.

    Optional args lo (default 0) and hi (default len(a)) bound the
    slice of a to be searched.
    """
def bisect_right(
    a: list, x: Any, lo: int = 0, hi: int | None = None, key: Any = None
) -> int {
    if (key is None) {
        key = lambda (x: Any) { x; };
    }
    if (lo < 0) {
        raise ValueError('lo must be non-negative');
    }
    if (hi is None) {
        hi = len(a);
    }
    while (lo < hi) {
        mid: int = (lo + hi) // 2;
        if (key(x) < key(a[mid])) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

