""" Merge sort helper
    @type l: list
    @type r: list
    """
def merge(l: list, r: list) -> list {
    merged: list = [];
    while (len(l) and len(r)) {
        if (l[0] <= r[0]) {
            merged.append(l[0]);
            l.pop(0);
        } else {
            merged.append(r[0]);
            r.pop(0);
        }
    }
    return (merged + l + r);
}

