    decode it as a two's compliment signed integer

    :param uint:
    :param bits:
    :return:
    """
def uint_to_int(uint: int, bits: int) -> int {
    if ((uint & (1 << (bits - 1))) != 0) {
        uint = uint - (1 << bits);
    }
    return uint;
}

