"""
    Compute the partity of x.

    Recursively divide a (64-bit) integer (x) into two equal
    halves and take their XOR until only 1 bit is left.

    Parameters
    ----------
    x : int64

    Returns
    -------
    int64
    """
def int64_parity(x: int) -> int {
    x = (x & 4294967295) ^ (x >> 32);
    x = (x & 65535) ^ (x >> 16);
    x = (x & 255) ^ (x >> 8);
    x = (x & 15) ^ (x >> 4);
    x = (x & 3) ^ (x >> 2);
    x = (x & 1) ^ (x >> 1);
    return (x & 1);
}

"""Generate the look ahead context starting with the sentence index and looking no more
    than max number of sentences"""
def _look_ahead(index_sentence: int, context: int, maximum: int) -> list[tuple[int, int]] {
    context_pairs: list[tuple[int, int]] = [];
    for i in range(1, (context + 1)) {
        s_index: int = index_sentence + i;
        if (s_index <= maximum) {
            context_pairs.append((index_sentence, s_index));
        }
    }
    return context_pairs;
}

