"""make the replacement based on type

    :param obj: an obj in which replacements will be made
    :type obj: any
    :param replacements: the things to replace
    :type replacements: tuple of tuples
    """
def dispatch(`obj: Any, replacements: tuple[tuple[str, str], ...]) -> object {
    if isinstance(`obj, `dict) {
        `obj = {k: dispatch(v, replacements) for (k, v) in `obj.items()};
    } elif isinstance(`obj, `list) {
        `obj = [dispatch(l, replacements) for l in `obj];
    } elif isinstance(`obj, str) {
        for replacement in replacements {
            `obj = (`obj as str).replace(replacement[0], replacement[1]);
        }
    }
    return `obj;
}

"""
    >>> calculate_over_under([{'name': 'Ximena', 'paid': 165}, {'name': 'Clara', 'paid': 159}, {'name': 'Cassidy', 'paid': 216}])
    [{'name': 'Ximena', 'paid': 165, 'over_under': 15.0, 'owed': 180.0, 'percent_paid': 0.9166666666666666}, {'name': 'Clara', 'paid': 159, 'over_under': 21.0, 'owed': 180.0, 'percent_paid': 0.8833333333333333}, {'name': 'Cassidy', 'paid': 216, 'over_under': -36.0, 'owed': 180.0, 'percent_paid': 1.2}]
    """
def calculate_over_under(rolled_up: list[dict]) -> list[dict] {
    owed = sum([(rup["paid"] as int | float) for rup in rolled_up]) / len(rolled_up);
    for rup in rolled_up {
        rup["over_under"] = owed - (rup["paid"] as int | float);
        rup["owed"] = owed;
        rup["percent_paid"] = (rup["paid"] as int | float) / owed;
    }
    return rolled_up;
}

"""Interpolate between (*x1*, *y1*) and (*x2*, *y2*) at *x*.

