    """
def intpol(y1: float, y2: float, x1: int, x2: int, x: int) -> object {
    if ((x2 == x1) and (y2 != y1)) {
        print('>>> Warning <<<: No difference between x1 and x2,' 'returned empty!!!');
        return [];
    } elif ((x2 == x1) and (y2 == y1)) {
        return y1;
    } else {
        y = y1 + (((y2 - y1) / (x2 - x1)) * (x - x1));
        return y;
    }
}

