"""
    Orders a set of glyph handles using regular sort and an explicit
    sort order. The explicit draw order must take the form of a list
    of glyph names while the keys should be glyph names with a custom
    suffix. The draw order may only match subset of the keys and any
    matched items will take precedence over other entries.
    """
def glyph_order(keys: list[str], draw_order: list[str] | None = None) -> list[str] {
    if draw_order is None {
        draw_order = [];
    }
    keys = sorted(keys);
    def order_fn(glyph: str) -> tuple[int | float, str] {
        matches = [
            item
            for item in draw_order
            if glyph.startswith(item)
        ];
        return (draw_order.index(matches[0]), glyph)
            if matches
            else ((1000000000.0 + keys.index(glyph)), glyph);
    }
    return sorted(keys, key=order_fn);
}

"""
    Function based on the map function for the arduino
    https://www.arduino.cc/reference/en/language/functions/math/map/
    """
def map_val(val: float, in_min: float, in_max: float, out_min: float, out_max: float) -> float {
    return ((((val - in_min) * (out_max - out_min)) / (in_max - in_min)) + out_min);
}

""" returns i, (period, color) """
def get_current_step(t: float, t0: float, sequence: list[tuple[float, Any]]) -> tuple[int, tuple[float, Any]] {
    period = sum(s[0] for s in sequence);
    tau = t - t0;
    while ((tau - period) > 0) {
        tau -= period;
    }
    i = 0;
    while True {
        current = sequence[i][0];
        if (tau < current) {
            break;
        } else {
            i += 1;
            tau -= current;
        }
    }
    return (i, sequence[i]);
}

"""Encode given number in base 10 to digits in given base.
    number: int -- integer representation of number (in base 10)
    base: int -- base to convert to
    return: str -- string representation of number (in given base)"""
def encode(number: int, base: int) -> str {
    assert (2 <= base <= 36) , 'base is out of range: {}'.format(base);
    assert (number >= 0) , 'number is negative: {}'.format(number);
    dividend: int = number;
    divisor: int = base;
    quotient: int = 1;
    hex_letter_offset: int = 87;
    result: str = '';
    while (quotient != 0) {
        remainder: int | str = 0;
        if (dividend < divisor) {
            remainder = dividend;
            quotient = 0;
        } else {
            remainder = dividend % divisor;
            dividend = (dividend - (remainder as int)) // divisor;
        }
        if ((remainder as int) > 9) {
            remainder = chr((remainder as int) + hex_letter_offset);
        }
        result += str(remainder);
    }
    return result[::-1];
}

"""bisection search (right)"""
def bisect_right(a: list[int], x: int, lo: int = 0, hi: int | None = None) -> int {
    if (hi is None) {
        hi = len(a);
    }
    while (lo < hi) {
        mid = (lo + hi) // 2;
        if (a[mid] <= x) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

"""Compute the angle alpha and projected separation s for each
    time step due to the lens orbital motion.

    :param alpha0: angle alpha at date tb.
    :param s0: projected separation at date tb.
    :param dalpha: float, angular velocity at date tb
        (radians.year^-1).
    :param ds: change rate of separation (year^-1).
    :param t: list of dates.
    :param tb: time reference for linear development.
    :type alpha0: float
    :type s0: float
    :type dalpha: float
    :type ds: float
    :type t: numpy array
    :type tb: float
    :return: unpacked list of actual alpha and s values at each date.
    :rtype: numpy array, numpy array
    """
def lens_rotation(
    alpha0: float, s0: float, dalpha: float, ds: float, t: list, tb: float
) -> object {
    Cte_yr_d = 365.25;
    alpha = alpha0 - ((((t as any) - tb) * dalpha) / Cte_yr_d);
    s = s0 + ((((t as any) - tb) * ds) / Cte_yr_d);
    return (alpha, s);
}

