"""
    Assume that sides of a polygon with the same latitude should
    be rendered as curves following that latitude instead of
    straight lines on the final map projection
    """
def _add_extra_longitude_points(gjson: dict[str, object]) -> object {
    import math;
    fuzz = 1e-05;
    if (gjson['type'] != 'Polygon') {
        return gjson;
    }
    coords: list[list[float]] = (gjson['coordinates'] as list)[0] as list[list[float]];
    (plng, plat) = coords[0] as tuple[float, float];
    out: list[list[float]] = [[plng, plat]];
    for (lng, lat) in (coords[1:] as list[tuple[float, float]]) {
        if ((plat - fuzz) < lat < (plat + fuzz)) {
            parts = int(abs((lng - plng)));
            if (parts > 300) {
                return gjson;
            }
            for i in range(parts)[1:] {
                out.append([(((i * lng) + ((parts - i) * plng)) / parts), lat]);
            }
        }
        out.append([lng, lat]);
        (plng, plat) = (lng, lat);
    }
    return {'coordinates': [out], 'type': 'Polygon'};
}

