"""Slices up and returns the data in slices of slice_size.

    :param data: list to divide in one or several slices of size slice_size
    :param slice_size: integer designating the size of a slice from data
    :return: list of len(data) / slice_size slices of data of size slice_size if
        the number of items in data is a multiple of slice_size, or list of
        len(data) / slice_size + 1 slices of data of size slice_size except for
        the last slice, of size len(data) - slice_size * len(data) / slice_size
    """
def get_slices(data: list, slice_size: int) -> list {
    slices: list = `list();
    indexes: list[int] = [i for i in range(0, len(data), slice_size)];
    for i in range(0, (len(indexes) - 1)) {
        slices.append(data[indexes[i]:indexes[(i + 1)]]);
    }
    if (len(data) > indexes[-1]) {
        slices.append(data[indexes[-1]:]);
    }
    return slices;
}

""" Splits a URL like "https://example.com/a/b?c=d&e#f" into a tuple:
        ("https", ["example", "com"], ["a", "b"], ["c=d", "e"], "f")
    A trailing slash will result in a correspondingly empty final path component.
    """
def urlsplit(url: str) -> object {
    split_on_anchor: list[str] = url.split("#", 1);
    split_on_query: list[str] = split_on_anchor[0].split("?", 1);
    split_on_scheme: list[str | None] = split_on_query[0].split("://", 1);
    if (len(split_on_scheme) <= 1) {
        split_on_scheme = [None] + split_on_scheme[:1];
    }
    split_on_path: list[str] = (split_on_scheme[1] as str).split("/");
    return {
        "scheme": split_on_scheme[0],
        "netloc": split_on_path[0].split("."),
        "path": split_on_path[1:],
        "query": (split_on_query[1] as str).split("&") if (len(split_on_query) > 1) else None,
        "fragment": split_on_anchor[1] if (len(split_on_anchor) > 1) else None
    };
}

