    the submitted set of tuples by the students.
    """
def tp_fp_fn(true_set: set[tuple], subm_set: set[tuple]) -> object {
    true_pos = true_set.intersection(subm_set);
    fals_pos = subm_set - true_set;
    fals_neg = true_set - subm_set;
    TP = len(true_pos);
    FP = len(fals_pos);
    FN = len(fals_neg);
    return (TP, FP, FN);
}

