  24
  >>> sum_multiples(1, 12, 3)
  30
  """
def sum_multiples(start: int, end: int, divisor: int) -> int {
    result: int = 0;
    counter: int = start;
    while (counter <= end) {
        if ((counter % divisor) == 0) {
            result += counter;
        }
        counter += 1;
    }
    return result;
}

