    """
def D(f: Callable[[int | float], float], x: int | float, N: int) -> list {
    sequence = [];
    for i in range(N) {
        sequence.append(
            (
                (f((float(x) + (2.0 ** (-1 * float(i))))) - f(x))
                / (2.0 ** (-1 * float(i)))
            )
        );
    }
