    while (x > 255) {
        x >>= 2;
        shift += 2;
    }
    return (x << shift);
}

"""Return the index where to insert item x in list a, assuming a is sorted.
    The return value i is such that all e in a[:i] have e <= x, and all e in
    a[i:] have e > x.  So if x already appears in the list, a.insert(x) will
    insert just after the rightmost x already there.
    Optional args lo (default 0) and hi (default len(a)) bound the
    slice of a to be searched.
    """
def bisect(a: list, x: object, lo: int = 0, hi: int | None = None) -> int {
    if (lo < 0) {
        raise ValueError('lo must be non-negative');
    }
    if (hi is None) {
        hi = len(a);
    }
    while (lo < hi) {
        mid: int = (lo + hi) // 2;
        if (x < a[mid]) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

"""
    Convolution of 2 causal signals, x(t<0) = y(t<0) = 0, using discrete
    summation.
        x*y(t) = \int_{u=0}^t x(u) y(t-u) du = y*x(t)
    where the size of x[], y[], x*y[] are P, Q, N=P+Q-1 respectively.
    """
def conv(x: list[float], y: list[float]) -> list {
    (P, Q, N) = (len(x), len(y), ((len(x) + len(y)) - 1));
    z: list = [];
    for k in range(N) {
        (lower, upper) = (max(0, (k - (Q - 1))), min((P - 1), k));
        z.append(sum((x[i] * y[(k - i)]) for i in range(lower, (upper + 1))));
    }
    return z;
}

"""
    Arguments:
        v: a float.
        divisor, min_value: integers.
    Returns:
        an integer.
    """
def make_divisible(v: float, divisor: int, min_value: int | None = None) -> int {
    if (min_value is None) {
        min_value = divisor;
    }
    new_v: int = max(min_value as int, ((int((v + (divisor / 2))) // divisor) * divisor));
    if (new_v < (0.9 * v)) {
        new_v += divisor;
    }
    return new_v;
}

