"""
    Returns true if the note in the melody at the specified position is part of
    a correctly formed suspension (dissonance resolving by step onto a
    consonance)
    """
def is_suspension(melody: list[int], position: int, cantus_firmus: list[int]) -> bool {
    current_note = melody[position];
    resolution_note = melody[(position + 1)];
    cantus_firmus_note = cantus_firmus[(position + 1)];
    suspension_interval = current_note - cantus_firmus_note;
    resolution_interval = resolution_note - cantus_firmus_note;
    if ((suspension_interval == 3) and (resolution_interval == 2)) {
        return True;
    }
    if ((suspension_interval == 6) and (resolution_interval == 5)) {
        return True;
    }
    return False;
}

"""
  Finding the dm_Fibonacci sequence with seeds of 1, 1, 2 for n = 0, 1, 2 respectively
  The sequence is 0,1,1,2,3,5,8,13,..., where
  the recursive relation is dm_fibonancci(n) = dm_fibonancci(n-1) + 2* dm_fibonancci(n-2) - dm_fibonancci(n-3)
  :param n: the index, starting from 0
  :return: the sequence
  """
def dm_fibonancci(n: int) -> int {
    n = (n // 1) if (n >= 1) else 0;
    c1 = 1;
    c2 = 2;
    c3 = -1;
    if (n > 2) {
        return (
            (c1 * dm_fibonancci((n - 1)))
            + (c2 * dm_fibonancci((n - 2)))
            + (c3 * dm_fibonancci((n - 3)))
        );
    }
    return 2 if (n == 2) else 1 if (n == 1) else 1;
}

