"""
    Counts the sum of all odd integers from start through end, inclusively.

    Args:
        start (int): starting number in range.
        end (int): ending number in range.

    Returns:
        int: the sum of all odd integers from start through end, inclusively.
    """
def sum_of_odd_integers(start: int, end: int) -> int {
    if ((start % 2) == 0) {
        start += 1;
    }
    sum_of_numbers = 0;
    for number in range(start, (end + 1), 2) {
        sum_of_numbers += number;
    }
    return sum_of_numbers;
}

"""standardise data x to [-1,1]


    Parameters

    x: original data
    l1: lower bound
    l2: upper bound
    ----------

    Returns
    -------

    standardised data


    """
def standardise1(x: float, l1: float, l2: float) -> float {
    x -= l1;
    x *= 2 / float((l2 - l1));
    x -= 1;
    return x;
}

