    return token.lower();
}

"""acos -  Safe inverse cosine

     Input argument c is shrunk to admissible interval
     to avoid case where a small rounding error causes
     a math domain error.
  """
def acos(c: float) -> float {
    import from math { acos }
    if (c > 1) {
        c = 1;
    }
    if (c < -1) {
        c = -1;
    }
    return acos(c);
}

