}

"""Linearly scales all the values in the sequence to lie between the given values.
    Shifts up to minval and scales by the difference ``maxval-minval``
    If all values are identical, then sets them to `minval`."""
def linscale(seq: list[float], minval: float = 0.0, maxval: float = 1.0) -> list[float] {
    (m, M) = (min(seq), max(seq));
    def sc(s: float, m: float = m, M: float = M) -> float {
        if (m == M) {
            return minval;
        }
        return (minval + (((s - m) / float((M - m))) * (maxval - minval)));
    }
    seq = [sc(s) for s in seq];
    return seq;
}

"""U_code = snapdict['InternalEnergy'] INTERNAL ENERGY_code = VELOCITY_code^2 = (params.txt default = (km/s)^2)
    helium_mass_fraction = snapdict['Metallicity'][:,1]
    ElectronAbundance= snapdict['ElectronAbundance']"""
def getTemperature(
    U_code: float,
    helium_mass_fraction: float | None = None,
    ElectronAbundance: float | None = None,
    mu: float | None = None
) -> float {
    U_cgs: float = U_code * 10000000000.0;
    gamma: float = 5 / 3.0;
    kB: float = 1.38e-16;
    m_proton: float = 1.67e-24;
    if (mu is None) {
        try {
            assert (helium_mass_fraction is not None);
            assert (ElectronAbundance is not None);
        } except AssertionError {
            raise ValueError(
                "You need to either provide mu or send helium mass fractions and electron abundances to calculate it!"
            );
        }
        y_helium: float = (helium_mass_fraction as float) / (4 * (1 - (helium_mass_fraction as float)));
        mu = (1.0 + (4 * y_helium)) / (1 + y_helium + (ElectronAbundance as float));
    }
    mean_molecular_weight: float = (mu as float) * m_proton;
    return ((mean_molecular_weight * (gamma - 1) * U_cgs) / kB);
}

"""Binary search."""
def binary_search(lo: int, hi: int, condition: Callable[[int], str]) -> int {
    while (lo <= hi) {
        mid = (lo + hi) // 2;
        result = condition(mid);
        if (result == 'found') {
            return mid;
        } elif (result == 'left') {
            hi = mid - 1;
        } elif (result == 'right') {
            lo = mid + 1;
        }
    }
    return -1;
}

"""Kullback-Leibler divergence for Gaussian distributions."""
def klGauss(x: float, y: float, sig2: float = 1.0) -> float {
    return (((x - y) * (x - y)) / (2 * sig2));
}

"""
    Generates an initial job sequence based on a weighted combination of
    the earliest-due-date and the shortest-processing-time
    dispatching strategy. The job sequence will be feed to the model.
    """
def edd_x_spt_pre_sequencing(
    dataset: dict,
    w_edd: float = 0.5,
    w_spt: float = 0.5,
    *_args: object,
    **_kwargs: object,
) -> list {
    sequence: list = [job for job in dataset.values()];
    sequence = sorted(
        sequence, key=lambda (job: dict) { (job["due date"] as float); }
    );
    rank = 1;
    prev_job: dict | None = None;
    for job in sequence {
        if (
            prev_job
            and ((job["due date"] as float) != (prev_job["due date"] as float))
        ) {
            rank += 1;
        }
        job["rank"] = rank;
        prev_job = job;
    }
    sequence = sorted(
        sequence,
        key=lambda (job: dict) {
            ((job["t_smd"] as float) + (job["t_aoi"] as float));
        },
    );
    rank = 1;
    prev_job = None;
    for job in sequence {
        if (
            prev_job
            and (
                ((job["t_smd"] as float) + (job["t_aoi"] as float))
                != ((prev_job["t_smd"] as float) + (prev_job["t_aoi"] as float))
            )
        ) {
            rank += 1;
        }
        job["rank"] = (w_edd * (job["rank"] as float)) + (w_spt * (rank as float));
        prev_job = job;
    }
    sequence = sorted(sequence, key=lambda (job: dict) { (job["rank"] as float); });
    return sequence;
}

