"""
    Calculates the Coordinates of the intersection Area.
    """
def calc_intersection(actual_position: dict[str, int], calculated_position: dict[str, int]) -> dict[str, int] {
    x_actual = actual_position.get("x", None) as int;
    y_actual = actual_position.get("y", None) as int;
    w_actual = actual_position.get("width", None) as int;
    h_actual = actual_position.get("height", None) as int;
    x_calculated = calculated_position.get("x", None) as int;
    y_calculated = calculated_position.get("y", None) as int;
    w_calculated = calculated_position.get("width", None) as int;
    h_calculated = calculated_position.get("height", None) as int;
    x1 = x_actual if (x_actual > x_calculated) else x_calculated;
    y1 = y_actual if (y_actual > y_calculated) else y_calculated;
    x2 = ((x_actual + w_actual) - 1)
        if (((x_actual + w_actual) - 1) < ((x_calculated + w_calculated) - 1))
        else ((x_calculated + w_calculated) - 1);
    y3 = ((y_actual + h_actual) - 1)
        if (((y_actual + h_actual) - 1) < ((y_calculated + h_calculated) - 1))
        else ((y_calculated + h_calculated) - 1);
    x = x1;
    y = y1;
    w = (x2 - x1) + 1;
    h = (y3 - y1) + 1;
    return {"x": x, "y": y, "width": w, "height": h};
}

