"""
    Returns  ``population`` choose ``sample``, given
    by: n! / k!(n-k)!, where n == ``population`` and
    k == ``sample``.
    """
def choose(population: int, sample: int) -> object {
    if (sample > population) {
        return 0;
    }
    s = max(sample, (population - sample));
    assert (s <= population);
    assert (population > -1);
    if (s == population) {
        return 1;
    }
    numerator = 1;
    denominator = 1;
    for i in range((s + 1), (population + 1)) {
        numerator *= i;
        denominator *= i - s;
    }
    return (numerator / denominator);
}

"""
    Takes a byterange spanning some segments and converts that into a
    byterange spanning the corresponding fragments within their fragment
    archives.

    Handles prefix, suffix, and fully-specified byte ranges.

    :param segment_start: first byte of the first segment
    :param segment_end: last byte of the last segment
    :param segment_size: size of an EC segment, in bytes
    :param fragment_size: size of an EC fragment, in bytes

    :returns: a 2-tuple (frag_start, frag_end) where

      * frag_start is the first byte of the first fragment, or None if this
        is a suffix byte range

      * frag_end is the last byte of the last fragment, or None if this is a
        prefix byte range
    """
def segment_range_to_fragment_range(
    segment_start: int | None,
    segment_end: int | None,
    segment_size: int,
    fragment_size: int,
) -> tuple[int | None, int | None] {
    fragment_start = ((segment_start // segment_size) * fragment_size)
        if (segment_start is not None)
        else None;
    fragment_end = None
        if (segment_end is None)
        else (((segment_end + 1) // segment_size) * fragment_size)
            if (segment_start is None)
            else ((((segment_end + 1) // segment_size) * fragment_size) - 1);
    return (fragment_start, fragment_end);
}

