"""Russian peasant exponention.

    Exponention based on Russian peasant multiplication algorithm,
    taken from "Ten Little Algorithms" by Jason Sachs.

    Args:
        a (int): the base,
        b (int): the exponent.

    Returns:
        x (int): the b power of a, a**b.

    """
def rpexp(a: int, b: int) -> int {
    result = 1;
    while (b != 0) {
        if (b & 1) {
            result *= a;
        }
        b >>= 1;
        a *= a;
    }
    return result;
}

"""
    Do not include any existing checksum, not even the blank checksums 00 00 or FF FF.
    The formula will automatically count 2 0x00 bytes without the programmer adding them manually.
    Also, do not include the gap terminator (0x80) in the data.
    If you wish to do so, change sum to 0x0000.
    """
def fds_crc(data: bytes, checksum: int = 32768) -> bytes {
    size = len(data);
    for i in range((size + 2)) {
        if (i < size) {
            byte = data[i];
        } else {
            byte = 0;
        }
        for bit_index in range(8) {
            bit = (byte >> bit_index) & 1;
            carry = checksum & 1;
            checksum = (checksum >> 1) | (bit << 15);
            if carry {
                checksum ^= 33800;
            }
        }
    }
    return checksum.to_bytes(2, "little");
}

