        return (abs(y) < eps);
    }
    assert (abs(((x - y) / y)) < eps);
}

"""
    >>> bytes2human(10000)
    '9K'
    >>> bytes2human(100001221)
    '95M'
    """
def bytes2human(n: int | float, format: str = "%(value)i%(symbol)s") -> str {
    symbols = ('B', 'K', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y');
    prefix: dict[str, int] = {};
    for (i, s) in enumerate(symbols[1:]) {
        prefix[s] = 1 << ((i + 1) * 10);
    }
    for symbol in reversed(symbols[1:]) {
        if (n >= prefix[symbol]) {
            value: float = float(n) / prefix[symbol];
            return (format % `dict(locals() as dict[str, object], value=value));
        }
    }
    return (format % `dict(symbol=symbols[0], value=n));
}

"""Computes if slice first and second overlap for the size of the dimension"""
def _union_1d(first: slice, second: slice, size: int) -> slice | None {
    (first_min, first_max, _) = first.indices(size) as tuple[int, int, int];
    (second_min, second_max, _) = second.indices(size) as tuple[int, int, int];
    if ((first_max >= second_min) and (second_max >= first_min)) {
        return slice(min(first_min, second_min), max(first_max, second_max));
    }
    return None;
}

