    If fail, return None
    """
obj _LogLike {
    def cl_error(msg: str, key: str);
}

def parameter_dict_merge(log: _LogLike, param_dicts: list[dict[str, object]]) -> object {
    merged_dict: dict[str, object] = {};
    for param_dict in param_dicts {
        for (key, value) in param_dict.items() {
            if (key not in merged_dict) {
                merged_dict[key] = value;
                continue;
            }
            if (merged_dict[key] != value) {
                log.cl_error("ambiguous values for key [%s] in parameters", key);
                return None;
            }
        }
    }
    return merged_dict;
}

"""Sort list using quick sort.

    Complexity: O(n log n).  Worst: O(n2)

    @param l list to sort.
    @returns sorted list.
    """
def quicksort(l: list) -> list {
    if (len(l) <= 1) {
        return l;
    }
    pivot = l[0];
    less: list = [];
    equal: list = [];
    greater: list = [];
    for e in l {
        if (e < pivot) {
            less.append(e);
        } elif (e == pivot) {
            equal.append(e);
        } else {
            greater.append(e);
        }
    }
    return (quicksort(less) + equal + quicksort(greater));
}

"""Checks if entities overlap.
    I.e. cross each others start and end boundaries.
    :param entities: list of entities
    :return: boolean
    """
def do_entities_overlap(entities: list[dict]) -> object {
    sorted_entities = sorted(entities, key=lambda (e: dict) { (e["start"] as int); });
    for i in range((len(sorted_entities) - 1)) {
        curr_ent: dict = sorted_entities[i];
        next_ent: dict = sorted_entities[(i + 1)];
        if (
            ((next_ent["start"] as int) < (curr_ent["end"] as int))
            and ((next_ent["entity"] as object) != (curr_ent["entity"] as object))
        ) {
            return True;
        }
    }
    return False;
}

