"""Convert comma-delimted kwargs argument into a normalized dictionary.

  Args:
    raw_value: [string] Comma-delimited key=value bindings.
  """
def binding_string_to_dict(raw_value: str) -> dict[str, str | bool | int] {
    kwargs: dict[str, str | bool | int] = {};
    if raw_value {
        for binding in raw_value.split(',') {
            (name, value) = binding.split('=');
            parsed_value: str | bool | int = value;
            if (value.lower() == 'true') {
                parsed_value = True;
            } elif (value.lower() == 'false') {
                parsed_value = False;
            } elif value.isdigit() {
                parsed_value = int(value as str);
            }
            kwargs[name] = parsed_value;
        }
    }
    return kwargs;
}

