"""A deeply inadequate floating point comparison."""
def floats_equal(x: float, y: float) -> bool {
    small = 0.0001;
    if ((x == y) or ((x < small) and (y < small))) {
        return True;
    }
    epsilon = max(abs(x), abs(y)) * small;
    return (abs((x - y)) < epsilon);
}

"""splits a mask into its bottom_any and empty parts"""
def _decode_mask(mask: int) -> tuple[list[int], list[int]] {
    empty: list[int] = [];
    bottom_any: list[int] = [];
    for i in range(32) {
        if (((mask >> i) & 1) == 1) {
            empty.append(i);
        }
        if (((mask >> (i + 32)) & 1) == 1) {
            bottom_any.append(i);
        }
    }
    return (bottom_any, empty);
}

