"""
    Linear mapping between two ranges of values
    """
def map_range(x: int | float, x_min: int | float, x_max: int | float, y_min: int | float, y_max: int | float) -> int {
    x = float(x);
    x_range = x_max - x_min;
    y_range = y_max - y_min;
    xy_ratio = x_range / y_range;
    y = ((x - x_min) / xy_ratio) + y_min;
    return int(y);
}

"""
       blending function polynomial
       d = delta x = xabs - xdr
       u = uncertainty radius of xabs estimate error
       s = tuning scale factor

       returns blend
    """
def blend3(d: float = 0.0, u: float = 1.0, s: float = 0.05) -> float {
    d = float(d);
    u = float(u);
    s = min(1.0, float(abs(s)));
    b = 1.0 - (s ** ((d * d) / (u * u)));
    return b;
}

"""
    Convert mean/dispersion parameterization of a negative binomial to the ones scipy supports

    See https://en.wikipedia.org/wiki/Negative_binomial_distribution#Alternative_formulations
    """
def convert_params(mu: float, alpha: float) -> tuple[float, float] {
    r = 1.0 / alpha;
    var = mu + ((1.0 / r) * (mu ** 2));
    p = (var - mu) / var;
    return (r, (1.0 - p));
}

"""Find replica groups for SPMD."""
def _find_replica_groups(
    global_x: int, inner_x: int, inner_y: int, outer_group_size: int
) -> list[list[int]] {
    groups_x: int = global_x // inner_x;
    inner_replica_groups: list[list[int]] = [];
    for group_id in range(outer_group_size) {
        sub_group_ids: list[int] = [];
        row_group_id: int = group_id // groups_x;
        col_group_id: int = group_id % groups_x;
        starting_id: int = (row_group_id * inner_y * global_x) + (col_group_id * inner_x);
        for y in range(inner_y) {
            inner_group_ids: list[int] = `list(range(starting_id, (starting_id + inner_x)));
            if ((y % 2) == 1) {
                inner_group_ids.reverse();
            }
            sub_group_ids.extend(inner_group_ids);
            starting_id += global_x;
        }
        inner_replica_groups.append(sub_group_ids);
    }
    return inner_replica_groups;
}

"""
    coord_to_string(h_or_d, m, s):
       Return a formatted string of RA or DEC values as
       'hh:mm:ss.ssss' if RA, or 'dd:mm:ss.ssss' if DEC.
    """
def coord_to_string(h_or_d: int | float, m: int | float, s: int | float) -> str {
    retstr: str = "";
    if (h_or_d < 0) {
        retstr = "-";
    } elif (abs(h_or_d) == 0) {
        if ((m < 0.0) or (s < 0.0)) {
            retstr = "-";
        }
    }
    (h_or_d, m, s) = (abs(h_or_d), abs(m), abs(s));
    if (s >= 9.9995) {
        return (retstr + ("%.2d:%.2d:%.4f" % (h_or_d, m, s)));
    }
    return (retstr + ("%.2d:%.2d:0%.4f" % (h_or_d, m, s)));
}

