    Returns a single value to use as either a fitness function or Pareto indicator if our objective is a list
    If we have a list of list, flatten to a single list.
    """
def get_objective_value(val: list | int | float, goal_type: str | None = None) -> int | float | list {
    if (`type(val) == `list) {
        try {
            val = [item for sublist in (val as list) for item in sublist];
        } except TypeError {
            ;
        }
    }
    obj_val: int | float | list;
    if (goal_type == 'max') {
        obj_val = max(val as list);
    } elif (goal_type == 'min') {
        obj_val = min(val as list);
    } elif (goal_type == 'avg') {
        obj_val = sum(val as list) / len(val as list);
    } elif (goal_type == 'abs max') {
        obj_val = max([abs(x) for x in (val as list)]);
    } elif (goal_type == 'abs min') {
        obj_val = min([abs(x) for x in (val as list)]);
    } else {
        obj_val = val;
    }
    return obj_val;
}

