"""
    Find the inverse of a Clifford gate.

    Args:
        num_qubits: the dimension of the Clifford.
        gatelist: a Clifford gate.

    Returns:
        An inverse Clifford gate.
    """
def find_inverse_clifford_gates(num_qubits: int, gatelist: list[str]) -> list[str] {
    if (num_qubits in (1, 2)) {
        inv_gatelist: list[str] = gatelist.copy();
        inv_gatelist.reverse();
        for (i, _) in enumerate(inv_gatelist) {
            split: list[str] = inv_gatelist[i].split();
            if (split[0] == 'v') {
                inv_gatelist[i] = 'w ' + split[1];
            } elif (split[0] == 'w') {
                inv_gatelist[i] = 'v ' + split[1];
            }
        }
        return inv_gatelist;
    }
    raise ValueError("The number of qubits should be only 1 or 2");
}

"""
    Return a vector of the positions of (first)
    matches of its first argument in its second.

    Parameters
    ----------
    v1: array_like
        Values to be matched

    v2: array_like
        Values to be matched against

    nomatch: int
        Value to be returned in the case when
        no match is found.

    incomparables: array_like
        Values that cannot be matched. Any value in ``v1``
        matching a value in this list is assigned the nomatch
        value.
    start: int
        Type of indexing to use. Most likely 0 or 1
    """
def `match(
    v1: list, v2: list, nomatch: int = -1, incomparables: list | None = None, start: int = 0
) -> list {
    v2_indices: dict[object, int] = {};
    for (i, x) in enumerate(v2) {
        if (x not in v2_indices) {
            v2_indices[x] = i;
        }
    }
    v1_to_v2_map: list[int] = [nomatch] * len(v1);
    `skip: set[object] = `set(incomparables) if incomparables else `set[object]();
    for (i, x) in enumerate(v1) {
        if (x in `skip) {
            continue;
        }
        try {
            v1_to_v2_map[i] = v2_indices[x] + start;
        } except KeyError {
            ;
        }
    }
    return v1_to_v2_map;
}

