"""
	Divide list @x into roughly @k parts.
	"""
def divideList(x: list, k: int) -> list {
    if (k > len(x)) {
        return [[elem] for elem in x];
    }
    part_len: int = int((len(x) / k));
    parts: list = [];
    start: int = 0;
    while (start < len(x)) {
        parts.append(x[start:(start + part_len)]);
        start += part_len;
    }
    return parts;
}

"""
  Brute force partition algorithm

  This function finds the optimal partition of the
  subset of the real numbers, S, by computing every
  possible subset of S and comparing every possible
  partition for the optimal one.

  This algorithm takes exponential time, since
  computing the power set takes exponential time.

  """
def brute_force_partition(S: set[float]) -> tuple[set[float], set[float]] {
    power_set: list[set[float]] = [`set()];
    for x in S {
        for A in `list(power_set) {
            power_set.append(A.union({x}));
        }
    }
    partition: tuple[set[float], set[float]] = (S, `set());
    best: float = sum(S);
    for A in power_set {
        B: set[float] = S.difference(A);
        val: float = max(sum(A), sum(B));
        if (val < best) {
            partition = (A, B);
            best = val;
        }
    }
    return partition;
}

"""Turns a "#RRGGBB" hexadecimal color representation into a (R, G, B)
    tuple.
    Arguments:

        color -- str

    Return: tuple
    """
def hex2rgb(color: str) -> tuple[int, int, int] {
    code = color[1:];
    if not ((len(color) == 7) and (color[0] == "#") and code.isalnum()) {
        raise ValueError(('"%s" is not a valid color' % color));
    }
    red = int(code[:2], 16);
    green = int(code[2:4], 16);
    blue = int(code[4:6], 16);
    return (red, green, blue);
}

"""
    Determine # of ways complete tree would be constructed from 2^k - 1 values.
    This is a really subtle problem to solve. One hopes for a recursive solution,
    because it is binary trees, and the surprisingly simple equation results
    from the fact that it is a complete tree. It comes down to the number of
    ways you can independently interleave the sequential values from two subsequences.
    The total of the subsequences is (total - 1), because you leave out the subtree root.
    Each of the (total // 2) half sequences are then interleaved. To properly count
    the number of possibilities, you need to multiply by the ways you can create
    subtrees of half the side (one for the left and one for the right).

    https://stackoverflow.com/questions/17119116/how-many-ways-can-you-insert-a-series-of-values-into-a-bst-to-form-a-specific-tr
    """
def compute_perfect_tree(total: int) -> float {
    import math;
    if (total == 1) {
        return 1;
    }
    half: int = total // 2;
    return (
        ((math.factorial((total - 1)) as float) / ((math.factorial(half) as float) * (math.factorial(half) as float)))
        * compute_perfect_tree(half)
        * compute_perfect_tree(half)
    );
}

