"""Stirling Numbers of the Second Kind"""
def stirling_numbers_2(n: int, k: int) -> int {
    if (n == k) {
        return 1;
    }
    if ((n == 0) and (k == 0)) {
        return 1;
    }
    if ((n == 0) or (k == 0)) {
        return 0;
    }
    return (
        (k * stirling_numbers_2((n - 1), k)) + stirling_numbers_2((n - 1), (k - 1))
    );
}

