"""Return closest greater multiple of `k` to `n`."""
def closest_multiple(n: int, k: int, ceil: bool = True) -> int | float {
    if (n == 0) {
        return 0;
    }
    if (n < k) {
        return k;
    }
    if ((n % k) == 0) {
        return n;
    }
    return (k * ((n / k) + 1 if ceil else 0));
}

"""Apply function to 1-... generating a list of elements within
    'lower' and 'upper' limits (inclusive)."""
def generateNums(function: Callable[[int], int | float], lower: int | float, upper: int | float) -> object {
    print(("Generating list for function " + function.__name__));
    numList = [];
    i = 0;
    num: int | float = 0;
    while (num <= upper) {
        num = function(i);
        if ((num >= lower) and (num <= upper)) {
            numList.append(num);
        }
        i += 1;
    }
    return numList;
}

"""Check if 2D coordinates are within a circle

    Optional arguments offset the circle's centre and specify radius

    returns True if x,y is in circle of position a,b and radius r
    """
def in_circle(x: int | float, y: int | float, a: int | float = 0, b: int | float = 0, r: int | float = 25) -> object {
    return ((((x - a) * (x - a)) + ((y - b) * (y - b))) < (r ** 2));
}

"""Unpacks a 32 bit word into 4 signed byte length values."""
def unpack_bytes(word: int) -> object {
    def as_8bit_signed(val: int) -> object {
        val = val & 255;
        return val if (val < 128) else (val - 256);
    }
    return (
        as_8bit_signed(word),
        as_8bit_signed((word >> 8)),
        as_8bit_signed((word >> 16)),
        as_8bit_signed((word >> 24))
    );
}

"""This just calculates the 6 points in our basic figure of eight
    should be easy enough and we then draw lines between each point and
    get the last point

    >>> calc_route(400, 300, 200, 100)
    [(200, 400), (100, 300), (200, 200), (600, 400), (700, 300), (600, 200)]

    """
def calc_route(
    centrex: int = 400, centrey: int = 300, halfwidth: int = 200, radius: int = 100
) -> list[tuple[int, int]] {
    leftx = centrex - halfwidth;
    rightx = centrex + halfwidth;
    pt0 = (leftx, (centrey + radius));
    pt1 = ((leftx - radius), centrey);
    pt2 = (leftx, (centrey - radius));
    pt3 = (rightx, (centrey + radius));
    pt4 = ((rightx + radius), centrey);
    pt5 = (rightx, (centrey - radius));
    return [pt0, pt1, pt2, pt3, pt4, pt5];
}

"""
    This module limits the values to the range of [0,limit]
    """
def limit_x(x: float, limit: float) -> float {
    x_gr_limit = x > limit;
    x_le_limit = (x_gr_limit * limit) + ((1 - x_gr_limit) * x);
    x_gr_zero = x > 0.0;
    x_norm = x_gr_zero * x_le_limit;
    return x_norm;
}

"""Recursive function that sorts protein group by a number of sorting
    functions."""
def sort_protein_group(pgroup: list, sortfunctions: list, sortfunc_index: int) -> list {
    pgroup_out: list = [];
    subgroups: list = (sortfunctions[sortfunc_index] as any)(pgroup);
    sortfunc_index += 1;
    for subgroup in subgroups {
        if ((len(subgroup as list) > 1) and (sortfunc_index < len(sortfunctions))) {
            pgroup_out.extend(
                sort_protein_group(subgroup as list, sortfunctions, sortfunc_index)
            );
        } else {
            pgroup_out.extend(subgroup as list);
        }
    }
    return pgroup_out;
}

"""Resi dani sudoku. V tabeli t velikosti 9 x 9 so ze vpisana nekatera stevila.
    Prazna polja so oznacena z 0."""
def sudoku(t: list[list[int]]) -> list[list[int]] | None {
    def mozne_poteze(u: int, v: int) -> list[int] {
        sez_vrstica = [
            t[u][i]
            for i in range(0, 9)
            if (t[u][i] != 0)
        ];
        sez_stolpec = [
            t[i][v]
            for i in range(0, 9)
            if (t[i][v] != 0)
        ];
        x = (u // 3) * 3;
        y = (v // 3) * 3;
        sez_kvadratek = [
            t[i][j] for i in range(x, (x + 3))
            for j in range(y, (y + 3))
            if (t[i][j] != 0)
        ];
        sez = sez_kvadratek + sez_stolpec + sez_vrstica;
        return [
            i
            for i in range(1, 10)
            if (i not in sez)
        ];
    }
    def naslednje_polje(u: int, v: int) -> tuple[int, int] {
        if (v < 8) {
            return (u, (v + 1));
        }
        return ((u + 1), 0);
    }
    def sestopaj(u: int, v: int) -> list[list[int]] | None {
        while ((u < 9) and (t[u][v] != 0)) {
            (u, v) = naslednje_polje(u, v);
        }
        if ((u, v) == (9, 0)) {
            return t;
        }
        for k in mozne_poteze(u, v) {
            t[u][v] = k;
            r: list[list[int]] | None = sestopaj(u, v);
            if (r is None) {
                t[u][v] = 0;
            } else {
                return r;
            }
        }
        return None;
    }
    return sestopaj(0, 0);
}

"""Add coordinates to a set of points that the wire passes through. They
    are defined as a number of steps horizontally or vertically from the
    starting point for this particular instruction.

    Parameters
    ----------
    hor_steps : int
        number of steps to take along the x direction
    vert_steps : int
        number of steps to take along the y direction
    start_x : int
        x coordinate of starting point
    start_y : int
        y coordinate of starting point
    wire_coords : set
        set of coordinates that the wire passes through

    Returns
    -------
    start_x : int
        x coordinate of end point
        (will be the starting point for the next instruction)
    start_y : int
        y coordinate of end point
        (will be the starting point for the next instruction)
    wire_coords : set
        set of coordinates that the wire passes through
    """
def steps_to_coords(
    hor_steps: int, vert_steps: int, start_x: int, start_y: int, wire_coords: set
) -> tuple[tuple[int, int], set] {
    if (hor_steps > 0) {
        for x in range(1, (hor_steps + 1)) {
            wire_coords.add(((start_x + x), start_y));
        }
    } elif (hor_steps < 0) {
        for x in range(1, ((-1 * hor_steps) + 1)) {
            wire_coords.add(((start_x - x), start_y));
        }
    }
    if (vert_steps > 0) {
        for y in range(1, (vert_steps + 1)) {
            wire_coords.add((start_x, (start_y + y)));
        }
    } elif (vert_steps < 0) {
        for y in range(1, ((-1 * vert_steps) + 1)) {
            wire_coords.add((start_x, (start_y - y)));
        }
    }
    (start_x, start_y) = ((start_x + hor_steps), (start_y + vert_steps));
    return ((start_x, start_y), wire_coords);
}

"""
    Returns x/y in percent as a formatted string with two
    decimal places.
    """
def pct_format(x: int | float, y: int | float) -> str {
    return "{:.2f} %".format(((x / y) * 100));
}

"""Returns (n/d) mod m. Works because the modular multiplicative
    inverse of d is equal to d^(m-2) mod m as long as m is prime."""
def mod_div(n: int, d: int, m: int) -> int {
    inverse = pow(d, (m - 2), m);
    return ((n * inverse) % m);
}

""" Returns m and b of y = mx + b equation for the provided points. """
def get_line(x0: float, y0: float, x1: float, y1: float) -> tuple[float, float] {
    m = (y1 - y0) / (x1 - x0);
    b = y0 - (m * x0);
    return (m, b);
}

"""Parse the seat specification string, and return the seat ID

    :param seat_str: Seat specification string
    :return: Seat ID
    """
def get_seat_id(seat_str: str) -> int {
    row = 0;
    col = 0;
    for (i, char) in enumerate(seat_str[:7]) {
        row += (char == 'B') * ((2 ** (6 - i)) as int);
    }
    for (i, char) in enumerate(seat_str[7:]) {
        col += (char == 'R') * ((2 ** (2 - i)) as int);
    }
    return ((row * 8) + col);
}

"""Get two's complement of `raw_val`.

        Args:
            raw_val (int): Raw value
            length (int): Max bit length

        Returns:
            int: Two's complement
        """
def getTwosComplement(raw_val: int, length: int) -> int {
    val = raw_val;
    if (raw_val & (1 << (length - 1))) {
        val = raw_val - (1 << length);
    }
    return val;
}

"""
    return the index of the first position of codon in the dna sequence

    @type  posLastStop: int
    @param posLastStop: Position of the last found stop codon.
    @type  sequence: string
    @param sequence: Nucleotide sequence.
    @type  codon: string
    @param codon: 3-letter DNA code.
    @rtype:   int
    @return:  The position of the stop codon in the nucleotide sequence.
    """
def findstop_help(posLastStop: int, sequence: str, codon: str) -> int {
    try {
        return sequence.index(codon, posLastStop);
    } except Exception {
        return -1;
    }
}

""" Search session id from rtsp strings
  """
def sessionid(recst: bytes) -> str | None {
    text: str = recst.decode();
    recs: list[str] = text.split('\r\n');
    for rec in recs {
        ss: list[str] = rec.split();
        if (ss[0].strip() == "Session:") {
            return ss[1].strip();
        }
    }
}

"""
    Substitute parameters into the query
    :param query: input query with params
    :param params: values used to substitute
    :return:
    """
def make_query_string(query: str, params: list[str]) -> str {
    query_string = query;
    index = 1;
    for param in params {
        if param {
            to_replace = "%%param%d%%" % index;
            query_string = query_string.replace(to_replace, param);
        }
        index += 1;
    }
    return query_string;
}

"""Calculates the circumference of a square.

    Calculates the circumference of a square based on the lenth of side.

    Args:
        length (float) : length is the length of side of a square.

    Returns:
        float: circumference of the square.
    """
def circ_square(length: float) -> float {
    if (length < 0) {
        raise ValueError("The length of side must be >= 0.");
    }
    area_output = 4 * length;
    return area_output;
}

"""Return the number of nodes and processors per node to use."""
def get_ppn_and_nodes(num_procs: int, procs_per_node: int) -> tuple[int, int] {
    if (num_procs >= procs_per_node) {
        ppn = procs_per_node;
        num_nodes = num_procs // ppn;
    } else {
        ppn = num_procs;
        num_nodes = 1;
    }
    return (ppn, num_nodes);
}

"""Return a divided by b and Raise exception for b==0"""
def div(a: int | float, b: int | float) -> float {
    if not b {
        raise ValueError("Cannot divide by zero!");
    }
    return (a / b);
}

"""Return a nicely formatted number in .f or .e format."""
def format_num(x: int | float, ndecimals: int = 2, plus_sym: bool = False) -> str {
    fmt = '%.' + str(ndecimals);
    if (abs(x) < (10 ** -ndecimals)) {
        fmt = fmt + 'e';
    } else {
        fmt = fmt + 'f';
    }
    if (plus_sym and (x > 0)) {
        fmt = '+' + fmt;
    }
    return (fmt % x);
}

"""
    fun assigns 1 if input string
    is in alphabet, otherwise
    it returns 0.

    parameters:
    x_nt = nucleotide on x axis
    y_nt = nucleotide on y axis
    alphabet = dict of nt_pair:score
    """
def watson_crick(x_nt: str, y_nt: str, alphabet: dict[str, float] | None = None) -> object {
    if not alphabet {
        alphabet = {"AT": 1.0, "TA": 1.0, "GC": 1.0, "CG": 1.0};
    }
    pair = x_nt + y_nt;
    return alphabet.get(pair, 0);
}

"""
    Perform a vertical flip (along the horizontal axis) of
    all the pairs in the network. Such a flip should result
    in a valid sorting network (provided the network used
    for the flip was valid itself).
    """
def vertical_flip(pairs: list[tuple[int, int]]) -> list[tuple[int, int]] {
    max_idx = max(pairs, key=lambda (pair: tuple[int, int]) { pair[1]; })[1];
    return [((max_idx - p1), (max_idx - p0)) for (p0, p1) in pairs];
}

"""
    Given two dicts containing info about repositories, determine if they are the same
    repository.
    Each of the dicts must have the following keys: `changeset_revisions`( if check revisions is true), `name`, `owner`, and
    (either `tool_shed` or `tool_shed_url`).
    """
def the_same_repository(
    repo_1_info: dict[str, str | None],
    repo_2_info: dict[str, str | None],
    check_revision: bool = True
) -> bool {
    if (
        not check_revision
        or repo_1_info.get('changeset_revision') == repo_2_info.get('changeset_revision')
    ) {
        if repo_1_info.get('name') == repo_2_info.get('name') {
            if repo_1_info.get('owner') == repo_2_info.get('owner') {
                t1ts = repo_1_info.get('tool_shed', repo_1_info.get('tool_shed_url', None));
                t2ts = repo_2_info.get('tool_shed', repo_2_info.get('tool_shed_url', None));
                if (t1ts as str) in (t2ts as str) or (t2ts as str) in (t1ts as str) {
                    return True;
                }
            }
        }
    }
    return False;
}

"""Returns dict with the dunder keys converted back to nested dicts

    eg::

        >>> undunder_keys({'a': 'hello', 'b__c': 'world'})
        {'a': 'hello', 'b': {'c': 'world'}}

    :param _dict : (dict) flat dict
    :rtype       : (dict) nested dict

    """
def undunder_keys(_dict: dict) -> dict {
    def f(key: str, value: any) -> dict {
        parts = key.split('__');
        return {parts[0]: value if (len(parts) == 1) else f(parts[1], value)};
    }
    result: dict = {};
    for r in [f(k as str, v) for (k, v) in _dict.items()] {
        rk = `list(r.keys())[0];
        if (rk not in result) {
            result.update(r);
        } else {
            (result[rk] as dict).update(r[rk] as dict);
        }
    }
    return result;
}

"""
    :type n: int
    :rtype: bool
    """
def isPowerOfThree(n: int) -> bool {
    return ((n > 0) and (((3 ** 19) % n) == 0));
}

"""Calculate error in batches using the given valid/test model."""
def calc_error_by_batches(model: Callable[[int, int], float], data_size: int, batch_size: int) -> float {
    err = 0.0;
    beg = 0;
    while (beg < data_size) {
        end = min((beg + batch_size), data_size);
        err += model(beg, end) * (end - beg);
        beg = end;
    }
    return (err / data_size);
}

"""
    I stands for init, as in initialCounts, T stands for Transfered, as in transfered Counts.
    """
def getSurvivalBoolData(
    ICounts: list[int | float],
    TCounts: list[int | float],
    IThreshold: int | float,
    TThreshold: int | float,
) -> object {
    (IAtoms, TAtoms) = [[] for _ in range(2)];
    for (IPoint, TPoint) in zip(ICounts, TCounts) {
        IAtoms.append((IPoint > IThreshold));
        TAtoms.append((TPoint > TThreshold));
    }
    return (IAtoms, TAtoms);
}

"""Calculate the resolution element using dw=r*w/A/fcol

       returns resolution element in mm
    """
def _calc_resolelement(w: float, fcol: float, r: float, A: float) -> object {
