}

"""U_codes = res['']
        y_heliums = res['z'][:,1]
        ElectronAbundance=res['ne']"""
def getTemperature(U_code: float, y_helium: float, ElectronAbundance: float) -> float {
    U_cgs = U_code * 10000000000.0;
    gamma = 5 / 3.0;
    kB = 1.38e-16;
    m_proton = 1.67e-24;
    mu = (1.0 + (4 * y_helium)) / (1 + y_helium + ElectronAbundance);
    mean_molecular_weight = mu * m_proton;
    return ((mean_molecular_weight * (gamma - 1) * U_cgs) / kB);
}

"""Quadratic interpolation for estimating the true position of an
    inter-sample maximum when nearby samples are known.

    f is a vector and x is an index for that vector.

    Returns (vx, vy), the coordinates of the vertex of a parabola that goes
    through point x and its two neighbors.

    Example:
    Defining a vector f with a local maximum at index 3 (= 6), find local
    maximum if points 2, 3, and 4 actually defined a parabola.

    In [3]: f = [2, 3, 1, 6, 4, 2, 3, 1]

    In [4]: parabolic(f, argmax(f))
    Out[4]: (3.2142857142857144, 6.1607142857142856)

    """
def parabolic(f: list[float], x: int) -> tuple[float, float] | None {
    if ((x < 1) or ((x + 1) >= len(f))) {
        return None;
    }
    denom = (f[(x - 1)] - (2 * f[x])) + f[(x + 1)];
    if (denom == 0.0) {
        return None;
    }
    xv = (((1 / 2.0) * (f[(x - 1)] - f[(x + 1)])) / denom) + x;
    yv = f[x] - ((1 / 4.0) * (f[(x - 1)] - f[(x + 1)]) * (xv - x));
    return (xv, yv);
}

"""
    Convert bytes to KB/MB/GB/TB/s
    """
def format_bytes(size: int | float) -> str {
    power = 2 ** 10;
    n = 0;
    power_labels: dict[int, str] = {0: 'B/s', 1: 'KB/s', 2: 'MB/s', 3: 'GB/s', 4: 'TB/s'};
    while (size > power) {
        size /= power;
        n += 1;
    }
    return " ".join((str(round(size, 2)), power_labels[n]));
}

"""Convert SipHash24 output to Py_hash_t
    """
def pysiphash(uint64: int) -> object {
    assert (0 <= uint64 < (1 << 64));
    if (uint64 > ((1 << 63) - 1)) {
        int64: int = uint64 - (1 << 64);
    } else {
        int64: int = uint64;
    }
    uint32: int = (uint64 ^ (uint64 >> 32)) & 4294967295;
    if (uint32 > ((1 << 31) - 1)) {
        int32: int = uint32 - (1 << 32);
    } else {
        int32: int = uint32;
    }
    return (int32, int64);
}

"""
    Get the smallest divisible number by all [1..max_factor] numbers by brute force.
    """
def get_smallest_divisible_number_brute_force(max_factor: int) -> int {
    number_i: int = max_factor;
    while True {
        divisible = True;
        for factor_i in range(1, (max_factor + 1)) {
            if ((number_i % factor_i) > 0) {
                divisible = False;
                break;
            }
        }
        if divisible {
            return number_i;
        }
        number_i += 1;
    }
}

def is_false(v: bool | str | int | None, chk_none: bool = True) -> bool {
    if isinstance(v, str) {
        v = v.lower();
    }
    chk: list[bool | str | int | None] = [False, 'false', 'no', 'n', '0', 0];
    if chk_none {
        chk = chk + [None, 'none', 'null', ''];
    }
    return (v in chk);
}

def map_ips_from_nodes(
    all_nodes: list[dict[str, str | int | list | dict | None]]
) -> dict[str, dict[str, str | int | None]] {
    filtered_node_ips: dict[str, dict[str, str | int | None]] = {};
    for `node in all_nodes {
        node_ips: dict[str, dict[str, str | int | None]] = {};
        for alloc in `node['relationships']['allocations']['data'] {
            ip = alloc['attributes']['ip'];
            alias = alloc['attributes']['alias'];
            if (ip not in node_ips) {
                node_ips[ip] = {
                    'node_id': (`node['id'] as str | int | None),
                    'node_fqdn': (`node['fqdn'] as str | int | None),
                    'alias': (alias as str | int | None),
                    'total_allocs': 0,
                    'used_allocs': 0
                };
            }
            if alloc['attributes']['assigned'] {
                node_ips[ip]['used_allocs'] += 1;
            }
            node_ips[ip]['total_allocs'] += 1;
        }
        filtered_node_ips.update(node_ips);
    }
    return filtered_node_ips;
}

"""
    PR(p) = ( (1-d) / n ) + ( d * sum( PR(i) / NumLinks(i) ) )
                                   i
    d = dampening number; n = # of possible pages; p = page; i = incoming pages
    """
def iter_algorithm(d: float, n: int, p: str, corpus: dict[str, list[str]], pr: dict[str, float]) -> float {
    page_sum = 0.0;
    for i in corpus {
        if (p in corpus[i]) {
            page_sum += pr[i] / len(corpus[i]);
        }
    }
    return (((1 - d) / n) + (d * page_sum));
}

import from next.headers { cookies }
import from lib.auth { getSessionToken, validateSessionToken }

import from typing { TypedDict }

class SessionResult(TypedDict) {
    has user: object | None,
        session: object | None;
}

async def:pub getCurrentSession -> SessionResult {
    cookieStore = await cookies();
    token: str | None = getSessionToken(cookieStore);
    if not token {
        return {"user": None, "session": None};
    }
    validationResult: SessionResult = await validateSessionToken(token);
    return validationResult as SessionResult;
}

