""" (list) -> float

    Sum up the values in a nested numbers list
    """
def r_sum(nested_num_list: list) -> int | float {
    cntr: int | float = 0;
    for elem in nested_num_list {
        if isinstance(elem, `list) {
            cntr += r_sum(elem as list);
        } elif isinstance(elem, int) {
            cntr += elem;
        } elif isinstance(elem, float) {
            cntr += elem;
        } else {
            raise TypeError('Invalid value found in list: {0}'.format(elem as object));
        }
    }
    return cntr;
}

"""A function for testing approximate equality of two numbers.
    Same as math.isclose in Python v3.5 (and newer)
    https://www.python.org/dev/peps/pep-0485
    """
def almost_equal(a: float, b: float, rel_tol: float = 1e-09, abs_tol: float = 0.0) -> bool {
    return (abs((a - b)) <= max((rel_tol * max(abs(a), abs(b))), abs_tol));
}

""" stretches the samples to cover a range of width 2**bits,
    so we can convert to ints later.
    """
def stretch(audio: list[float], byte_width: int) -> list[float] {
    audio * (((2 ** ((8 * byte_width) - 1)) as int) - 1)
}

"""Count the lead indent of a string"""
def leading_indent(text: str | list) -> object {
    if not isinstance(text, `list) {
        text = (text as str).splitlines(True);
    }
    for line in text as list {
        if (line as str).strip() {
            return (len(line as str) - len((line as str).lstrip()));
        }
    }
    return 0;
}

"""Currently just filters by max y distance between rows"""
def filter_toks(tokens: list[dict], min_y: int, max_y_dist: int) -> object {
    row_intervals: list[list[int]] = sorted(
        [
            [(t['top'] as int), ((t['top'] as int) + (t['height'] as int))]
            for t in tokens
            if ((t['conf'] as float) > 0.2)
        ]
    );
    row_intervals.sort(key=lambda (interval: list) { (interval[0] as int); });
    row_ranges: list[list[int]] = row_intervals;
    for current in row_intervals {
        previous = row_ranges[-1];
        if (current[0] - previous[1]) {
            continue;
        }
        if (current[0] <= previous[1]) {
            previous[1] = max(previous[1], current[1]);
        } else {
            row_ranges.append(current);
        }
    }
    if (len(row_ranges) <= 1) {
        return tokens;
    }
    (prev_top, prev_bottom) = (0, min_y);
    new_ranges: list[list[int]] = [];
    for (row_top, row_bottom) in row_ranges {
        if (abs((row_top - prev_bottom)) > max_y_dist) {
            break;
        } else {
            new_ranges.append([row_top, row_bottom]);
            (prev_top, prev_bottom) = (row_top, row_bottom);
        }
    }
    new_tokens: list[dict] = [];
    for token in tokens {
        for (row_top, row_bottom) in new_ranges {
            if (
                ((token['top'] as int) >= row_top)
                and (((token['top'] as int) + (token['height'] as int)) <= row_bottom)
            ) {
                new_tokens.append(token);
                break;
            }
        }
    }
    return new_tokens;
}

"""
    check if sudoku board is true by checking that the same number didn't appear more than one in its row, col,
    surrounding 3*3 sub matrix
    """
def sudoku2(grid: list[list[str]]) -> bool {
    for i in range(9) {
        for j in range(9) {
            if (((i % 3) == 0) and ((j % 3) == 0)) {
                l: list[str] = [
                    grid[s_i][s_j] for s_i in range(i, (i + 3))
                    for s_j in range(j, (j + 3))
                    if grid[s_i][s_j].isdigit()
                ];
                if (len(`set(l)) != len(l)) {
                    return False;
                }
            }
            if grid[i][j].isdigit() {
                if (grid[i].count(grid[i][j]) > 1) {
                    return False;
                }
                if ((`list(zip(*grid)) as list[list[str]])[j].count(grid[i][j]) > 1) {
                    return False;
                }
            }
        }
    }
    return True;
}

"""
    Coerce a field_name (which may be a callable) to a string.
    """
obj _FieldNameCallable {
    has __name__: str;
}

def _coerce_field_name(field_name: object, field_index: int) -> object {
    if callable(field_name) {
        if ((field_name as _FieldNameCallable).__name__ == '<lambda>') {
            return ('lambda' + str(field_index));
        }
        return (field_name as _FieldNameCallable).__name__;
    }
    return field_name;
}

""" Dimension for search implied by a skater name """
def implied_r(f: str | type) -> object {
    name: str;
    if isinstance(f, str) {
        name = f;
    } else {
        name = (f as type).__name__;
    }
    if ('_r2' in name) {
        return 2;
    } elif ('_r3' in name) {
        return 3;
    } elif ('_r1' in name) {
        return 1;
    } else {
        return 0;
    }
}

"""
    maxmin_unnormalize data.

    :param data: ndarray, data.
    :return: ndarray
    """
def traffic_data_maxmin_unnormalize(
    data: float | int, max_value: float | int = 100, min_value: float | int = 0
) -> object {
    if (max_value > 0) {
        scaler = max_value - min_value;
        data = (data * scaler) + min_value;
    }
    return data;
}

"""
    Split text into arguments and parse each of them to an appropriate format (int, float or string)
    Args:
        line: text line
        splitter: value to split by
    Returns: list of arguments
    """
def interpret_line(line: str, splitter: str = ',') -> list[int | float | str] {
    parsed: list[int | float | str] = `list();
    elms = line.split(splitter);
    for elm in elms {
        el: int | float | str;
        try {
            el = int(elm);
        } except ValueError {
            try {
                el = float(elm);
            } except ValueError {
                el = elm.strip();
            }
        }
        parsed.append(el);
    }
    return parsed;
}

"""
    Returns a string representation of `x` formatted with precision `p`.

    Based on the webkit javascript implementation taken
    `from here <https://code.google.com/p/webkit-mirror/source/browse/JavaScriptCore/kjs/number_object.cpp>`_,
    and implemented by `randlet <https://github.com/randlet/to-precision>`_.
    """
def precision(x: int | float, p: int) -> str {
    import math;
    x = float(x);
    if (x == 0.0) {
        return ("0." + ("0" * (p - 1)));
    }
    out: list[str] = [];
    if (x < 0) {
        out.append("-");
        x = -x;
    }
    e: int = int(math.log10(x));
    tens: float = math.pow(10, ((e - p) + 1)) as float;
    n: float = math.floor((x / tens)) as float;
    if (n < math.pow(10, (p - 1))) {
        e = e - 1;
        tens = math.pow(10, ((e - p) + 1)) as float;
        n = math.floor((x / tens)) as float;
    }
    if (abs((((n + 1.0) * tens) - x)) <= abs(((n * tens) - x))) {
        n = n + 1;
    }
    if (n >= math.pow(10, p)) {
        n = n / 10.0;
        e = e + 1;
    }
    m: str = "%.*g" % (p, n);
    if ((e < -2) or (e >= p)) {
        out.append(m[0]);
        if (p > 1) {
            out.append(".");
            out.extend(m[1:p]);
        }
        out.append("e");
        if (e > 0) {
            out.append("+");
        }
        out.append(str(e));
    } elif (e == (p - 1)) {
        out.append(m);
    } elif (e >= 0) {
        out.append(m[:(e + 1)]);
        if ((e + 1) < len(m)) {
            out.append(".");
            out.extend(m[(e + 1):]);
        }
    } else {
        out.append("0.");
        out.extend((["0"] * -(e + 1)));
        out.append(m);
    }
    return "".join(out);
}

""" parse a string of format chr:start-end:strand and return a 4-tuple
    Strand defaults to + and end defaults to start+23
    """
def parsePos(text: str | None) -> tuple[str, int, int, str] {
    chrom: str;
    start: int;
    end: int;
    strand: str;
    if ((text is not None) and (len(text) != 0) and (text != "?")) {
        fields = text.split(":");
        if (len(fields) == 2) {
            (chrom, posRange) = fields;
            strand = "+";
        } else {
            (chrom, posRange, strand) = fields;
        }
        posRange = posRange.replace(",", "");
        if ("-" in posRange) {
            (start_raw, end_raw) = posRange.split("-");
            start = int(start_raw);
            end = int(end_raw);
        } else {
            start = int(posRange);
            end = start + 23;
        }
    } else {
        (chrom, start, end, strand) = ("", 0, 0, "+");
    }
    return (chrom, start, end, strand);
}

"""Get the catalog path for the designated layer if possible. Ensures we can pass map layers to the subprocess.

    If it's already a string, assume it's a catalog path and return it as is.

    Args:
        layer (layer object or string): Layer from which to retrieve the catalog path.

    Returns:
        string: Catalog path to the data
    """
def get_catalog_path(layer: object) -> object {
    if hasattr(layer, "dataSource") {
        return getattr(layer, "dataSource");
    }
    return layer;
}

"""
    marks: list of marks of students in integer

    Return average marks of students
    """
def grader(marks: list[int]) -> object {
    try {
        assert not (len(marks) == 0) , 'list cannot be empty';
    } except AssertionError as ae {
        print(f'AssertionError: {ae}');
        return 0.0;
    } else {
        sum = 0;
        for m in marks {
            sum += m;
        }
        return (sum / len(marks));
    }
}

"""
    Return the index of the (first) maximum in seq

    >>> assert maxloc([1,3,2,3]) == 1
    """
def maxloc(seq: list) -> int {
    best: tuple[int, any] = max(enumerate(seq), key=lambda (s: tuple[int, any]) { s[1]; });
    return best[0];
}

